INSERT INTO chk_versiones (version, descripcion, fecha_generacion, vigente) VALUES ('v6', 'Checklist v6: Anexo 3, procesos de la v2, cruce Res. 3100 vs 1403/2955, habilitación y vacíos prioritarios', '2026-10-20', false);

