INSERT INTO chk_guia_obligacion (version, cumple, no_cumple, no_aplica, fuente) VALUES ('v6', 'Cumple si · la evidencia revisada demuestra que el prestador cumplió la obligación de manera satisfactoria y dentro de los parámetros de calidad y oportunidad exigidos durante el periodo verificado.', 'No cumple si · la evidencia muestra que el prestador no dio cumplimiento a la obligación, en todo o en parte, durante el periodo evaluado.', 'No aplica si · la obligación está sujeta a hechos o condiciones particulares que no se dieron en el periodo verificado, por lo que no era exigible.', 'Anexo 3 p.6');

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C00', 'Validación de soportes de habilitación', 'Se califica Está habilitado / No está habilitado (No aplica solo en las validaciones condicionadas). Si la inscripción o el servicio no están habilitados, se registra si el prestador presenta el soporte de inscripción en el REPS: con soporte, la habilitación está en trámite y no es hallazgo; sin soporte, es hallazgo y se notifica al OPL. Las instituciones del SSFM son régimen de excepción y se acogen al SOGCS de forma voluntaria (Anexo 3 p.6).', 'Habilitación', NULL, '{"C":"Está habilitado","NC":"No está habilitado"}'::jsonb, 'Está habilitado si', ARRAY['ESM', 'FA']::text[], 'Res. 3100/2019 Arts. 4, 7, 8 y 10; Res. 1403/2007 Art. 22-23; Res. 2955/2007 Art. 2', 1) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('HB-01', 'Prestador inscrito en el REPS con la sede visitada', 'Está habilitado si · el prestador figura inscrito en el Registro Especial de Prestadores de Servicios de Salud (REPS) con la sede visitada, sede con infraestructura física y código de inscripción asignado por la secretaría de salud departamental o distrital, o la entidad que tenga a cargo dichas competencias.', 'Res. 3100/2019 Art. 4 (p.3), modificado por Res. 465/2025 Art. 1 (p.2); Res. 3100/2019 Art. 8 num. 8.3 y 8.5 (p.4-5)', 'cruce', 'Todo prestador de servicios de salud debe estar inscrito en el REPS, registrando como mínimo una sede con infraestructura física y por lo menos un servicio habilitado. La secretaría de salud departamental o distrital asigna el código de inscripción y registra la inscripción.', 'Consulta del REPS y constancia de habilitación expedida por la secretaría de salud departamental o distrital.', 'No aplica a la farmacia alterna que sea solo establecimiento farmacéutico (se autoriza, no se habilita).', NULL, NULL, NULL::jsonb, '{"pregunta":"¿El prestador presenta el soporte de inscripción en el REPS?","guia":"Para prestadores que aún no han tenido su primera visita de verificación (la inscripción de una IPS nueva y los servicios de alta complejidad dependen de la visita previa): el formulario de inscripción del REPS diligenciado e impreso, radicado ante la secretaría de salud departamental o distrital con la declaración de autoevaluación de cada servicio.","opciones":{"SI":"Presenta el soporte de inscripción","NO":"No presenta el soporte"},"efecto":{"SI":"Habilitación en trámite ante la secretaría de salud: no genera hallazgo.","NO":"Hallazgo: no está habilitado ni reportado ante el REPS. Se notifica al OPL."},"fuente":"Res. 3100/2019 Art. 7 num. 7.1.3, 7.1.4, 7.1.5 y 7.2 (p.4); Art. 8 num. 8.4 (p.4); Manual 9.3 inc. 3-4 (p.40)"}'::jsonb, 1),
    ('HB-02', 'Servicio farmacéutico habilitado en la sede, con la complejidad y las modalidades que presta', 'Está habilitado si · en el REPS el servicio farmacéutico figura habilitado en la sede visitada, con la complejidad y las modalidades que efectivamente se prestan.', 'Res. 3100/2019 Art. 7 num. 7.1.2 (p.4); Art. 8 num. 8.5 (p.5); Manual 11.3.2 (p.97)', 'cruce', 'El prestador determina el o los servicios a habilitar, la complejidad, la modalidad y la capacidad instalada. La secretaría expide la constancia de habilitación, desde la cual el servicio se considera habilitado y puede ofertarse y prestarse.', 'Consulta del REPS (servicios habilitados por sede) y constancia de habilitación.', 'No aplica a la farmacia alterna que sea solo establecimiento farmacéutico.', NULL, NULL, NULL::jsonb, '{"pregunta":"¿El prestador presenta el soporte de inscripción en el REPS?","guia":"Para prestadores que aún no han tenido su primera visita de verificación (la inscripción de una IPS nueva y los servicios de alta complejidad dependen de la visita previa): el formulario de inscripción del REPS diligenciado e impreso, radicado ante la secretaría de salud departamental o distrital con la declaración de autoevaluación de cada servicio.","opciones":{"SI":"Presenta el soporte de inscripción","NO":"No presenta el soporte"},"efecto":{"SI":"Habilitación en trámite ante la secretaría de salud: no genera hallazgo.","NO":"Hallazgo: no está habilitado ni reportado ante el REPS. Se notifica al OPL."},"fuente":"Res. 3100/2019 Art. 7 num. 7.1.3, 7.1.4, 7.1.5 y 7.2 (p.4); Art. 8 num. 8.4 (p.4); Manual 9.3 inc. 3-4 (p.40)"}'::jsonb, 2),
    ('HB-03', 'Inscripción vigente o renovada, sin inactivación', 'Está habilitado si · la inscripción está vigente (inicial de cuatro años o renovación anual con la autoevaluación declarada en el REPS antes del vencimiento) y ni el prestador ni el servicio farmacéutico están inactivados.', 'Res. 3100/2019 Art. 10 (p.5); Art. 11 (p.5-6)', 'cruce', 'La inscripción inicial tiene vigencia de cuatro años y se renueva por un año con la autoevaluación declarada en el REPS. Sin autoevaluación se inactiva la inscripción o el servicio.', 'Consulta del REPS: fecha de inscripción, renovaciones y estado del prestador y del servicio.', 'No aplica a la farmacia alterna que sea solo establecimiento farmacéutico.', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('HB-04', 'Distintivo de habilitación del servicio farmacéutico', 'Está habilitado si · el distintivo de habilitación del servicio farmacéutico generado en el REPS está publicado en un lugar visible.', 'Res. 3100/2019 Art. 8 num. 8.5 (p.5); Manual 9.3.2.1 (p.40)', 'cruce', '', 'Distintivo de habilitación (observación).', 'No aplica a la farmacia alterna que sea solo establecimiento farmacéutico.', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('HB-05', 'Farmacia alterna: autorización de funcionamiento de la entidad territorial de salud', 'Está habilitado si · la farmacia alterna presenta el acto de autorización de funcionamiento expedido por la entidad territorial de salud, referido a los procesos que realiza.', 'Res. 1403/2007 Art. 22 num. 2 lit. b (p.12); Art. 23 num. 2 (p.13)', 'cruce', 'Las entidades territoriales de salud autorizan el funcionamiento de los establecimientos farmacéuticos (farmacia-droguería y droguería, entre otros). La autorización se refiere a los procesos para los cuales están autorizados.', 'Acto de autorización de funcionamiento de la entidad territorial de salud.', '', 'Solo farmacia alterna', NULL, NULL::jsonb, NULL::jsonb, 5),
    ('HB-06', 'Farmacia alterna: certificado de distancia', 'Está habilitado si · la farmacia alterna (farmacia-droguería o droguería) obtuvo de la autoridad competente el certificado de distancia antes de iniciar su funcionamiento.', 'Res. 2955/2007 Art. 2 (p.2-3), que modifica Res. 1403/2007 Manual T.I Cap.III num. 2.1 lit. a', 'cruce', 'Para el funcionamiento de los establecimientos farmacéuticos minoristas se debe obtener previamente, por parte de la autoridad competente, el certificado de distancia.', 'Certificado de distancia.', '', 'Solo farmacia alterna', NULL, NULL::jsonb, NULL::jsonb, 6),
    ('HB-07', 'Farmacia alterna: autorización de la entidad territorial para inyectología o glicemia', 'Está habilitado si · existe autorización de la entidad territorial de salud para cada procedimiento (inyectología, monitoreo de glicemia) que la farmacia alterna ofrece.', 'Dec. 780/2016 Art. 2.5.3.10.23 (p. 296); Res. 1403/2007 Manual T.I Cap.V num. 1 lit. b (p.34); num. 2 lit. b (p.40)', 'cruce', '', 'Autorización de la entidad territorial de salud para los procedimientos.', '', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 7),
    ('HB-08', 'Certificado de Buenas Prácticas de Elaboración del Invima (mezclas o reempaque en dosis unitaria)', 'Está habilitado si · existe certificado vigente del Invima que cubre los procesos de mezcla, adecuación y ajuste de dosis o reempaque y reenvase en dosis unitaria que se realizan, en central propia o contratada.', 'Res. 3100/2019 Manual 11.3.2, Medicamentos num. 13 (p.99-100); Res. 1403/2007 Art. 23 num. 3 lit. a (p.13-14)', 'cruce', 'Las preparaciones, la adecuación y ajuste de concentraciones y el reempaque y reenvase dentro del SDMDU requieren el Certificado de Cumplimiento de Buenas Prácticas de Elaboración del Invima.', 'Certificado de BPE del Invima (procesos certificados y fecha); si la central es contratada, el del contratista.', '', 'Solo si el punto o su central contratada hace mezclas, ajustes de dosis o reempaque en dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 8),
    ('HB-09', 'Resolución del Fondo Nacional de Estupefacientes para medicamentos de control especial', 'Está habilitado si · el prestador que realiza actividades con medicamentos de control especial tiene la resolución de autorización vigente del Fondo Nacional de Estupefacientes o la entidad que haga sus veces.', 'Res. 3100/2019 Manual 11.1.4 num. 5 (p.72)', 'cruce', '', 'Resolución de autorización vigente del Fondo Nacional de Estupefacientes.', '', 'Solo si maneja medicamentos de control especial', NULL, NULL::jsonb, NULL::jsonb, 9)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C01', 'Seguimiento a la operación del OPL', 'Reportes de la herramienta, pendientes, PQRSR, personal del OPL, niveles de servicio e información reportada.', NULL, NULL, NULL, NULL, ARRAY['ESM', 'FA']::text[], 'Anexo 3 p.4, p.13-14, p.16', 2) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('SO-01', 'Reportes de la herramienta tecnológica del OPL consistentes, oportunos y de calidad', 'Cumple si · los reportes de la herramienta tecnológica del OPL revisados son consistentes, oportunos y de calidad, y la información de dispensación, novedades operativas y estados de cumplimiento está correctamente cargada y transmitida.', 'Anexo 3 p.13 num. 1', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('SO-02', 'Medicamentos pendientes resueltos dentro de los tiempos del contrato', 'Cumple si · los medicamentos pendientes revisados se resolvieron dentro de los tiempos establecidos en el contrato de medicamentos y en los estándares definidos por DIGSA.', 'Anexo 3 p.13 num. 4; p.14', 'anexo3', NULL, NULL, NULL, NULL, NULL, '[{"label":"Pendientes en el periodo","unidad":"n.º"},{"label":"Pendientes fuera de término","unidad":"n.º"}]'::jsonb, NULL::jsonb, 2),
    ('SO-03', 'Trazabilidad de pendientes verificada con el usuario', 'Cumple si · en los casos revisados, la entrega de los medicamentos pendientes se confirmó con el usuario.', 'Anexo 3 p.14', 'anexo3', NULL, NULL, NULL, NULL, NULL, '[{"label":"Usuarios contactados","unidad":"n.º"},{"label":"Entregas no confirmadas","unidad":"n.º"}]'::jsonb, NULL::jsonb, 3),
    ('SO-04', 'Respuestas del OPL a las PQRSR veraces, oportunas y efectivas', 'Cumple si · las respuestas del OPL a las PQRSR revisadas, validadas directamente con los usuarios involucrados, son veraces, oportunas y resolvieron efectivamente los casos.', 'Anexo 3 p.13 num. 2; p.14', 'anexo3', NULL, NULL, NULL, NULL, NULL, '[{"label":"PQRSR revisadas","unidad":"n.º"},{"label":"PQRSR con respuesta fuera de término","unidad":"n.º"}]'::jsonb, NULL::jsonb, 4),
    ('SO-05', 'Novedades del personal contratado por el OPL para el punto', 'Cumple si · los cambios, rotaciones, ausencias o reemplazos del personal del OPL en el punto fueron notificados oportunamente y no afectan la continuidad del servicio.', 'Anexo 3 p.13 num. 3', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('SO-06', 'Indicadores de pendientes de la modalidad de dispensación y suministro', 'Cumple si · los indicadores de pendientes de dispensación y suministro, y los tiempos máximos de resolución de pendientes en ESM de suministro, cumplen lo establecido en el contrato de medicamentos.', 'Anexo 3 p.14', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('SO-07', 'Novedades reportadas por DIGSA, DISANES o JEFSA verificadas', 'Cumple si · al verificar las novedades o el incumplimiento de indicadores reportados por DIGSA, DISANES o JEFSA, no se confirma incumplimiento del OPL.', 'Anexo 3 p.14', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 7),
    ('SO-08', 'Coherencia entre lo ofertado por el OPL y lo ejecutado en la operación', 'Cumple si · lo ejecutado en la operación corresponde a lo ofertado por el OPL.', 'Anexo 3 p.16', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 8),
    ('SO-09', 'Procedimientos, flujos, indicadores, tiempos de respuesta y niveles de servicio implementados', 'Cumple si · los procedimientos, flujos operativos, indicadores, tiempos de respuesta, niveles de servicio y mecanismos de control de los documentos contractuales están implementados correctamente.', 'Anexo 3 p.16', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('SO-10', 'Calidad, oportunidad y veracidad de la información reportada', 'Cumple si · la información reportada por el OPL es de calidad, oportuna y veraz, y cumple los criterios de trazabilidad, interoperabilidad, seguridad de la información y control de riesgos del contrato.', 'Anexo 3 p.16', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 10),
    ('SO-11', 'Oportunidad y racionalidad de los servicios', 'Cumple si · los servicios revisados se prestaron de manera oportuna y racional.', 'Anexo 3 p.4 (definición de auditoría de procesos)', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 11)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C02', 'Seguimiento a planes de mejoramiento', 'Aplica si la visita es de seguimiento a un plan o si el punto tiene un plan vigente.', NULL, 'plan', NULL, NULL, ARRAY['ESM', 'FA', 'NC']::text[], 'Anexo 3 p.11-12', 3) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('PM-01', 'Plan de mejoramiento presentado dentro de los 5 días hábiles', 'Cumple si · el OPL presentó el plan dentro de los 5 días hábiles siguientes a la comunicación del hallazgo, o dentro del plazo mayor motivado por la interventoría.', 'Anexo 3 p.11', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('PM-02', 'Plan con el contenido mínimo exigido', 'Cumple si · el plan contiene todo lo siguiente: (i) hallazgo y causas; (ii) acciones correctivas o de mejora; (iii) responsables; (iv) cronograma con fechas de inicio y fin; (v) indicadores o criterios objetivos de verificación.', 'Anexo 3 p.11', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('PM-03', 'Acciones del plan implementadas', 'Cumple si · al vencimiento del plazo definido se constata el cumplimiento de las acciones propuestas.', 'Anexo 3 p.11-12', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('PM-04', 'Plan eficaz: el hallazgo que lo originó está subsanado', 'Cumple si · el plan fue eficaz para subsanar el hallazgo que le dio origen. Si no, se reporta a DIGSA y puede exigirse un nuevo plan con medidas más exigentes.', 'Anexo 3 p.12', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 4)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C03', 'Nivel central del OPL', '', NULL, NULL, NULL, NULL, ARRAY['NC']::text[], 'Anexo 3 p.13', 4) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('NC-01', 'Gestión de inventarios', 'Cumple si · la gestión de inventarios del nivel central se ajusta a lo establecido en el contrato de medicamentos y sus anexos.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('NC-02', 'Trazabilidad', 'Cumple si · la trazabilidad de los medicamentos se ajusta a lo establecido en el contrato de medicamentos y sus anexos.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('NC-03', 'Mecanismos de control interno', 'Cumple si · los mecanismos de control interno se ajusta a lo establecido en el contrato de medicamentos y sus anexos.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('NC-04', 'Calidad del cargue de información', 'Cumple si · el cargue de información se ajusta a lo establecido en el contrato de medicamentos y sus anexos.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('NC-05', 'Interoperabilidad de las plataformas tecnológicas', 'Cumple si · la interoperabilidad de las plataformas tecnológicas se ajusta a lo establecido en el contrato de medicamentos y sus anexos.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('NC-06', 'Procesos financieros y de facturación', 'Cumple si · la ejecución de los procesos financieros y de facturación se ajusta a lo establecido en el contrato de medicamentos y sus anexos.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('NC-07', 'Procesos centralizados para la planeación de la operación', 'Cumple si · la operación de los procesos técnicos, jurídicos, tecnológicos y económicos centralizados se ajusta a lo establecido en el contrato de medicamentos y sus anexos.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 7),
    ('NC-08', 'Cumplimiento contractual', 'Cumple si · la gestión del nivel central se ajusta a lo establecido en el contrato de medicamentos y sus anexos.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 8)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C04', 'Farmacia alterna', '', NULL, NULL, NULL, NULL, ARRAY['FA']::text[], 'Anexo 3 p.12-13', 5) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('FA-01', 'Existencia y operación real del punto alterno', 'Cumple si · el punto alterno existe en la dirección registrada y está operando.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('FA-02', 'Disponibilidad de medicamentos', 'Cumple si · hay disponibilidad de los medicamentos para su entrega a los usuarios.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('FA-03', 'Oportunidad en la entrega de medicamentos', 'Cumple si · las entregas revisadas fueron oportunas.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('FA-04', 'Calidad del servicio prestado a los usuarios del SSFM', 'Cumple si · la calidad del servicio prestado a los usuarios del SSFM corresponde a la ofertada.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('FA-05', 'Condiciones técnicas, operativas y de infraestructura ofertadas por el operador', 'Cumple si · las condiciones técnicas, operativas y de infraestructura observadas corresponden a las ofertadas por el operador.', 'Anexo 3 p.13', 'anexo3', NULL, NULL, NULL, NULL, NULL, NULL::jsonb, NULL::jsonb, 5)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C05', 'Capacidad instalada e infraestructura', '', 'Procesos auditados', NULL, NULL, NULL, ARRAY['ESM', 'FA']::text[], 'Anexo 5 p.10 (capacidad instalada) · validaciones de la v2', 6) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('I01-01', 'Infraestructura acorde con complejidad, procesos, volumen de actividades y personal', 'Cumple si · los espacios observados permiten realizar todos los procesos que el servicio/establecimiento realiza y alojar al personal que labora, en proporción a su complejidad y volumen de actividades.', 'Dec. 780/2016 Art. 2.5.3.10.8 num. 1 (p. 286); Dec. 780/2016 Art. 2.5.3.10.11 par. 3 (p. 288); Res. 1403/2007 Manual T.I Cap.I num. 3 lit. a (p.21); T.I Cap.III num. 2 inc. 2 (p.30), sustituido por Res. 2955/2007 Art. 1 (p.1-2); Res. 1403/2007 Manual T.I Cap.II num. 1 (p.23)', 'v2', 'El servicio o establecimiento farmacéutico dispone de una infraestructura física (estructura y dimensiones) acorde con su grado de complejidad, el número de actividades y/o procesos que realiza, el volumen de actividades y el número de personas que laboran.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('I01-02', 'Ubicación independiente y área física exclusiva del establecimiento', 'Cumple si · el área es de uso exclusivo del servicio/establecimiento farmacéutico (no compartida con otras actividades) y, en farmacias-droguerías y droguerías, el local no se comunica con vivienda ni con otro establecimiento comercial.', 'Dec. 780/2016 Art. 2.5.3.10.11 par. 3 (p. 288); Res. 1403/2007 Manual T.I Cap.II num. 1.1 (p.23); Res. 1403/2007 Manual T.I Cap.V num. 1 lit. b inc. final (p.34); num. 2 lit. b inc. final (p.40)', 'v2', 'El local tiene ubicación independiente y área física exclusiva e independiente para el servicio/establecimiento farmacéutico. La farmacia-droguería y la droguería están ubicadas en un lugar independiente de cualquier habitación (vivienda) u otro establecimiento comercial.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('I01-03', 'Local de circulación restringida y seguro', 'Cumple si · el acceso a las áreas internas del servicio/establecimiento está restringido al personal autorizado y el local presenta condiciones de seguridad.', 'Dec. 780/2016 Art. 2.5.3.10.11 par. 3 (p. 288); Res. 1403/2007 Manual T.I Cap.II num. 1.1 (p.23)', 'v2', 'El área del servicio/establecimiento farmacéutico es de circulación restringida y segura.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('I01-04', 'Ubicación de fácil acceso para los usuarios', 'Cumple si · el verificador constata que el acceso de los usuarios al servicio/establecimiento es fácil.', 'Dec. 780/2016 Art. 2.5.3.10.11 par. 3 (p. 288); Res. 1403/2007 Manual T.I Cap.II num. 1 (p.23); Res. 1403/2007 Manual T.I Cap.V num. 1 lit. b inc. final (p.34); num. 2 lit. b inc. final (p.40)', 'v2', 'El servicio/establecimiento farmacéutico está ubicado en un sitio de fácil acceso para los usuarios; el SF hospitalario está en un área de la IPS de fácil acceso.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('I01-05', 'Ubicación alejada de fuentes de contaminación (y de ruido excesivo en SF de IPS)', 'Cumple si · no se observan fuentes de alta contaminación contiguas a las áreas de almacenamiento y, en SF de IPS, el servicio no está junto a fuentes de contaminación o de ruido excesivo.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. a (p.46); Res. 1403/2007 Manual T.I Cap.II num. 1 (p.23)', 'v2', 'Las áreas de almacenamiento están alejadas de sitios de alta contaminación, para conservar adecuadamente los dispositivos médicos y la estabilidad de los medicamentos. El SF hospitalario (y el ambulatorio de IPS en instalaciones separadas) está alejado de fuentes de contaminación o ruido excesivo.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('I01-06', 'Circulaciones libres que faciliten el movimiento de personas, objetos y equipos', 'Cumple si · las circulaciones y puertas permiten el paso de personas, objetos y equipos sin obstáculos.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. b (p.46); Res. 3100/2019 Manual 11.1.2 num. 19 (p.63); Res. 3100/2019 Manual 11.1.2 num. 20 (p.63)', 'v2', 'Las áreas de almacenamiento facilitan la circulación de personas y objetos, con puertas situadas de manera que se facilite dicha circulación. En SF de prestadores inscritos en el REPS, las áreas de circulación están libres de obstáculos de manera que permitan la movilización de pacientes, talento humano, usuarios y equipos biomédicos.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('I01-07', 'Aviso exterior con razón social y mención ''Farmacia-Droguería'' o ''Droguería''', 'Cumple si · existe aviso exterior en letras visibles con la razón o denominación social y la mención ''Farmacia-Droguería'' o ''Droguería'', según corresponda.', 'Res. 1403/2007 Manual T.I Cap.V num. 1 lit. b inc. final (p.34); num. 2 lit. b inc. final (p.40)', 'v2', 'La farmacia-droguería o droguería se identifica con un aviso en letras visibles, ubicado en la parte exterior del local o edificio que ocupa, que expresa la razón o denominación social del establecimiento; la identificación pública incluye la mención ''Farmacia-Droguería'' o ''Droguería'', según corresponda.', 'Aviso exterior (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías', NULL, NULL, NULL::jsonb, NULL::jsonb, 7),
    ('I01-08', 'IPS: entrega ambulatoria cerca del consultorio, de fácil acceso y no peligrosa', 'Cumple si · el punto donde la IPS entrega o dispensa a pacientes ambulatorios no es distante del consultorio, es de fácil acceso y no es peligroso.', 'Res. 1403/2007 Manual T.I Cap.III num. 1 inc. 3 (p.28)', 'v2', 'La IPS no suministra medicamentos y dispositivos médicos a sus pacientes ambulatorios en lugares distantes del consultorio donde se realizó la consulta, de difícil acceso o peligrosos.', 'No definida en la norma (constatación física)', 'Aplica solo a IPS que entregan o dispensan medicamentos y dispositivos médicos a pacientes ambulatorios (directamente o mediante contrato)', NULL, NULL, NULL::jsonb, NULL::jsonb, 8),
    ('I01-09', 'Infraestructura separada y delimitada en edificación compartida con otros prestadores', 'Cumple si · el SF está separado y delimitado físicamente de los demás prestadores y solo comparte los ambientes permitidos según el tipo de edificación.', 'Res. 3100/2019 Manual 11.1.2 num. 3 (p.61); Res. 3100/2019 Manual 11.1.2 num. 6 (p.62); Res. 3100/2019 Manual 11.1.2 num. 7 (p.62)', 'v2', 'Cuando en la edificación funciona más de un prestador, la infraestructura del prestador está separada y delimitada físicamente. En edificaciones de uso exclusivo de salud (prestadores con servicios de consulta externa y apoyo diagnóstico y complementación terapéutica) solo se comparten aseo, salas de espera y unidades sanitarias; en edificaciones de uso mixto solo salas de espera y unidades sanitarias. En edificaciones de uso mixto solo funcionan servicios de consulta externa, de apoyo diagnóstico y complementación terapéutica y de cirugía ambulatoria.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que funcionan en una edificación con más de un prestador', NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('I01-10', 'Ascensor, rampa o sistema alternativo de elevación según pisos de la edificación', 'Cumple si · : en edificación de hasta 3 pisos con el SF en 2.º o 3.er piso existe ascensor, rampa o sistema alternativo de elevación; en edificación de más de 3 pisos existe ascensor.', 'Res. 3100/2019 Manual 11.1.2 num. 8 (p.62); Res. 3100/2019 Manual 11.1.2 num. 10 (p.62)', 'v2', 'Si el SF funciona en el segundo o tercer piso de una edificación de hasta tres pisos (contados a partir del nivel más bajo construido), cuenta con ascensor, rampa o sistema alternativo de elevación. Las edificaciones de más de tres pisos cuentan con ascensor.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS ubicados en 2.º o 3.er piso de edificaciones de hasta 3 pisos, o en edificaciones de más de 3 pisos', NULL, NULL, NULL::jsonb, NULL::jsonb, 10),
    ('I01-11', 'Condiciones del sistema alternativo de elevación', 'Cumple si · el sistema alternativo de elevación cumple las cuatro condiciones (num. 9.1 a 9.4).', 'Res. 3100/2019 Manual 11.1.2 num. 9 (p.62)', 'v2', 'El sistema alternativo de elevación: no interfiere con el acceso y evacuación de los usuarios por las escaleras; está disponible tanto para el acceso como para la evacuación; es de manejo autónomo; y garantiza seguridad durante su uso.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que usan un sistema alternativo de elevación', NULL, NULL, NULL::jsonb, NULL::jsonb, 11),
    ('I01-12', 'Escaleras y rampas con piso antideslizante, pasamanos y protecciones laterales', 'Cumple si · las escaleras o rampas tienen piso uniforme y antideslizante en todo el recorrido, pasamanos y protecciones laterales hacia espacios libres.', 'Res. 3100/2019 Manual 11.1.2 num. 12 (p.62)', 'v2', 'Si hay escaleras o rampas, el piso es uniforme y de material antideslizante (o con elementos que garanticen esta propiedad) en todo su recorrido, con pasamanos a uno o ambos lados y con protecciones laterales hacia espacios libres.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS con escaleras o rampas', NULL, NULL, NULL::jsonb, NULL::jsonb, 12),
    ('I01-13', 'Servicios públicos: agua, energía eléctrica, alcantarillado y comunicaciones', 'Cumple si · los cuatro servicios están disponibles en la edificación.', 'Res. 3100/2019 Manual 11.1.2 num. 13 (p.62)', 'v2', 'La edificación donde se presta el servicio cuenta con suministro de agua, energía eléctrica, conexión a la red de alcantarillado y sistemas de comunicaciones.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 13),
    ('I01-14', 'Planta eléctrica en la edificación donde funciona el servicio farmacéutico', 'Cumple si · la edificación donde funciona el SF cuenta con planta eléctrica.', 'Res. 3100/2019 Manual 11.1.2 num. 14 (p.62)', 'v2', 'La edificación donde se presta el servicio farmacéutico cuenta con planta eléctrica.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 14),
    ('I01-15', 'Señalización y planos de evacuación visibles en cada piso', 'Cumple si · en cada piso hay señalización y planos visibles de rutas de evacuación, salidas de emergencia y puntos de encuentro.', 'Res. 3100/2019 Manual 11.1.2 num. 22 (p.63)', 'v2', 'Cada piso o nivel de la edificación cuenta con señalización y planos indicativos de las rutas de evacuación, salidas de emergencia y puntos de encuentro, visibles al público en general.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 15),
    ('I01-16', 'Alarmas sensibles al humo y extintores en las áreas de almacenamiento', 'Cumple si · en las áreas de almacenamiento hay alarma(s) sensible(s) al humo y extintor(es) de incendios.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. l (p.47)', 'v2', 'En las áreas de almacenamiento de medicamentos y dispositivos médicos se cuenta con alarmas sensibles al humo y extintores de incendios.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 16),
    ('I01-17', 'Certificado de conformidad de las instalaciones eléctricas (prestadores)', 'Cumple si · presenta la certificación que corresponde a la fecha de construcción o adaptación de la edificación (y el plan de ajustes si es anterior a mayo de 2005).', 'Res. 3100/2019 Manual 9.3.4.2 (p.44-45)', 'v2', 'El prestador cuenta con certificado de conformidad de las instalaciones eléctricas: edificación construida antes de mayo de 2005, certificación de profesional competente de que las instalaciones no representan alto riesgo, más plan de ajustes de las instalaciones eléctricas; edificación construida después de mayo de 2005 o adaptada como institución de salud, certificación de organismo de inspección acreditado por la ONAC.', 'Certificación según la fecha de construcción de la edificación; plan de ajustes de las instalaciones eléctricas (edificaciones anteriores a mayo de 2005)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 17),
    ('I01-18', 'Licencia de construcción o documento de reconocimiento de la edificación', 'Cumple si · la IPS (edificación anterior al 2-dic-1996) dispone de la licencia de construcción o del documento de reconocimiento que autoriza el uso en salud, o la entidad con objeto social diferente dispone de la licencia de construcción.', 'Res. 465/2025 Art. 3, par. 2, inc. 2 (p.4)', 'v2', 'Las IPS que funcionan en edificaciones construidas antes del 2 de diciembre de 1996 cuentan con copia de la licencia de construcción o, en su defecto, del documento de reconocimiento de la edificación expedido por autoridad competente que autorice su destinación a la prestación de servicios de salud. Las entidades con objeto social diferente cuentan con licencia de construcción.', 'Copia de la licencia de construcción o del documento de reconocimiento de la edificación', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS (IPS en edificaciones construidas antes del 2-dic-1996 y entidades con objeto social diferente)', NULL, NULL, NULL::jsonb, NULL::jsonb, 18),
    ('I01-19', 'Conectividad certificada para la modalidad de telemedicina', 'Cumple si · la conexión está operativa y existe certificación de conexión a internet que soporte el método (sincrónico o asincrónico) utilizado.', 'Res. 3100/2019 Manual 11.1.2 num. 51.1 / 52.1 / 53.2 (p.67-68); Res. 3100/2019 Manual 9.1.3 c) (p.37-38)', 'v2', 'El SF en modalidad de telemedicina cuenta con conectividad que garantice la prestación con integridad y continuidad según el método de transferencia de información que utilice (sincrónico o asincrónico), soportada en la certificación de conexión a internet.', 'Copia de la certificación de conexión a internet que soporte el método de comunicación sincrónico o asincrónico', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que ofertan la modalidad de telemedicina (prestador remisor o de referencia)', NULL, NULL, NULL::jsonb, NULL::jsonb, 19),
    ('I01-20', 'Sistemas de telecomunicaciones de doble vía en modalidad extramural', 'Cumple si · existe un sistema de telecomunicaciones de doble vía operativo para la modalidad extramural.', 'Res. 3100/2019 Manual 11.1.3 num. 16.1 (p.70)', 'v2', 'En la modalidad extramural, el prestador cuenta con sistemas de telecomunicaciones de doble vía.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que ofertan la modalidad extramural domiciliaria', NULL, NULL, NULL::jsonb, NULL::jsonb, 20),
    ('I01-21', 'Telemedicina: energía o baterías, iluminación homogénea y ambiente exclusivo', 'Cumple si · se verifican todas las condiciones aplicables según el rol del SF en telemedicina (remisor, referencia o referencia exclusiva).', 'Res. 3100/2019 Manual 11.1.2 num. 51.3 / 52.3 / 53.4 (p.67-68); Res. 3100/2019 Manual 11.1.2 num. 51.4 (p.68); 52.4 / 53.5; Res. 3100/2019 Manual 11.1.2 num. 53.1 (p.68)', 'v2', 'En la modalidad de telemedicina: hay suministro de energía eléctrica o baterías que permiten usar los instrumentos de comunicación y los equipos biomédicos necesarios; el nivel de iluminación es homogéneo (en el remisor, luz fluorescente blanca fría sin mezclar iluminación cálida y fría); y, si el prestador es de referencia exclusivo de telemedicina, cuenta con ambiente exclusivo que garantiza privacidad, confidencialidad, seguridad de los equipos frente a extracción no autorizada, condiciones ambientales para su funcionamiento y ausencia de interferencias visuales y sonoras.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS en modalidad de telemedicina (ambiente exclusivo: solo prestadores de referencia exclusivos de telemedicina)', NULL, NULL, NULL::jsonb, NULL::jsonb, 21),
    ('I02-01', 'Orden, aseo, limpieza y desinfección evidentes en todas las áreas', 'Cumple si · al momento de la visita todas las áreas están limpias y ordenadas (y, en prestadores inscritos en el REPS, la desinfección es evidente).', 'Res. 1403/2007 Manual T.I Cap.II num. 1.1 (p.23); Res. 3100/2019 Manual 11.1.2 num. 41 (p.66)', 'v2', 'Los locales permanecen limpios y ordenados. En SF de prestadores inscritos en el REPS, las condiciones de orden, aseo, limpieza y desinfección son evidentes y responden a un proceso dinámico de acuerdo con los servicios prestados.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 22),
    ('I02-02', 'Pisos impermeables, resistentes y uniformes que conserven la calidad de los productos', 'Cumple si · los pisos de todas las áreas presentan las características exigidas (y las adicionales de la Res. 3100 en prestadores inscritos en el REPS).', 'Dec. 780/2016 Art. 2.5.3.10.11 par. 3 (p. 289); Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. a (p.23); T.II Cap.II num. 3.2 lit. c (p.46); Res. 3100/2019 Manual 11.1.2 num. 42 (p.66)', 'v2', 'Los pisos son de material impermeable y resistente (uniforme en las áreas de almacenamiento) y permiten la conservación de la calidad de los medicamentos, dispositivos médicos y demás productos autorizados. En SF de prestadores inscritos en el REPS, además son resistentes a factores ambientales, continuos, antideslizantes, lavables, sólidos y resistentes a procesos de lavado y desinfección, con dilataciones y juntas selladas.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 23),
    ('I02-03', 'Sistema de drenaje de pisos que permita su fácil limpieza y sanitización', 'Cumple si · los pisos del local y de las áreas de almacenamiento cuentan con sistema de drenaje funcional.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. a (p.23); T.II Cap.II num. 3.2 lit. c (p.46)', 'v2', 'Los pisos cuentan con sistema de drenaje que permita su fácil limpieza y sanitización.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 24),
    ('I02-04', 'Paredes, muros, techos y cielos rasos impermeables, sólidos y de fácil limpieza', 'Cumple si · paredes, muros, techos y cielos rasos de todas las áreas presentan las características exigidas (y las adicionales de la Res. 3100 en prestadores inscritos en el REPS).', 'Dec. 780/2016 Art. 2.5.3.10.11 par. 3 (p. 289); Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. c (p.23); T.II Cap.II num. 3.2 lit. e (p.46); Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. b (p.23); T.II Cap.II num. 3.2 lit. d (p.46); Res. 3100/2019 Manual 11.1.2 num. 43 (p.66)', 'v2', 'Las paredes y muros son impermeables, sólidos, de fácil limpieza (y sanitización en áreas de almacenamiento) y resistentes a factores ambientales como humedad y temperatura; los techos y cielos rasos son resistentes, uniformes y de fácil limpieza y sanitización; unos y otros permiten la conservación de la calidad de los productos. En SF de prestadores inscritos en el REPS, cielos rasos, techos y paredes son además lavables, resistentes a factores ambientales, incombustibles y de superficie lisa y continua.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 25),
    ('I02-05', 'Instalaciones eléctricas con plafones en buen estado y cableado protegido', 'Cumple si · no hay cableado expuesto ni tomas, interruptores o plafones en mal estado o desprotegidos.', 'Dec. 780/2016 Art. 2.5.3.10.11 par. 3 (p. 289); Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. f (p.24)', 'v2', 'Las instalaciones eléctricas permiten la conservación de la calidad de los productos: plafones en buen estado y tomas, interruptores y cableado protegidos.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 26),
    ('I02-06', 'Instalaciones sanitarias que permitan conservar la calidad de los productos', 'Cumple si · las instalaciones sanitarias están en condiciones que no ponen en riesgo la calidad de los productos.', 'Dec. 780/2016 Art. 2.5.3.10.11 par. 3 (p. 289)', 'v2', 'Las instalaciones sanitarias permiten la conservación de la calidad de los medicamentos, dispositivos médicos y demás productos autorizados.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías, droguerías, agencias de especialidades farmacéuticas, depósitos de drogas y personas autorizadas', NULL, NULL, NULL::jsonb, NULL::jsonb, 27),
    ('I02-07', 'Unidad sanitaria por sexo: una por cada 15 personas que laboran', 'Cumple si · existe unidad sanitaria por sexo, en proporción de al menos una por cada 15 personas que laboran en el sitio.', 'Res. 1403/2007 Manual T.I Cap.V num. 1.1.3 (p.35)', 'v2', 'La farmacia-droguería (y la droguería, ver nota) cuenta con unidad sanitaria por sexo, en proporción de una por cada quince (15) personas que laboren en el sitio.', 'No definida en la norma (constatación física y número de personas que laboran)', 'Aplica solo a farmacias-droguerías y droguerías (ver nota)', NULL, NULL, NULL::jsonb, NULL::jsonb, 28),
    ('I03-01', 'Área administrativa debidamente delimitada', 'Cumple si · existe área administrativa identificable y delimitada.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.2.1 lit. a (p.24); Cap.IV num. 2.2 lit. a (p.32); Cap.V num. 1.1.2 lit. a (p.35); Res. 3100/2019 Manual 11.3.2, Infra num. 5.1 (p.98)', 'v2', 'Cuenta con área (ambiente) administrativa debidamente delimitada.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 29),
    ('I03-02', 'Área de recepción de medicamentos y dispositivos médicos', 'Cumple si · existe área de recepción identificada, con el alcance que corresponde al tipo de establecimiento.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.2.1 lit. b (p.24); Cap.IV num. 2.2 lit. b (p.32); Cap.V num. 1.1.2 lit. c (p.35); Res. 3100/2019 Manual 11.3.2, Infra num. 5.2 (p.98)', 'v2', 'Cuenta con área de recepción de medicamentos y dispositivos médicos. En DD y AEF incluye productos autorizados; en FD y droguerías es área de recepción y almacenamiento provisional de medicamentos, dispositivos médicos, productos autorizados y materia prima.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 30),
    ('I03-03', 'Área de cuarentena de medicamentos', 'Cumple si · existe área de cuarentena identificada.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.2.1 lit. c (p.24); Cap.IV num. 2.2 lit. c (p.32); Cap.V num. 1.1.2 lit. k (p.35); Res. 3100/2019 Manual 11.3.2, Infra num. 5.8 (p.98)', 'v2', 'Cuenta con área de cuarentena de medicamentos; en farmacias-droguerías y droguerías en ella también pueden almacenarse de manera transitoria los productos retirados del mercado.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 31),
    ('I03-04', 'Área de almacenamiento adecuada a los tipos de productos', 'Cumple si · existe área de almacenamiento con espacio adecuado para los tipos de productos que maneja.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.2.1 lit. d (p.24); Cap.IV num. 2.2 lit. d (p.32–33); Cap.V num. 1.1.2 lit. e (p.35); Res. 3100/2019 Manual 11.3.2, Infra num. 5.4 (p.98)', 'v2', 'Cuenta con área adecuada para el almacenamiento de medicamentos y dispositivos médicos, teniendo en cuenta los tipos de productos que se van a distribuir y/o dispensar.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 32),
    ('I03-05', 'Áreas de almacenamiento independientes, diferenciadas y señalizadas', 'Cumple si · las áreas de almacenamiento están separadas de las demás áreas, diferenciadas y con señalización visible.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. d (p.23)', 'v2', 'Las áreas para el almacenamiento de medicamentos y dispositivos médicos son independientes, diferenciadas y señalizadas.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 33),
    ('I03-06', 'Capacidad de almacenamiento suficiente para los dispositivos médicos comercializados', 'Cumple si · el espacio de almacenamiento disponible es suficiente para los dispositivos médicos que comercializa.', 'Res. 1403/2007 Manual T.I Cap.III num. 1.3 (p.29–30); num. 2 inc. 5 (p.30), sustituido por Res. 2955/2007 Art. 1 (p.1-2)', 'v2', 'La IPS que vende al detal dispositivos médicos a sus pacientes ambulatorios y los establecimientos sujetos al Dec. 2200/2005 que venden dispositivos médicos (sin Certificado de Capacidad de Almacenamiento y Acondicionamiento) tienen capacidad para almacenar los dispositivos médicos que comercializan.', 'No definida en la norma (constatación física)', 'Aplica solo a IPS y establecimientos farmacéuticos que comercializan dispositivos médicos', NULL, NULL, NULL::jsonb, NULL::jsonb, 34),
    ('I03-07', 'Área de dispensación de medicamentos y entrega de dispositivos médicos', 'Cumple si · existe área de dispensación identificada.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.2.1 lit. f (p.24); Cap.V num. 1.1.2 lit. j (p.35); Res. 3100/2019 Manual 11.3.2, Infra num. 5.3 (p.98)', 'v2', 'Cuenta con área de dispensación de medicamentos y entrega de dispositivos médicos (en farmacias-droguerías y droguerías, también de productos autorizados).', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de IPS/prestadores, farmacias-droguerías y droguerías (no aplica a depósitos de drogas ni a agencias de especialidades farmacéuticas)', NULL, NULL, NULL::jsonb, NULL::jsonb, 35),
    ('I03-08', 'Área identificada para medicamentos vencidos o deteriorados a destruir o desnaturalizar', 'Cumple si · existe área identificada y separada del inventario disponible para estos medicamentos.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.2.1 lit. g (p.24); Cap.IV num. 2.2 lit. g (p.33); Cap.V num. 1.1.2 lit. h (p.35); Res. 3100/2019 Manual 11.3.2, Infra num. 5.7 (p.98)', 'v2', 'Cuenta con área (especial) debidamente identificada para el almacenamiento (transitorio) de los medicamentos que deben ser destruidos o desnaturalizados por vencimiento o deterioro.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 36),
    ('I03-09', 'Área para productos rechazados, devueltos y retirados del mercado', 'Cumple si · existe área identificada y separada para productos rechazados, devueltos y retirados.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.2.1 lit. h (p.24); Cap.IV num. 2.2 lit. h (p.33); Res. 3100/2019 Manual 11.3.2, Infra num. 5.6 (p.98)', 'v2', 'Cuenta con área destinada al almacenamiento de productos rechazados, devueltos y retirados del mercado.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de IPS/prestadores, depósitos de drogas y agencias de especialidades farmacéuticas', NULL, NULL, NULL::jsonb, NULL::jsonb, 37),
    ('I03-10', 'Área para almacenamiento de materias primas', 'Cumple si · existe área identificada para el almacenamiento de materias primas.', 'Res. 1403/2007 Manual T.I Cap.V num. 1.1.2 lit. d (p.35); Res. 1403/2007 Manual T.I Cap.IV num. 2.2 lit. f (p.33)', 'v2', 'La farmacia-droguería cuenta con área para el almacenamiento de las materias primas. Los depósitos de drogas (y las agencias de especialidades farmacéuticas, por remisión) cuentan con área de almacenamiento de materias primas y medicamentos que requieran cadena de frío.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías, depósitos de drogas y agencias de especialidades farmacéuticas (y a droguerías por remisión literal; ver nota)', NULL, NULL, NULL::jsonb, NULL::jsonb, 38),
    ('I03-11', 'Área para productos autorizados, independiente y separada', 'Cumple si · existe área para productos autorizados separada de la de medicamentos y dispositivos médicos.', 'Res. 1403/2007 Manual T.I Cap.V num. 1.1.2 lit. f (p.35)', 'v2', 'Cuenta con área para el almacenamiento de productos autorizados, independiente y separada del área de almacenamiento de medicamentos y dispositivos médicos.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías', NULL, NULL, NULL::jsonb, NULL::jsonb, 39),
    ('I03-12', 'Área para almacenamiento de medicamentos fitoterapéuticos', 'Cumple si · existe área identificada para los medicamentos fitoterapéuticos.', 'Res. 1403/2007 Manual T.I Cap.V num. 1.1.2 lit. i (p.35)', 'v2', 'Cuenta con área para el almacenamiento de medicamentos fitoterapéuticos cuando éstos se venden al detal al público.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías que venden al detal medicamentos fitoterapéuticos', NULL, NULL, NULL::jsonb, NULL::jsonb, 40),
    ('I03-13', 'Área de alistamiento y despacho', 'Cumple si · existe área identificada de alistamiento y despacho.', 'Res. 1403/2007 Manual T.I Cap.IV num. 2.2 lit. i (p.33)', 'v2', 'El depósito de drogas cuenta con área de alistamiento y despacho.', 'No definida en la norma (constatación física)', 'Aplica solo a depósitos de drogas y agencias de especialidades farmacéuticas (por remisión del Cap.IV num. 1.3)', NULL, NULL, NULL::jsonb, NULL::jsonb, 41),
    ('I03-14', 'Área para asesoría a usuarios, farmacovigilancia, PRM/PRUM y atención farmacéutica', 'Cumple si · existe área destinada a las actividades listadas que el SF realiza.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.2.2 lit. d (p.25); Res. 3100/2019 Manual 11.3.2, Infra num. 7 (p.99)', 'v2', 'El SF hospitalario de mediana y alta complejidad cuenta, además de las áreas de baja complejidad, con área para una o varias de las siguientes actividades: asesoría a los usuarios, programas de farmacovigilancia, problemas relacionados con medicamentos (PRM), problemas relacionados con la utilización de medicamentos (PRUM) y atención farmacéutica, cuando se ofrezca.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos hospitalarios de mediana y alta complejidad', NULL, NULL, NULL::jsonb, NULL::jsonb, 42),
    ('I03-15', 'Atención farmacéutica prestada en espacio con comodidad y privacidad', 'Cumple si · el espacio donde se presta la atención farmacéutica permite conservar los recursos utilizados, ofrece comodidad al usuario y al prestador y garantiza la privacidad de la información.', 'Res. 1403/2007 Manual T.II Cap.III num. 1.1 inc. 2 (p.57)', 'v2', 'La atención farmacéutica se presta en condiciones que permitan la conservación de los recursos utilizados, la comodidad del usuario y del prestador de la atención y la privacidad de la información manejada.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios y establecimientos farmacéuticos que ofrecen atención farmacéutica', NULL, NULL, NULL::jsonb, NULL::jsonb, 43),
    ('I03-16', 'Sede de prestador exclusivamente extramural con las áreas del criterio 46', 'Cumple si · la sede cuenta con los tres ambientes o áreas (el de medicamentos, dispositivos médicos e insumos cuando se requiera).', 'Res. 3100/2019 Manual 11.1.2 num. 46.1 (p.67); Res. 3100/2019 Manual 11.1.2 num. 46.3 (p.67); Res. 3100/2019 Manual 11.1.2 num. 46.2 (p.67); Res. 465/2025 Art. 1, par. 3 (p.2-3)', 'v2', 'Cuando el prestador presta servicios exclusivamente en la modalidad extramural, su sede cuenta con: ambiente o área para el almacenamiento de medicamentos, dispositivos médicos e insumos (cuando se requiera); ambiente o área para el almacenamiento de equipos biomédicos; y ambiente o área para el archivo de las historias clínicas y registros.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que prestan servicios exclusivamente en la modalidad extramural', NULL, NULL, NULL::jsonb, NULL::jsonb, 44),
    ('I05-01', 'Dotación de equipos, instrumentos, bibliografía y materiales necesaria por área', 'Cumple si · cada área cuenta con los equipos, instrumentos, bibliografía y materiales necesarios para los procesos que realiza (en prestadores REPS, exclusivos del servicio y conformes con las recomendaciones del fabricante).', 'Res. 1403/2007 Manual T.I Cap.I num. 3 lit. b (p.21); T.I Cap.III num. 2 inc. 2 (p.30), sustituido por Res. 2955/2007 Art. 1 (p.1-2); Dec. 780/2016 Art. 2.5.3.10.8 num. 2 (p. 286); Res. 3100/2019 Manual 11.3.2, Dotación num. 9.1 (p.99)', 'v2', 'El SF o establecimiento cuenta con una dotación (equipos, instrumentos, bibliografía y materiales) necesaria para cumplir los objetivos de las actividades y procesos de cada área; en prestadores REPS, la dotación y el mobiliario son exclusivos y necesarios para los procesos generales y especiales, de acuerdo con las recomendaciones de los fabricantes.', 'No definida en la norma (constatación física / inventario de dotación)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 45),
    ('I05-02', 'Dotación concordante con lo documentado en procesos prioritarios', 'Cumple si · la dotación existente corresponde a la definida por el prestador en sus procesos prioritarios.', 'Res. 3100/2019 Manual 11.1.3 num. 4 (p.69)', 'v2', 'La dotación del servicio está en concordancia con lo definido por el prestador en el estándar de procesos prioritarios.', 'No definida en la norma (cotejo de la dotación frente a los procesos prioritarios documentados)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 46),
    ('I05-03', 'Termómetro e higrómetro calibrado (termohigrómetro) en cada sitio de almacenamiento', 'Cumple si · cada sitio de almacenamiento cuenta con instrumento funcional para medir temperatura y humedad relativa y el higrómetro está calibrado.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. h (p.24); T.II Cap.II num. 3.2 lit. i (p.46); Res. 3100/2019 Manual 11.3.2, Dotación num. 9.2 (p.99); Res. 3100/2019 Manual 11.1.4 num. 7 (p.72)', 'v2', 'Los sitios donde se almacenan medicamentos y DM (incluidas las reservas) disponen de instrumentos para medir la temperatura y la humedad relativa: termómetro adecuado e higrómetro calibrado, u otros instrumentos que cumplan esas funciones.', 'No definida en la norma (constatación física; se desprende: soporte de calibración del higrómetro)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 47),
    ('I05-04', 'Productos en estibas o estanterías de material sanitario, impermeable y lavable', 'Cumple si · los medicamentos y DM están en estibas o estanterías de material sanitario, impermeable y de fácil limpieza.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. j (p.46–47); Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. j (p.46)', 'v2', 'Los medicamentos y DM se ubican en estibas o estanterías de material sanitario, impermeable y fácil de limpiar.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 48),
    ('I05-05', 'F-D y DRG: estantería independiente para productos distintos de medicamentos', 'Cumple si · esos productos están en estantería independiente y separada.', 'Res. 1403/2007 Manual T.I Cap.V num. 1 lit. a inc. final (p.34); num. 2 lit. a inc. final (p.40)', 'v2', 'En farmacias-droguerías y droguerías, los productos que no producen contaminación ni ponen en riesgo la salud de los usuarios que pueden venderse al detal están ubicados en estantería independiente y separada.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías', NULL, NULL, NULL::jsonb, NULL::jsonb, 49),
    ('I05-07', 'Bibliografía del SF hospitalario: literatura, estabilidad/compatibilidad y farmacopea', 'Cumple si · están disponibles y actualizados la literatura científica, el soporte sobre estabilidad y compatibilidad y la farmacopea de base oficial.', 'Res. 1403/2007 Manual T.I Cap.II num. 2 (p.25)', 'v2', 'El servicio farmacéutico hospitalario, según su grado de complejidad, está dotado de literatura científica aceptada internacionalmente, soporte bibliográfico actualizado sobre estabilidad y compatibilidad y la farmacopea de base oficialmente adoptada en Colombia.', 'No definida en la norma (se desprende: bibliografía física o electrónica disponible)', 'Aplica solo a servicios farmacéuticos hospitalarios de IPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 50),
    ('I05-08', 'F-D y DRG: literatura científica y referencias de farmacología y farmacoterapia', 'Cumple si · están disponibles literatura científica y referencias actualizadas sobre farmacología y farmacoterapia.', 'Res. 1403/2007 Manual T.I Cap.V num. 1.2 (p.36); num. 2.2 lit. a (p.40)', 'v2', 'La farmacia-droguería y la droguería disponen de literatura científica aceptada internacionalmente y de referencias bibliográficas actualizadas y confiables sobre farmacología y farmacoterapia.', 'No definida en la norma (se desprende: bibliografía física o electrónica disponible)', 'Aplica solo a farmacias-droguerías y droguerías', NULL, NULL, NULL::jsonb, NULL::jsonb, 51),
    ('I05-09', 'Elementos de protección personal (barrera) entregados gratis y oportunamente', 'Cumple si · cada trabajador cuenta con elementos de barrera o contención entregados sin costo y de manera oportuna.', 'Dec. 780/2016 Art. 2.8.1.3.12 lit. d (p. 456)', 'v2', 'Se proporciona a cada trabajador, en forma gratuita y oportuna, elementos de barrera o contención para su protección personal.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de IPS y establecimientos farmacéuticos que realicen procedimientos asistenciales (inyectología o glicemia)', NULL, NULL, NULL::jsonb, NULL::jsonb, 52),
    ('I05-10', 'Registro (inventario) de equipos biomédicos con datos mínimos', 'Cumple si · el registro contiene los seis datos listados para cada equipo biomédico.', 'Res. 3100/2019 Manual 11.1.3 num. 1 (p.68)', 'v2', 'El prestador cuenta con el registro de la relación de equipos biomédicos requeridos, con: nombre del equipo, marca, modelo, serie, registro sanitario o permiso de comercialización (cuando lo requiera) y clasificación por riesgo (cuando la requiera).', 'Registro (relación de equipos biomédicos)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que utilicen equipos biomédicos', NULL, NULL, NULL::jsonb, NULL::jsonb, 53),
    ('I05-11', 'Programa de mantenimiento preventivo de equipos biomédicos', 'Cumple si · existe programa de mantenimiento preventivo vigente que cubre los equipos biomédicos conforme a las recomendaciones del fabricante (o al protocolo del prestador).', 'Res. 3100/2019 Manual 11.1.3 num. 2.1 (p.68)', 'v2', 'El prestador cuenta con programa de mantenimiento preventivo de los equipos biomédicos que incluye las recomendaciones del fabricante o, cuando este no las define, el protocolo de mantenimiento del prestador.', 'Programa de mantenimiento preventivo', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que utilicen equipos biomédicos', NULL, NULL, NULL::jsonb, NULL::jsonb, 54),
    ('I05-12', 'Hojas de vida de equipos biomédicos con registros de mantenimiento', 'Cumple si · cada equipo biomédico tiene hoja de vida con los registros de mantenimientos preventivos y correctivos.', 'Res. 3100/2019 Manual 11.1.3 num. 2.2 (p.68)', 'v2', 'Cada equipo biomédico tiene hoja de vida con los registros de los mantenimientos preventivos y correctivos, según corresponda.', 'Hojas de vida de los equipos', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que utilicen equipos biomédicos', NULL, NULL, NULL::jsonb, NULL::jsonb, 55),
    ('I05-13', 'Suficiencia de equipos biomédicos según su frecuencia de uso', 'Cumple si · la cantidad de equipos biomédicos corresponde a su frecuencia de uso (incluidos tiempos de esterilización cuando aplique).', 'Res. 3100/2019 Manual 11.1.3 num. 5 (p.69)', 'v2', 'La suficiencia de equipos biomédicos está relacionada con su frecuencia de uso, incluidos los tiempos del proceso de esterilización cuando aplique.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que utilicen equipos biomédicos', NULL, NULL, NULL::jsonb, NULL::jsonb, 56),
    ('I05-14', 'Mantenimiento de equipos biomédicos ejecutado por personal idóneo', 'Cumple si · el mantenimiento lo ejecuta talento humano profesional, tecnólogo o técnico en áreas relacionadas, propio o contratado.', 'Res. 3100/2019 Manual 11.1.3 num. 6 (p.69)', 'v2', 'El mantenimiento de los equipos biomédicos lo ejecuta talento humano profesional, tecnólogo o técnico en áreas relacionadas, directamente o mediante contrato o convenio con un tercero.', 'No definida en la norma (se desprende: soportes de formación del ejecutor y contrato o convenio)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que utilicen equipos biomédicos', NULL, NULL, NULL::jsonb, NULL::jsonb, 57),
    ('I05-15', 'Plan de mantenimiento de la planta física que incluye el equipamiento fijo', 'Cumple si · existe plan de mantenimiento de la planta física que incluye el equipamiento fijo.', 'Res. 3100/2019 Manual 9.3.4.2 (p.45)', 'v2', 'El prestador (IPS o entidad con objeto social diferente) cuenta con plan de mantenimiento de la planta física que incluye el equipamiento fijo; para las entidades con objeto social diferente puede ser el de la edificación.', 'Plan de mantenimiento de la planta física', 'Aplica solo a prestadores inscritos en el REPS (IPS y entidades con objeto social diferente)', NULL, NULL, NULL::jsonb, NULL::jsonb, 58),
    ('I05-16', 'Telemedicina: mantenimiento de la tecnología de información y comunicaciones', 'Cumple si · existe evidencia del mantenimiento de la tecnología de información y comunicaciones usada en telemedicina.', 'Res. 3100/2019 Manual 11.1.3 num. 17 (p.70)', 'v2', 'El prestador realiza el mantenimiento de la tecnología de información y comunicaciones para avalar la calidad de la información.', 'No definida en la norma (se desprende: registros de mantenimiento)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS en modalidad telemedicina', NULL, NULL, NULL::jsonb, NULL::jsonb, 59),
    ('I05-17', 'Telemedicina (remisor): certificación de ingeniero biomédico de equipos de captura', 'Cumple si · existe el documento firmado por ingeniero biomédico con tarjeta profesional vigente que certifica los numerales 17.1.1.1 a 17.1.1.3.', 'Res. 3100/2019 Manual 11.1.3 num. 17.1.1 (p.70)', 'v2', 'El prestador remisor cuenta con documento firmado por ingeniero biomédico con tarjeta profesional vigente que certifica que los dispositivos periféricos garantizan la información requerida por el prestador de referencia, que los equipos de captura obtienen información equivalente a la original y que los parámetros de digitalización y compresión garantizan la resolución necesaria.', 'Documento firmado por ingeniero biomédico', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS en telemedicina, categoría telexperticia, como prestador remisor', NULL, NULL, NULL::jsonb, NULL::jsonb, 60),
    ('I05-18', 'Prestador exclusivamente extramural: dotación según criterios del servicio extramural', 'Cumple si · la dotación del servicio farmacéutico cumple los criterios del estándar de dotación definidos para la modalidad extramural.', 'Res. 465/2025 Art. 1, par. 3 (p.3)', 'v2', 'En el prestador exclusivamente extramural, la dotación de todos los servicios cumple los criterios definidos para cada servicio en la modalidad extramural.', 'No definida en la norma (constatación física)', 'Aplica solo a prestadores inscritos en el REPS que prestan servicios exclusivamente en modalidad extramural', NULL, NULL, NULL::jsonb, NULL::jsonb, 61),
    ('I05-19', 'Telemedicina: pantallas de grado médico con especificaciones mínimas', 'Cumple si · la ficha técnica de las pantallas acredita las especificaciones del rol (remisor o referencia).', 'Res. 3100/2019 Manual 11.1.3 num. 17.1.2.3 (p.70); Res. 3100/2019 Manual 11.1.3 num. 17.2.2 (p.71)', 'v2', 'Las pantallas o monitores de grado médico usados para desplegar imágenes cumplen: en el remisor, dot pitch máximo de 0,25 mm; en el prestador de referencia, dot pitch máximo de 0,19 mm, resolución mínima de 1024 x 768 píxeles, contraste mínimo 500:1 y luminancia mínima de 250 cd/m2.', 'No definida en la norma (se desprende: ficha técnica del monitor)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS en telemedicina que despliegan imágenes', NULL, NULL, NULL::jsonb, NULL::jsonb, 62),
    ('I09-01', 'Área para manejo de residuos, aislada, segura y acorde al diagnóstico', 'Cumple si · existe un área o unidad identificada para residuos, aislada de las áreas que exigen estrictas condiciones de higiene, dimensionada según el diagnóstico y sin derrames ni riesgo de contaminación de materias primas o insumos.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.2.1 lit. i (p. 24); Cap.IV num. 2.2 lit. k (p. 33); Cap.V num. 1.1.2 lit. l (p. 35); Res. 591/2024 Manual (Anexo) num. 4.1.1.3.1.7 (p. 12); Res. 444/2008 Anexo, num. 5.3.3, p.8', 'v2', 'El establecimiento cuenta con área para manejo y disposición de residuos de acuerdo con la reglamentación vigente (Res. 1403/2007). Conforme a la Res. 591/2024, el almacenamiento interno se hace en unidades de almacenamiento diseñadas y ubicadas según el diagnóstico (cantidad y clases de residuos, frecuencias de recolección); en actividades de atención en salud, aisladas de salas de hospitalización, cirugía, laboratorios, toma de muestras, bancos de sangre, preparación de alimentos y lugares que requieran estrictas condiciones de higiene; y el almacenamiento es seguro, previniendo derrames, accidentes y contaminación de materias primas, insumos o residuos.', 'No definida en la norma (constatación física); diagnóstico del PGIRASA', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 63)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C06', 'Seguridad física', '', 'Procesos auditados', NULL, NULL, NULL, ARRAY['ESM', 'FA', 'NC']::text[], 'Anexo 5 p.10 (seguridad física) · validaciones de la v2', 7) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('SF-01', 'Control de acceso a las áreas de almacenamiento y dispensación', 'Cumple si · solo ingresa personal autorizado y el acceso está controlado.', 'Propuesto en la v2: sin soporte en la fuente de verdad', 'propuesto', '', '', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('SF-02', 'Custodia de medicamentos y llaves', 'Cumple si · existe responsable y registro de la custodia de llaves y medicamentos de mayor valor.', 'Propuesto en la v2: sin soporte en la fuente de verdad', 'propuesto', '', '', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('SF-03', 'Sistemas de vigilancia o alarma', 'Cumple si · el punto cuenta con vigilancia o alarma operativa.', 'Propuesto en la v2: sin soporte en la fuente de verdad', 'propuesto', '', '', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('SF-04', 'Prevención y atención de emergencias', 'Cumple si · hay extintores vigentes, señalización y plan de emergencias.', 'Propuesto en la v2: sin soporte en la fuente de verdad', 'propuesto', '', '', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('SF-05', 'Protección contra pérdida y hurto', 'Cumple si · hay controles y registro de novedades por pérdida o hurto.', 'Propuesto en la v2: sin soporte en la fuente de verdad', 'propuesto', '', '', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 5)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C07', 'Selección, adquisición y recepción técnica', '', 'Procesos auditados', NULL, NULL, NULL, ARRAY['ESM', 'FA', 'NC']::text[], 'Anexo 3 p.4 (recepción técnica) · validaciones de la v2', 8) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P04-01', 'Proceso de selección de medicamentos y DM documentado e implementado', 'Cumple si · existe procedimiento de selección que incluye los pasos a) definición de políticas institucionales, b) determinación del consumo histórico y c) decisión de selección, hay evidencia de su aplicación y, en prestadores REPS, la información documentada fue elaborada por el responsable del servicio.', 'Dec. 780/2016 Art. 2.5.3.10.14 num. 1 (p. 290); Res. 3100/2019 Manual 11.1.4 num. 4.1 (p.71); Res. 1403/2007 Manual T.II Cap.II num. 1.2 (p.43); Res. 3100/2019 Manual 11.3.2, PP num. 15.1 (p.100); Dec. 780/2016 Art. 2.5.3.10.11 par. 2 (p. 288); Res. 1403/2007 Manual T.II Cap.II num. 1.1 (p.43)', 'v2', 'El servicio tiene implementado el proceso general de selección de medicamentos y dispositivos médicos mediante un procedimiento que contempla como mínimo: a) definición de políticas institucionales; b) determinación del consumo histórico; c) decisión de selección. Los prestadores inscritos en el REPS cuentan con información documentada del proceso, elaborada por el responsable del servicio.', 'Información documentada / procedimiento de selección (Res. 3100; se desprende de Res. 1403) y soportes de su aplicación', 'Aplica solo a servicios farmacéuticos de IPS/prestadores y a farmacias-droguerías, droguerías o personas autorizadas contratadas en el SGSSS (Dec. 780 art. 2.5.3.10.11 par. 2); no aplica a F-D/DRG no contratadas en el SGSSS ni a AEF/DD, sometidas solo a recepción y almacenamiento (y dispensación las F-D/DRG)', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P04-02', 'Criterios, técnicas y métodos para controlar y evaluar la selección', 'Cumple si · están definidos criterios, técnicas o métodos de control y evaluación del proceso de selección y hay evidencia de su aplicación.', 'Res. 1403/2007 Manual T.II Cap.II num. 1.3 (p.43)', 'v2', 'Se cuenta con criterios, técnicas y métodos que permitan controlar, evaluar y gestionar continuamente el proceso de selección de medicamentos y dispositivos médicos.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de IPS/prestadores y a farmacias-droguerías, droguerías o personas autorizadas contratadas en el SGSSS (Dec. 780 art. 2.5.3.10.11 par. 2); no aplica a F-D/DRG no contratadas en el SGSSS ni a AEF/DD, sometidas solo a recepción y almacenamiento (y dispensación las F-D/DRG)', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P04-03', 'Proceso de adquisición de medicamentos y DM documentado e implementado', 'Cumple si · existe información documentada (procedimiento) del proceso de adquisición y evidencia de su aplicación.', 'Dec. 780/2016 Art. 2.5.3.10.14 num. 1 (p. 290); Res. 3100/2019 Manual 11.1.4 num. 4.2 (p.71); Res. 3100/2019 Manual 11.3.2, PP num. 15.1 (p.100); Dec. 780/2016 Art. 2.5.3.10.11 par. 2 (p. 288)', 'v2', 'El servicio tiene implementado el proceso general de adquisición de medicamentos y dispositivos médicos; los prestadores inscritos en el REPS cuentan con información documentada del proceso, elaborada por el responsable del servicio.', 'Información documentada / procedimiento de adquisición (Res. 3100) y soportes de su aplicación', 'Aplica solo a servicios farmacéuticos de IPS/prestadores y a farmacias-droguerías, droguerías o personas autorizadas contratadas en el SGSSS (Dec. 780 art. 2.5.3.10.11 par. 2); no aplica a F-D/DRG no contratadas en el SGSSS ni a AEF/DD, sometidas solo a recepción y almacenamiento (y dispensación las F-D/DRG)', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P04-04', 'Programación de necesidades por periodo con los pasos a) a g) del Manual', 'Cumple si · existe programación de necesidades para un periodo definido que evidencia los pasos a) a g).', 'Res. 1403/2007 Manual T.II Cap.II num. 2.3.1 (p.44–45)', 'v2', 'El SF o establecimiento determina la cantidad de medicamentos y DM que requiere para un periodo, considerando el perfil epidemiológico, la población usuaria y/o el consumo histórico, las necesidades de los servicios, la oferta de servicios y el presupuesto, siguiendo los pasos: a) definir periodo de análisis y de proyección; b) cuantificar las necesidades y priorizarlas por nivel de uso en cada servicio; c) confrontar los cálculos con los consumos históricos; d) analizar las causas de modificaciones notables de los consumos; e) ajustar y programar cantidades con punto de reposición, consumos promedio, niveles mínimos y tiempo de reposición; f) definir prioridades según presupuesto y peso económico (ABC/VEN u otro método idóneo); g) definir programas de entregas o momentos de compra.', 'No definida en la norma (se desprende: documento de programación de necesidades)', 'Aplica solo a servicios farmacéuticos de IPS/prestadores y a farmacias-droguerías, droguerías o personas autorizadas contratadas en el SGSSS (Dec. 780 art. 2.5.3.10.11 par. 2); no aplica a F-D/DRG no contratadas en el SGSSS ni a AEF/DD, sometidas solo a recepción y almacenamiento (y dispensación las F-D/DRG)', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P04-05', 'Mecanismos para adquirir medicamentos y DM de urgencias evidentes no incluidos en el POS', 'Cumple si · la institución tiene definido un mecanismo para adquirir medicamentos y DM de urgencias evidentes no incluidos en el POS.', 'Res. 1403/2007 Manual T.II Cap.II num. 2.2 inc. 1 (p.44)', 'v2', 'La institución tiene creados mecanismos que permitan adquirir los dispositivos médicos y medicamentos que deban utilizarse en urgencias evidentes y que no estén incluidos en el Plan Obligatorio de Salud (POS).', 'No definida en la norma (se desprende: mecanismo o procedimiento documentado)', 'Aplica solo a IPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P04-06', 'Prevalencia del criterio técnico del director del SF frente al área de compras', 'Cumple si · en los casos de discrepancia entre compras y el SF sobre los aspectos listados, prevaleció el criterio técnico del director del SF.', 'Res. 1403/2007 Manual T.II Cap.II num. 2.3.3 (p.45)', 'v2', 'Cuando hay diferencias de criterio entre el responsable de las compras y el responsable del servicio farmacéutico respecto a calidad, recepción y almacenamiento, distribución, uso adecuado, devolución al proveedor por fecha próxima de vencimiento, ofrecimiento/aceptación/rechazo de donaciones y destrucción o desnaturalización, prevalece el criterio técnico del director del servicio farmacéutico.', 'No definida en la norma', 'Aplica solo a SF de IPS o establecimientos cuyo responsable de compras es distinto del responsable del SF', NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P04-07', 'Control de la calidad durante el proceso de adquisición', 'Cumple si · están definidos y se aplican criterios, técnicas o métodos de control de la calidad del proceso de adquisición.', 'Res. 1403/2007 Manual T.II Cap.II num. 2.4 (p.45)', 'v2', 'La institución o establecimiento cuenta con criterios, técnicas y métodos para controlar, evaluar y gestionar continuamente la calidad durante la adquisición de medicamentos y DM, controlando el cumplimiento de la normatividad de contratación administrativa, civil o comercial y de los principios de economía, transparencia y selección objetiva del contratista.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de IPS/prestadores y a farmacias-droguerías, droguerías o personas autorizadas contratadas en el SGSSS (Dec. 780 art. 2.5.3.10.11 par. 2); no aplica a F-D/DRG no contratadas en el SGSSS ni a AEF/DD, sometidas solo a recepción y almacenamiento (y dispensación las F-D/DRG)', NULL, NULL, NULL::jsonb, NULL::jsonb, 7),
    ('P04-08', 'Aplicación del sistema de codificación de medicamentos y DM del Ministerio', 'Cumple si · los medicamentos y DM adquiridos se codifican conforme al sistema de codificación establecido por el Ministerio.', 'Res. 1403/2007 Manual T.II Cap.II num. 2.4 (p.45)', 'v2', 'En la adquisición se tiene en cuenta el sistema de codificación para medicamentos y dispositivos médicos que establezca el Ministerio.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de IPS/prestadores y a farmacias-droguerías, droguerías o personas autorizadas contratadas en el SGSSS (Dec. 780 art. 2.5.3.10.11 par. 2); no aplica a F-D/DRG no contratadas en el SGSSS ni a AEF/DD, sometidas solo a recepción y almacenamiento (y dispensación las F-D/DRG)', NULL, NULL, NULL::jsonb, NULL::jsonb, 8),
    ('P04-09', 'Medicamentos y DM adquiridos solo de proveedores legalmente autorizados', 'Cumple si · los proveedores de los que se adquieren medicamentos y DM están legalmente autorizados por la entidad territorial de salud o el INVIMA.', 'Res. 1403/2007 Manual T.II Cap.II num. 4 inc. 1 (p.51)', 'v2', 'Los medicamentos y dispositivos médicos se adquieren de sitios legalmente autorizados por la entidad territorial de salud o el INVIMA.', 'No definida en la norma (se desprende: soportes de autorización de los proveedores y facturas de compra)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P04-10', 'Donaciones: solo medicamentos legales, no alterados ni fraudulentos y vigentes', 'Cumple si · los medicamentos recibidos en donación cumplen los requisitos legales de comercialización, no presentan causales de alteración o fraude y tenían fecha de vencimiento vigente al recibirse.', 'Res. 1403/2007 Manual T.II Cap.III num. 6.1 inc. 6 (p.71); Res. 1403/2007 Manual T.II Cap.III num. 6.2 lit. b (p.71)', 'v2', 'Solo se reciben (u ofrecen) en donación medicamentos que cumplan la plenitud de los requisitos legales para ser comercializados en el territorio nacional, que no estén incursos en causales de alteración o fraude y cuya fecha de vencimiento esté vigente.', 'No definida en la norma (se desprende: acta de recepción técnica de la donación)', 'Aplica solo a IPS receptoras de donaciones nacionales de medicamentos', NULL, NULL, NULL::jsonb, NULL::jsonb, 10),
    ('P04-11', 'Donaciones recibidas técnicamente por QF o TRF y almacenadas adecuadamente', 'Cumple si · el acta de recepción técnica de cada donación está suscrita por QF o TRF (o auxiliar en servicios farmacéuticos en las regiones del art. 446 Ley 09/1979), sigue el procedimiento del num. 3.3, y los donados se almacenan en las condiciones de almacenamiento aplicables.', 'Res. 1403/2007 Manual T.II Cap.III num. 6.2 lit. a (p.71); Res. 1403/2007 Manual T.II Cap.III num. 6.2 lit. c (p.71)', 'v2', 'La donación es recibida técnicamente por un Químico Farmacéutico o Tecnólogo en Regencia de Farmacia conforme al procedimiento de recepción (Manual T.II Cap.II num. 3.3); en las regiones del art. 446 de la Ley 09/1979 puede recibirla el auxiliar en servicios farmacéuticos, cumpliendo la recepción técnica. Los medicamentos donados se almacenan adecuadamente según la reglamentación aplicable.', 'Acta de recepción (num. 3.3)', 'Aplica solo a IPS receptoras de donaciones nacionales de medicamentos', NULL, NULL, NULL::jsonb, NULL::jsonb, 11),
    ('P04-12', 'Medicamentos donados no comercializados ni usados con fines lucrativos', 'Cumple si · los registros de salida de los medicamentos donados no evidencian comercialización ni uso con fines lucrativos.', 'Res. 1403/2007 Manual T.II Cap.III num. 6.3 (p.71)', 'v2', 'Los medicamentos recibidos en donación no se comercializan ni se utilizan con fines lucrativos; cuando la donación se solicitó o recibió para una circunstancia concreta, se usan para satisfacer esa necesidad específica.', 'No definida en la norma (se desprende: registros de salida de los medicamentos donados)', 'Aplica solo a IPS receptoras de donaciones nacionales de medicamentos', NULL, NULL, NULL::jsonb, NULL::jsonb, 12),
    ('P04-13', 'Plan para el uso humanitario de excedentes de donaciones', 'Cumple si · existe plan definido para el uso humanitario de los excedentes en la población más vulnerable y los excedentes se usan conforme a él.', 'Res. 1403/2007 Manual T.II Cap.III num. 6.3 (p.71)', 'v2', 'Los excedentes de donaciones se utilizan con fines humanitarios en la atención de la población más vulnerable, según un plan previamente definido o que se establezca con rigurosidad y transparencia.', 'Plan de uso de excedentes', 'Aplica solo a IPS receptoras de donaciones que tengan excedentes', NULL, NULL, NULL::jsonb, NULL::jsonb, 13),
    ('P04-14', 'Vacunación en el SF: procedimiento con obtención de vacunas de proveedor de calidad', 'Cumple si · el procedimiento operativo documentado de aplicación de vacunas define la forma de obtenerlas de un proveedor que asegure la calidad del biológico.', 'Res. 465/2025 Art. 3, par. 3, ii) (p.4)', 'v2', 'Si se aplican vacunas en un servicio distinto del de vacunación (p. ej., el SF), el prestador documenta en el estándar de procesos prioritarios el procedimiento operativo para la aplicación de las vacunas, que incluye la forma en que se obtendrán de un proveedor que asegure el cumplimiento de la calidad del biológico.', 'Información documentada en procesos prioritarios', 'Aplica solo a prestadores inscritos en el REPS que apliquen vacunas en servicios distintos del de vacunación', NULL, NULL, NULL::jsonb, NULL::jsonb, 14),
    ('P04-15', 'IPS: comité de compras con concepto técnico del DT y aprobación de la programación', 'Cumple si · existe el comité de compras, sus actas evidencian la verificación de cotizaciones y análisis de ofertas, el concepto técnico del director del SF y la aprobación de la programación de necesidades.', 'Res. 1403/2007 Manual T.II Cap.II num. 2.2 inc. 1 (p.44); Res. 1403/2007 Manual T.II Cap.II num. 2.3.1 lit. g (p.45)', 'v2', 'La institución cuenta con comité de compras que aplica la política de compras, verifica las cotizaciones que respaldan la evaluación de las ofertas y analiza las ofertas con los criterios definidos; el director técnico del servicio farmacéutico da concepto técnico al comité para la adquisición de medicamentos y DM; y la programación de necesidades es evaluada permanentemente y aprobada por el comité de compras.', 'No definida en la norma (se desprende: acto de conformación del comité, actas con conceptos técnicos y aprobación de la programación)', 'Aplica solo a IPS (con comité de compras)', NULL, NULL, NULL::jsonb, NULL::jsonb, 15),
    ('P04-16', 'Información de la adquisición enviada al sistema de información del SF', 'Cumple si · la información de las adquisiciones está incorporada al sistema de información del SF de forma continua.', 'Res. 1403/2007 Manual T.II Cap.II num. 2.3.4 (p.45)', 'v2', 'El responsable de la adquisición envía de manera oportuna, continua y veraz al sistema de información del servicio farmacéutico toda la información que va adquiriendo sobre medicamentos y dispositivos médicos.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de IPS y establecimientos que realizan adquisición', NULL, NULL, NULL::jsonb, NULL::jsonb, 16),
    ('P05-01', 'Proceso de recepción y almacenamiento documentado e implementado', 'Cumple si · el proceso de recepción está definido y se aplica y, en prestadores REPS, existe información documentada elaborada por el responsable del servicio.', 'Dec. 780/2016 Art. 2.5.3.10.14 num. 1 (p. 290); Res. 3100/2019 Manual 11.1.4 num. 4.4 (p.71); Res. 3100/2019 Manual 11.3.2, PP num. 15.1 (p.100)', 'v2', 'Todo servicio y establecimiento farmacéutico tiene implementado el proceso general de recepción y almacenamiento de medicamentos y DM; los prestadores inscritos en el REPS cuentan con información documentada del proceso de recepción, elaborada por el responsable del servicio.', 'Información documentada del proceso (Res. 3100); para los demás no definida en la norma', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 17),
    ('P05-02', 'Recepción realizada por el director del SF/establecimiento o su delegado', 'Cumple si · las recepciones son realizadas por el director o por la persona que este delegó.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.3 (p.47)', 'v2', 'Los medicamentos y DM adquiridos son recibidos por el director del servicio farmacéutico de la IPS o del establecimiento farmacéutico, o por la persona que este delegue.', 'No definida en la norma (se desprende: firma del acta de recepción y soporte de la delegación)', '', NULL, '1 · Recepción técnica y muestras médicas', NULL::jsonb, NULL::jsonb, 18),
    ('P05-03', 'Estudio y comparación de la documentación del negocio y de la entrega', 'Cumple si · en cada recepción se verificó la correspondencia entre la documentación del negocio y la de entrega en fecha, cantidades y condiciones técnicas.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.3 lit. a–c (p.47)', 'v2', 'En la recepción se estudia la documentación que contiene el negocio y la documentación de entrega, y se comparan para establecer la correspondencia entre los productos entregados y los especificados (fecha de entrega, cantidades, condiciones técnicas, etc.).', 'No definida en la norma (se desprende: orden de compra o documento del negocio frente a factura/remisión)', '', NULL, '1 · Recepción técnica y muestras médicas', NULL::jsonb, NULL::jsonb, 19),
    ('P05-04', 'Inspección técnica y acta de recepción completa, firmada y archivada', 'Cumple si · cada acta de recepción registra fecha y hora de entrega, cantidad de unidades, lote, registro sanitario, fecha de vencimiento, condiciones de transporte, manipulación, embalaje, empaque y envase, condiciones administrativas y técnicas de la negociación y la identificación de la muestra (si se tomó), refleja la inspección (incluido laboratorio fabricante), está firmada por quien recibe y quien entrega y está archivada en el sitio designado en orden consecutivo.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.3 lit. d (p.47); Res. 1403/2007 Manual T.II Cap.II num. 3.3 lit. f (p.48)', 'v2', 'En cada recepción se inspeccionan los productos (cantidad de unidades, número de lote, fecha de vencimiento, registro sanitario, laboratorio fabricante, condiciones de almacenamiento durante el transporte, manipulación, embalaje, material de empaque y envase, condiciones administrativas y técnicas de la negociación) y se elabora un acta que recoge detalladamente esa información, incluida la fecha y hora de entrega y la identificación de la muestra tomada. El acta la firman quien recibe y quien entrega y se archiva en el sitio previamente designado y en orden sucesivo.', 'Acta de recepción', '', NULL, '1 · Recepción técnica y muestras médicas', NULL::jsonb, NULL::jsonb, 20),
    ('P05-05', 'Comunicación a la autoridad sanitaria de productos no conformes en la recepción', 'Cumple si · para cada producto que no cumplió especificaciones de calidad en el recibo, existe comunicación a la autoridad sanitaria competente.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.3 lit. d (p.47)', 'v2', 'Cuando en la diligencia de recibo los productos no cumplen las especificaciones técnicas de calidad, se comunica a las autoridades sanitarias competentes, de acuerdo con la legislación vigente.', 'No definida en la norma (se desprende: comunicación radicada ante la autoridad sanitaria)', 'Aplica solo si en la recepción se detectaron productos que no cumplían especificaciones técnicas de calidad', NULL, '1 · Recepción técnica y muestras médicas', NULL::jsonb, NULL::jsonb, 21),
    ('P05-06', 'Plan de muestreo en la recepción (Res. INVIMA 2004008172/2004)', 'Cumple si · existe plan de muestreo con cálculo del tamaño de muestra, aplicado en las recepciones, y la muestra queda identificada en el acta.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.3 lit. e (p.47–48)', 'v2', 'Se define el plan de muestreo y se calcula el tamaño de la muestra, que se extrae del total del lote, conforme a la Res. INVIMA 2004008172 de 2004 y normas que la complementen, modifiquen o sustituyan.', 'No definida en la norma (se desprende: plan de muestreo documentado; el acta identifica la muestra)', 'Aplica solo a SF de IPS y establecimientos mayoristas (DD, AEF); de aplicación opcional para establecimientos minoristas (F-D, DRG)', NULL, '1 · Recepción técnica y muestras médicas', NULL::jsonb, NULL::jsonb, 22),
    ('P05-07', 'Registro de ingreso de lo recibido (cantidad, fecha, valor unitario y total)', 'Cumple si · cada ingreso está registrado con cantidad, fecha, valor unitario y valor total.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.3 lit. h (p.48)', 'v2', 'El SF o establecimiento registra en los medios existentes, preferiblemente computarizados, la cantidad, fecha, valor unitario, valor total, etc., de los medicamentos y DM recibidos.', 'Registro de ingreso', '', NULL, '1 · Recepción técnica y muestras médicas', NULL::jsonb, NULL::jsonb, 23),
    ('P05-08', 'Registro de medicamentos y DM con datos mínimos (lote, vencimiento, registro sanitario)', 'Cumple si · los registros contienen todos los datos listados para cada medicamento y para cada DM.', 'Res. 3100/2019 Manual 11.1.4 num. 1 (p.71); Res. 3100/2019 Manual 11.1.4 num. 2 (p.71)', 'v2', 'El prestador lleva registros de todos los medicamentos de uso humano requeridos con: principio activo, forma farmacéutica, concentración, lote, fecha de vencimiento, presentación comercial, unidad de medida y registro sanitario vigente o permiso del INVIMA; y cuenta con información documentada de verificación y seguimiento de los DM con: descripción, marca, serie (cuando aplique), presentación comercial, registro sanitario o permiso de comercialización, clasificación por riesgo, vida útil (cuando aplique), lote y fecha de vencimiento.', 'Registros / información documentada', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 24),
    ('P05-09', 'Información documentada de reactivos de diagnóstico in vitro', 'Cumple si · la información documentada de cada reactivo contiene todos los datos listados (3.1 a 3.7).', 'Res. 3100/2019 Manual 11.1.4 num. 3 (p.71)', 'v2', 'Los reactivos de diagnóstico in vitro requeridos cuentan con información documentada de verificación y seguimiento de: nombre, marca, presentación comercial, registro sanitario vigente o permiso de comercialización del INVIMA, clasificación del riesgo sanitario, vida útil (cuando aplique), fecha de vencimiento y lote.', 'Información documentada', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que manejen reactivos de diagnóstico in vitro', NULL, NULL, NULL::jsonb, NULL::jsonb, 25),
    ('P09-10', 'Ausencia de muestras médicas en el servicio o establecimiento', 'Cumple si · no se encuentran muestras médicas de medicamentos.', 'Dec. 780/2016 Art. 2.5.3.10.19 num. 6 (p. 293); Res. 1403/2007 Manual T.II Cap.II num. 3.3 lit. g (p. 48); num. 5.3 lit. f (p. 56)', 'v2', 'Se prohíbe la recepción o tenencia de muestras médicas de medicamentos en los servicios farmacéuticos y en los establecimientos farmacéuticos; el dispensador no puede tenerlas.', 'No definida en la norma (observación del inventario)', '', NULL, '1 · Recepción técnica y muestras médicas', NULL::jsonb, NULL::jsonb, 26)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C08', 'Almacenamiento e inventarios', '', 'Procesos auditados', NULL, NULL, NULL, ARRAY['ESM', 'FA', 'NC']::text[], 'Anexo 5 p.10 (almacenamiento); Anexo 3 p.4 · validaciones de la v2', 9) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P06-01', 'Información documentada de los procesos de almacenamiento y conservación', 'Cumple si · existe información documentada vigente de los procesos de almacenamiento y de conservación, elaborada por el responsable del servicio.', 'Res. 3100/2019 Manual 11.1.4 num. 4.5 (p.71); Res. 3100/2019 Manual 11.1.4 num. 4.6 (p.71); Res. 3100/2019 Manual 11.3.2, PP num. 15.1 (p.100)', 'v2', 'El prestador cuenta con información documentada de los procesos generales de almacenamiento y de conservación, elaborada por el responsable del servicio.', 'Información documentada', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P06-02', 'Planificación del almacenamiento (sitio, diseño, conservación e inventarios)', 'Cumple si · existe evidencia de planificación del almacenamiento que contempla los aspectos a) a d).', 'Res. 1403/2007 Manual T.II Cap.II num. 3.1 (p.45–46)', 'v2', 'El almacenamiento se planifica teniendo en cuenta: a) selección del sitio; b) diseño de instalaciones; c) establecimiento de criterios, procedimientos y recursos para el cuidado y la conservación; d) aplicación de métodos de inventario que aseguren la rotación adecuada y apoyen la planificación de las adquisiciones.', 'No definida en la norma', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P06-03', 'Control de calidad durante el almacenamiento (incluye evidencias de inestabilidad)', 'Cumple si · están definidos y se aplican controles de calidad durante el almacenamiento y no se encuentran en el inventario disponible productos con evidencias de inestabilidad.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.6 (p.49); Res. 1403/2007 Manual T.II Cap.II num. 3.6.1 lit. e (p.50)', 'v2', 'El SF o establecimiento cuenta con criterios, técnicas y métodos para controlar, evaluar y gestionar continuamente la calidad durante el almacenamiento, incluida la observación de cualquier evidencia de inestabilidad según la forma farmacéutica (precipitados, turbidez y hongos en soluciones y jarabes, separación de fases en emulsiones, cambio de color, pérdida de dureza, oxidación de tabletas, pérdida de redispersión en suspensiones).', 'No definida en la norma', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P06-04', 'Ordenamiento técnico e identificación/codificación de productos almacenados', 'Cumple si · el método de ordenamiento está definido y se aplica, y los espacios/estanterías y productos están identificados o codificados (u opera otro sistema técnicamente viable que minimice errores).', 'Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. i (p.24); T.II Cap.II num. 3.4 (p.48); Res. 1403/2007 Manual T.II Cap.II num. 3.4 (p.48)', 'v2', 'Los medicamentos y DM se ubican en el área de almacenamiento asignada e identificada, según clasificación farmacológica y orden alfabético (u otro método técnicamente viable) que garantice el orden y minimice confusión, pérdida, vencimiento y errores de distribución, considerando frecuencia de demanda, volumen, forma farmacéutica y nivel de atención. Los medios de almacenamiento permiten rápida identificación y se asignan códigos a espacios, áreas y estanterías y a los productos (o se usa otro sistema técnicamente viable).', 'No definida en la norma (observación en el área de almacenamiento)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P06-05', 'Rotación: primero en expirar, primero en salir (incluye productos devueltos)', 'Cumple si · los lotes con vencimiento más próximo están ubicados y se despachan o dispensan primero, incluidos los devueltos reubicados.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. i (p.24); T.II Cap.II num. 3.5.4 (p.49); num. 5.4.1 (p.57)', 'v2', 'El sistema de segregación garantiza que el lote más próximo a vencerse sea el primero en distribuirse o dispensarse (primero en expirar, primero en salir), incluidos los productos devueltos; es obligatorio en toda la cadena del medicamento.', 'No definida en la norma (observación de la ubicación de los lotes)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P06-06', 'Control de fechas de vencimiento documentado y aplicado', 'Cumple si · existe procedimiento de control de vencimientos aplicado de forma continua y no se encuentran productos vencidos disponibles para distribución o dispensación.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.6.5 (p.50); num. 5.4.1 (p.57); Res. 3100/2019 Manual 11.1.4 num. 4.7 (p.71)', 'v2', 'Se cuenta con criterios, procedimientos y recursos para verificar continuamente las fechas de vencimiento de medicamentos y DM, de modo que se distribuyan o dispensen dentro de su vigencia; los prestadores REPS cuentan con información documentada del control de fechas de vencimiento.', 'Información documentada (Res. 3100); para los demás no definida en la norma (se desprende: registro de control de vencimientos)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P06-07', 'Control de existencias con niveles mínimo y máximo y punto de reposición', 'Cumple si · están definidos niveles mínimo y máximo, punto de reposición o pedido y presupuesto para el periodo, con el procedimiento para calcularlos.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.6.3 (p.50)', 'v2', 'Se cuenta con criterios, procedimientos y recursos para calcular las existencias necesarias para un periodo determinado, fijando niveles mínimo y máximo, punto de reposición o de pedido y el presupuesto necesario.', 'No definida en la norma (se desprende: parámetros de mínimos, máximos y punto de reposición)', 'Aplica solo a servicios y establecimientos farmacéuticos distintos de los distribuidores particulares (para estos es de aplicación opcional)', NULL, '2 · Control de existencias e inventarios', NULL::jsonb, NULL::jsonb, 7),
    ('P06-08', 'Control de inventarios: rotación y conteos físicos frente al registro de existencias', 'Cumple si · existe procedimiento de control de inventarios y registros de inventario general, selectivo o rotativo y permanente con comparación del conteo físico frente al registro de existencias.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.6.4 (p.50)', 'v2', 'Se cuenta con criterios, procedimientos y recursos para el control de inventarios, especialmente mediante la evaluación de la rotación y el conteo físico comparado con el registro de existencias; se realiza inventario general, pruebas selectivas o inventario rotativo e inventario permanente.', 'No definida en la norma (se desprende: procedimiento y registros o actas de inventario)', 'Aplica solo a servicios y establecimientos farmacéuticos distintos de los distribuidores particulares (para estos es de aplicación opcional)', NULL, '2 · Control de existencias e inventarios', NULL::jsonb, NULL::jsonb, 8),
    ('P06-09', 'Reservas (botiquines/stocks) controladas: lista visible y actualizada con vencimientos', 'Cumple si · cada botiquín o stock tiene en lugar visible la lista de todos los medicamentos y DM en reserva con sus cantidades, el listado está actualizado con fechas de vencimiento y los de vencimiento próximo se usan primero o se gestiona su cambio o devolución.', 'Res. 1403/2007 Manual T.I Cap.II num. 5 (p.28); Res. 1403/2007 Manual T.II Cap.II num. 5.4.2 lit. a (p.57); Res. 1403/2007 Manual T.II Cap.II num. 5.4.2 lit. b (p.57); Res. 1403/2007 Manual T.II Cap.II num. 4.2 inc. final (p.51)', 'v2', 'En la IPS el acceso a medicamentos y DM se garantiza en todo caso mediante reservas controladas bajo responsabilidad del servicio de enfermería, que: a) coloca en lugar visible al personal sanitario la lista y cantidades de todos los medicamentos y DM en reserva; b) mantiene actualizado el listado con las fechas de vencimiento, administrando primero los de vencimiento próximo o solicitando su cambio o devolución al proveedor. El Jefe de Enfermería del servicio responde por los medicamentos y DM allí ubicados y sus condiciones técnicas de almacenamiento.', 'Lista visible de reservas y listado actualizado con fechas de vencimiento', 'Aplica solo a IPS con reservas de medicamentos (botiquines o stocks) en los servicios', NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P06-12', 'Condiciones del fabricante y trazabilidad en recepción, almacenamiento y distribución', 'Cumple si · los productos se mantienen en las condiciones indicadas por el fabricante en el empaque y es posible reconstruir el origen y destino de los lotes manejados.', 'Res. 1403/2007 Art. 4 num. 2 (p.2–3)', 'v2', 'Cada actor que interviene en la recepción, almacenamiento, transporte y distribución física garantiza las condiciones establecidas por el fabricante en el empaque y la trazabilidad de los medicamentos y DM (principio de conservación de la calidad).', 'No definida en la norma', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 10),
    ('P06-13', 'Mecanismos para asegurar la conservación de los bienes de la organización y del Estado', 'Cumple si · existen y se aplican mecanismos definidos para la conservación de los bienes a cargo del SF.', 'Dec. 780/2016 Art. 2.5.3.10.7 num. 9 (p. 286)', 'v2', 'El servicio farmacéutico desarrolla y aplica mecanismos para asegurar la conservación de los bienes de la organización y del Estado (función del SF).', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de IPS/prestadores y a farmacias-droguerías, droguerías o personas autorizadas contratadas en el SGSSS (Dec. 780 art. 2.5.3.10.11 par. 2); no aplica a F-D/DRG no contratadas en el SGSSS ni a AEF/DD, sometidas solo a recepción y almacenamiento (y dispensación las F-D/DRG)', NULL, NULL, NULL::jsonb, NULL::jsonb, 11),
    ('P06-14', 'Extramural domiciliaria: medicamentos según inventario definido en procesos prioritarios', 'Cumple si · los medicamentos disponibles para la atención extramural corresponden al inventario establecido y documentado en procesos prioritarios.', 'Res. 3100/2019 Manual 11.1.4 num. 16.2 (p.73)', 'v2', 'En la modalidad extramural domiciliaria, cuando se requiera, se cuenta con medicamentos de acuerdo con el inventario establecido por el prestador conforme a lo documentado en sus procesos prioritarios.', 'Inventario establecido y documento de procesos prioritarios', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS con modalidad extramural domiciliaria', 'Solo si el punto entrega medicamentos a domicilio', NULL, NULL::jsonb, NULL::jsonb, 12),
    ('P06-15', 'Kit de derrames: información documentada de almacenamiento, vencimientos y custodia', 'Cumple si · existe información documentada de almacenamiento, conservación, control de vencimientos, uso y custodia del contenido del kit de derrames.', 'Res. 3100/2019 Manual 11.1.5 num. 23 (p.76)', 'v2', 'El prestador cuenta con información documentada de las condiciones de almacenamiento, conservación, control de fechas de vencimiento, uso y custodia de los medicamentos, DM e insumos contenidos en los kits de derrames de medicamentos.', 'Información documentada', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS (servicios con kit de derrames de medicamentos)', NULL, NULL, NULL::jsonb, NULL::jsonb, 13),
    ('P06-16', 'Suficiencia de dispositivos médicos según su frecuencia de uso', 'Cumple si · la cantidad de DM disponibles es suficiente para su frecuencia de uso (incluidos tiempos de esterilización cuando aplique).', 'Res. 3100/2019 Manual 11.1.4 num. 9 (p.72)', 'v2', 'La cantidad de dispositivos médicos disponibles corresponde a su frecuencia de uso, incluidos los tiempos del proceso de esterilización cuando aplique.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que usan dispositivos médicos', NULL, NULL, NULL::jsonb, NULL::jsonb, 14),
    ('P06-17', 'Extramural domiciliaria: DM e insumos según patología o eventos de salud pública', 'Cumple si · en las atenciones extramurales que lo requieren, se dispone de los DM e insumos acordes con la patología o el evento de interés en salud pública.', 'Res. 3100/2019 Manual 11.1.4 num. 16.1 (p.73)', 'v2', 'En la modalidad extramural domiciliaria se cuenta, cuando se requiera, con dispositivos médicos e insumos asistenciales según la patología del paciente o los eventos de interés en salud pública.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS con modalidad extramural domiciliaria', 'Solo si el punto entrega medicamentos a domicilio', NULL, NULL::jsonb, NULL::jsonb, 15),
    ('I04-02', 'Registros permanentes de temperatura y humedad relativa con gestión de desviaciones', 'Cumple si · existen registros de temperatura y humedad relativa de cada sitio de almacenamiento, continuos en el periodo revisado, y (en prestadores REPS) evidencia de acciones ante valores fuera de lo recomendado por el fabricante.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. h (p.24); T.II Cap.II num. 3.2 lit. i (p.46); Res. 3100/2019 Manual 11.1.4 num. 7 (p.72)', 'v2', 'Se llevan registros permanentes de control de la temperatura y la humedad relativa de los sitios de almacenamiento; en prestadores REPS se evidencia su registro, control y gestión.', 'Registros de temperatura y humedad relativa', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 16),
    ('I04-03', 'Información documentada del seguimiento a temperatura y humedad', 'Cumple si · existe información documentada vigente del seguimiento a las condiciones ambientales de temperatura y humedad.', 'Res. 3100/2019 Manual 11.3.2, PP num. 15.4 (p.100)', 'v2', 'El servicio farmacéutico cuenta con información documentada del seguimiento a las condiciones ambientales de temperatura y humedad.', 'Información documentada (y registros, ver ítem anterior)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 17),
    ('I04-04', 'Iluminación natural o artificial adecuada para conservación e identificación', 'Cumple si · la iluminación de las áreas permite identificar los productos y manejar la documentación sin comprometer la conservación de los productos.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. e (p.24); T.II Cap.II num. 3.2 lit. f (p.46); Dec. 780/2016 Art. 2.5.3.10.11 par. 3 (p. 288); Res. 3100/2019 Manual 11.1.2 num. 18 (p.63)', 'v2', 'Las áreas cuentan con iluminación natural y/o artificial que permite la conservación de la calidad y la identificación de los medicamentos y DM y el buen manejo de la documentación.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 18),
    ('I04-05', 'Ventilación natural o artificial que no dependa de puertas o ventanas abiertas', 'Cumple si · existe sistema de ventilación (natural o artificial) que garantiza la conservación y no depende de ventanas o puertas abiertas que permitan contaminación.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. g (p.24); T.II Cap.II num. 3.2 lit. g (p.46); Dec. 780/2016 Art. 2.5.3.10.11 par. 3 (p. 289); Res. 3100/2019 Manual 11.1.2 num. 18 (p.63)', 'v2', 'Existe un sistema de ventilación natural y/o artificial que garantiza la conservación adecuada de los medicamentos y DM; no se entiende por ventilación natural las ventanas o puertas abiertas que puedan permitir la contaminación con polvo y suciedad del exterior.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 19),
    ('I04-06', 'Protección contra rayos solares directos y de fotosensibles frente a la luz', 'Cumple si · ningún medicamento o DM recibe incidencia directa de rayos solares y los fotosensibles están almacenados protegidos de la luz.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. h (p.46); Res. 1403/2007 Manual T.II Cap.II num. 3.6.1 lit. a (p.49)', 'v2', 'Se evita la incidencia directa de los rayos solares sobre medicamentos y DM, y los medicamentos fotosensibles se almacenan protegidos de la luz.', 'No definida en la norma (constatación física)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 20),
    ('I04-09', 'Inflamables en sitio ventilado, con T/HR controladas, iluminación, extintor y desagüe', 'Cumple si · el sitio de almacenamiento de inflamables reúne todas las condiciones listadas.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.6.1 lit. c (p.50)', 'v2', 'Los productos inflamables se almacenan en sitios con condiciones controladas de ventilación, temperatura y humedad, iluminación adecuada, extintor y suelo con desagüe.', 'No definida en la norma (constatación física)', 'Aplica solo si se almacenan productos inflamables', NULL, NULL, NULL::jsonb, NULL::jsonb, 21),
    ('I04-10', 'Espacios adecuados para medicamentos de gran volumen (≥ 500 ml)', 'Cumple si · existen espacios que permiten recibir, almacenar y distribuir o dispensar adecuadamente los medicamentos de gran volumen.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.6.1 lit. d (p.50)', 'v2', 'El servicio farmacéutico cuenta con espacios que permiten la recepción, almacenamiento y distribución y/o dispensación adecuados de los medicamentos de gran volumen (≥ 500 ml: líquidos endovenosos, expansores del plasma, soluciones para diálisis peritoneal, etc.).', 'No definida en la norma (constatación física)', 'Aplica solo a servicios farmacéuticos que manejen medicamentos de gran volumen (≥ 500 ml)', NULL, NULL, NULL::jsonb, NULL::jsonb, 22),
    ('I09-13', 'Áreas de almacenamiento de medicamentos sin acumulación de residuos', 'Cumple si · no se observan residuos acumulados en las áreas de almacenamiento.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. l (p. 47)', 'v2', 'En las áreas de almacenamiento no se acumulan residuos.', 'No definida en la norma (constatación física)', 'Aplica solo a establecimientos o servicios que realizan el proceso de almacenamiento (Res. 1403/2007, Manual T.II Cap.II)', NULL, NULL, NULL::jsonb, NULL::jsonb, 23)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C09', 'Cadena de frío', '', 'Procesos auditados', NULL, NULL, NULL, ARRAY['ESM', 'FA', 'NC']::text[], 'Anexo 5 p.10 (cadena de frío) · validaciones de la v2', 10) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P06-10', 'Procedimiento documentado de control de la cadena de frío', 'Cumple si · existe información documentada vigente del control de la cadena de frío (y, cuando se apliquen vacunas en el servicio, de su garantía en procesos prioritarios).', 'Res. 3100/2019 Manual 11.1.4 num. 4.8 (p.71); Res. 465/2025 Art. 3, par. 3, i) (p.4)', 'v2', 'El prestador cuenta con información documentada del control de la cadena de frío; si aplica vacunas en servicios distintos del de vacunación, documenta en procesos prioritarios la garantía de la cadena de frío.', 'Información documentada (procesos prioritarios)', 'Aplica solo a servicios farmacéuticos de prestadores inscritos en el REPS que manejen productos de cadena de frío', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P06-11', 'Plan de emergencia/contingencias para mantener la cadena de frío', 'Cumple si · existe plan de emergencia o contingencia documentado que garantiza la cadena de frío ante interrupciones de la energía eléctrica.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. k (p.47); Res. 3100/2019 Manual 11.1.4 num. 4.8 (p.71)', 'v2', 'Se cuenta con un plan de emergencia que garantice el mantenimiento de la cadena de frío en caso de interrupciones de la energía eléctrica; los prestadores REPS cuentan con información documentada del manejo de contingencias con la cadena de frío.', 'Plan de emergencia / información documentada de contingencias', 'Aplica solo si se almacenan medicamentos que requieren refrigeración o cadena de frío', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P07-08', 'Cadena de frío mantenida durante el transporte', 'Cumple si · en el transporte de productos de temperatura controlada se mantiene la cadena de frío y la integridad del producto.', 'Res. 1403/2007 Manual T.II Cap.III num. 7.4 lit. a (p.73)', 'v2', 'En el transporte de productos que requieren almacenamiento a temperatura controlada se asegura que se mantengan la cadena de frío y la integridad del producto.', 'Registros de temperatura durante el transporte (ver ítem de registros de condiciones especiales)', 'Aplica solo si se transportan productos que requieren temperatura controlada', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P07-09', 'Uso seguro de hielo seco sin contacto directo con los productos', 'Cumple si · al usar hielo seco, se aplican precauciones de seguridad y los productos no están en contacto directo con el hielo seco.', 'Res. 1403/2007 Manual T.II Cap.III num. 7.4 lit. b (p.73)', 'v2', 'Cuando se usa hielo seco en la cadena de frío se observan las precauciones de seguridad y se verifica que los productos no entren en contacto directo con él.', 'No definida en la norma', 'Aplica solo si se usa hielo seco en la cadena de frío', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('I04-01', 'Temperatura y humedad de almacenamiento controladas según lo recomendado por el fabricante', 'Cumple si · los sitios de almacenamiento cuentan con mecanismos instalados y en funcionamiento que mantienen la temperatura y la humedad relativa dentro de lo recomendado por el fabricante de los productos almacenados.', 'Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. d (p.23); Res. 1403/2007 Manual T.I Cap.II num. 1.1 lit. h (p.24); T.II Cap.II num. 3.2 lit. i (p.46); Res. 3100/2019 Manual 11.3.2, Infra num. 5.4 (p.98); Res. 3100/2019 Manual 11.1.4 num. 7 (p.72)', 'v2', 'Las áreas y sitios de almacenamiento tienen condiciones ambientales, temperatura y humedad relativa controladas, mediante mecanismos que garanticen las condiciones recomendadas por el fabricante (incluida la cadena de frío cuando aplique). En prestadores REPS, las reservas se almacenan en condiciones apropiadas de temperatura, humedad, ventilación, segregación y seguridad definidas por el fabricante.', 'No definida en la norma (constatación física de mecanismos y condiciones; soporte en los registros de temperatura y humedad)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('I04-07', 'Termolábiles y productos refrigerados almacenados en equipos de frío', 'Cumple si · todos los productos que requieren refrigeración están en cuartos fríos, refrigeradores o congeladores a la temperatura indicada por el fabricante y, en DD/AEF, existe el área de cadena de frío.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. k (p.47); Res. 1403/2007 Manual T.II Cap.II num. 3.6.1 lit. b (p.49); Res. 1403/2007 Manual T.I Cap.IV num. 2.2 lit. f (p.33)', 'v2', 'Los medicamentos termolábiles se almacenan a temperaturas adecuadas para evitar su descomposición con el calor, y los que requieren refrigeración se almacenan en cuartos fríos, refrigeradores o congeladores. Los depósitos de drogas (y AEF por remisión) cuentan con área de almacenamiento para materias primas y medicamentos que requieren cadena de frío.', 'No definida en la norma (constatación física)', 'Aplica solo si se almacenan medicamentos termolábiles o que requieren refrigeración', NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('I04-08', 'Mecanismos que registran la temperatura de los medios de refrigeración', 'Cumple si · cada medio de refrigeración dispone de un mecanismo que registra la temperatura y existen registros disponibles.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. k (p.47)', 'v2', 'Los medios de refrigeración disponen de mecanismos que registren la temperatura.', 'No definida en la norma (se desprende: registros de temperatura de los equipos de refrigeración)', 'Aplica solo si se almacenan productos que requieren refrigeración', NULL, NULL, NULL::jsonb, NULL::jsonb, 7),
    ('I05-06', 'Cantidad de medios de refrigeración acorde con las necesidades de almacenamiento', 'Cumple si · la cantidad de cuartos fríos, refrigeradores o congeladores es suficiente para los productos que requieren refrigeración y, si la entidad territorial dispuso aumentarla, se cumplió.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.2 lit. k (p.47)', 'v2', 'La cantidad de medios de refrigeración la determinan las necesidades de almacenamiento; la entidad territorial de salud la verifica y puede disponer su aumento.', 'No definida en la norma (constatación física)', 'Aplica solo si se almacenan productos que requieren refrigeración', NULL, NULL, NULL::jsonb, NULL::jsonb, 8),
    ('CF-01', 'Lectura de temperatura en sitio dentro del rango del producto', 'Cumple si · la temperatura medida en el equipo está dentro del rango de almacenamiento indicado por el fabricante.', 'Propuesto en la v2: sin soporte en la fuente de verdad', 'propuesto', '', '', '', NULL, NULL, '[{"label":"Temperatura leída","unidad":"°C"},{"label":"Rango declarado","unidad":"°C"}]'::jsonb, NULL::jsonb, 9),
    ('CF-02', 'Registro continuo de temperatura del periodo', 'Cumple si · hay registro de temperatura completo para el periodo revisado, sin excursiones sin gestionar.', 'Propuesto en la v2: sin soporte en la fuente de verdad', 'propuesto', '', '', '', NULL, NULL, '[{"label":"Excursiones en el periodo","unidad":"n.º"}]'::jsonb, NULL::jsonb, 10),
    ('CF-03', 'Equipos de refrigeración con mantenimiento y calibración vigentes', 'Cumple si · los equipos tienen hoja de vida, mantenimiento y calibración vigentes.', 'Propuesto en la v2: sin soporte en la fuente de verdad', 'propuesto', '', '', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 11),
    ('CF-04', 'Plan de contingencia ante fallas de energía o de equipos', 'Cumple si · existe un plan documentado y el personal lo conoce.', 'Propuesto en la v2: sin soporte en la fuente de verdad', 'propuesto', '', '', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 12),
    ('CF-05', 'Cadena de frío en la entrega al usuario', 'Cumple si · los medicamentos refrigerados se entregan en condiciones que conservan la cadena de frío.', 'Propuesto en la v2: sin soporte en la fuente de verdad', 'propuesto', '', '', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 13)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C10', 'Oportunidad, pendientes y entrega a domicilio', '', 'Procesos auditados', NULL, NULL, NULL, ARRAY['ESM', 'FA']::text[], 'Anexo 3 p.4 (entrega y seguimiento; oportunidad) · validaciones de la v2', 11) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P10-01', 'Entrega completa de lo prescrito al momento de la reclamación', 'Cumple si · en las dispensaciones revisadas se entregó la totalidad de lo prescrito al momento de la reclamación (o del recibo de la solicitud hospitalaria) y los faltantes, si los hubo, se gestionaron como pendientes.', 'Res. 1403/2007 Art. 4 num. 10 (p. 3); Manual T.II Cap.II num. 5.1.2 (p. 55); Circ. 017/2026 MSPS (transcribe art. 131 Dec. 019/2012) Num. 2 Marco normativo, art. 131 inc. 1 (p. 7); Ley 1751/2015 Art. 10 lit. i) (p. 2)', 'v2', 'Debe entregarse la totalidad de los medicamentos y dispositivos médicos prescritos en la primera comparecencia del interesado (o al recibo de la solicitud del servicio hospitalario), sin retrasos que pongan en riesgo la salud o la vida del paciente y sin dilaciones en la provisión; para los medicamentos del plan de beneficios, el suministro debe hacerse bajo un procedimiento que asegure la entrega completa e inmediata.', 'No definida en la norma', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P10-02', 'Mecanismo para determinar la demanda insatisfecha y corregir desviaciones', 'Cumple si · existe un mecanismo operativo para identificar la demanda insatisfecha y evidencia de corrección de las desviaciones detectadas.', 'Res. 1403/2007 Art. 4 num. 10 (p. 3)', 'v2', 'El servicio farmacéutico debe contar con mecanismos para determinar permanentemente la demanda insatisfecha de servicios y corregir rápidamente las desviaciones que se detecten; la entidad de la que forma parte garantiza los recursos necesarios.', 'No definida en la norma', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P10-03', 'Procedimiento de entrega completa y de pendientes concertado con la EAPB', 'Cumple si · existe un procedimiento acordado con cada EAPB contratante que cubre la entrega inmediata y completa y el mecanismo excepcional de entrega en máximo 48 horas.', 'Res. 1604/2013 Art. 5 num. 7 (p. 3); Res. 1604/2013 Art. 5 num. 6 (p. 3)', 'v2', 'La IPS (incluido su servicio farmacéutico) debe concertar con la EAPB los procedimientos que aseguren la entrega inmediata y completa de los medicamentos o la entrega derivada del mecanismo excepcional en el lugar de residencia o trabajo del afiliado, cuando este lo autorice, dentro de las 48 horas siguientes a la reclamación; la EAPB establece los procedimientos que aseguran la entrega en esos términos.', 'No definida en la norma (se desprende: procedimiento concertado con la EAPB)', 'Aplica solo a IPS/servicios farmacéuticos de la red de una EAPB que dispensan medicamentos a sus afiliados', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P10-04', 'Registro del pendiente en el punto y ante el asegurador al momento de la reclamación', 'Cumple si · cada entrega incompleta revisada tiene registro de pendiente con fecha y hora de la reclamación, también registrado ante el asegurador.', 'Circ. 017/2026 MSPS (num. 3.2.4; transcribe Res. 1809/2025 art. 17) Num. 3.2.4 (p. 13); num. 2, art. 17 Res. 1809/2025 transcrito (p. 9)', 'v2', 'Cuando se generen pendientes, el gestor farmacéutico debe registrarlos en el punto de dispensación al momento de la reclamación y registrar ante el asegurador el estado de la entrega de las tecnologías que no pudieron entregarse, en el mismo momento de la reclamación del usuario.', 'Registro del pendiente (contenido mínimo no definido en la norma)', 'Aplica solo a puntos de dispensación operados por gestores farmacéuticos donde se generen pendientes', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P10-05', 'Documento soporte del pendiente entregado al usuario', 'Cumple si · cada pendiente revisado tiene documento soporte entregado al usuario (copia física o registro electrónico).', 'Circ. 017/2026 MSPS (transcribe Res. 1809/2025 art. 17) Num. 2, art. 17 Res. 1809/2025 transcrito (p. 9)', 'v2', 'Cuando se genere un pendiente, debe entregarse al usuario un documento soporte, físico o electrónico, para realizar el seguimiento y la entrega.', 'Documento soporte físico o electrónico entregado al usuario', 'Aplica solo a puntos de dispensación operados por gestores farmacéuticos donde se generen pendientes', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P10-06', 'Información a la EAPB del estado de cada entrega y notificación de pendientes', 'Cumple si · existen reportes a la EAPB que identifican las entregas oportunas y los pendientes con su causa, y notificación de cada pendiente revisado.', 'Circ. 017/2026 MSPS (transcribe Res. 1809/2025 art. 16) Num. 2, art. 16 Res. 1809/2025 transcrito (p. 8); Circ. 017/2026 MSPS Num. 3.2.4, segunda parte (p. 13); Circ. 017/2026 MSPS Num. 3.1.2 vii) (p. 11)', 'v2', 'El gestor farmacéutico debe proporcionar a la EAPB con la que tiene acuerdo de voluntades información verificable sobre el estado de entrega de los medicamentos: si se realizó dentro del término del art. 131 del Dec. 019/2012 y del art. 1 de la Res. 1604/2013, o si quedó pendiente, exponiendo las razones de la no entrega; además debe informar oportunamente cada pendiente a la EPS para que se gestione su entrega a domicilio en las 48 horas siguientes.', 'Información o reportes enviados a la EAPB (formato no definido en la norma)', 'Aplica solo a gestores farmacéuticos con acuerdo de voluntades con una EAPB', 'Solo si el punto entrega medicamentos a domicilio', NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P10-07', 'Información de cada entrega con los datos mínimos del art. 8 de la Res. 1604/2013', 'Cumple si · los registros del establecimiento contienen todos los campos listados y existen envíos de esa información a la EAPB.', 'Res. 1604/2013 Art. 5 num. 7 inc. final (p. 3); Res. 1604/2013 Art. 8 nums. 1-9 y 11 (p. 5)', 'v2', 'La IPS debe proporcionar a la EAPB la información requerida para el reporte de la Res. 1604/2013: 1) nombre, tipo y número de identificación y género del afiliado; 2) domicilio, ciudad, departamento y teléfono; 3) nombre y código de la EAPB que realiza la entrega; 4) medicamentos prescritos (DCI, concentración, forma farmacéutica, vía de administración, frecuencia y duración del tratamiento); 5) cantidad prescrita y cantidad entregada; 6) diagnóstico principal y relacionado; 7) fecha de prescripción; 8) fecha de autorización de entrega; 9) fecha de registro de entrega; 11) registro de los usuarios que no autorizan la entrega en residencia o trabajo.', 'Base de datos o registros con los campos del art. 8; envíos de la información a la EAPB', 'Aplica solo a IPS/servicios farmacéuticos de la red de una EAPB', 'Solo si el punto entrega medicamentos a domicilio', NULL, NULL::jsonb, NULL::jsonb, 7),
    ('P10-08', 'Entrega de pendientes en máximo 48 horas desde la reclamación', 'Cumple si · en los pendientes revisados la entrega completa en residencia o lugar de trabajo se realizó dentro de las 48 horas siguientes a la reclamación (salvo constancia de no autorización del afiliado).', 'Res. 1604/2013 Art. 1 (p. 1); Circ. 017/2026 MSPS (transcribe art. 131 Dec. 019/2012) Num. 2 Marco normativo, art. 131 inc. 2 (pp. 7-8); Circ. 017/2026 MSPS Num. 3.2.6 (p. 13); Circ. 017/2026 MSPS Num. 3.1.2 v) (p. 11)', 'v2', 'Cuando la entrega no pueda hacerse completa al momento de la reclamación, el faltante (pendiente) debe entregarse en un lapso no mayor a 48 horas, contadas desde que el afiliado reclama, en su lugar de residencia o trabajo si el afiliado lo autoriza. Los gestores farmacéuticos deben garantizar la entrega en el domicilio de los pendientes generados en el punto de dispensación, y la entrega debe ser oportuna y completa en el punto de dispensación principal o en el domicilio.', 'No definida en la norma (se desprende: registro del pendiente y registro de entrega a satisfacción firmado, Res. 1604 art. 8)', 'Aplica solo cuando la entrega al momento de la reclamación fue incompleta (pendientes)', 'Solo si el punto entrega medicamentos a domicilio', NULL, NULL::jsonb, NULL::jsonb, 8),
    ('P10-09', 'Pendientes de crónicos de más de 30 días: no se exige nueva prescripción', 'Cumple si · en los pendientes de pacientes crónicos con más de 30 días la entrega se hace con el registro del pendiente, sin exigir nueva fórmula.', 'Circ. 017/2026 MSPS (transcribe Res. 1809/2025 art. 16 par.) Num. 2, art. 16 par. Res. 1809/2025 transcrito (p. 9)', 'v2', 'En enfermedades crónicas, cuando se genere un pendiente y el medicamento o dispositivo médico no se entregue después de 30 días, el estado pendiente reactiva la fórmula médica: no se requiere una nueva prescripción, para no imponer cargas administrativas al usuario.', 'No definida en la norma', 'Aplica solo a pendientes de pacientes con enfermedades crónicas', NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P10-10', 'Atención en la red alterna de pendientes no entregados tras 48 horas', 'Cumple si · el establecimiento de la red alterna (gestor alterno o IPS) atiende y entrega el pendiente reclamado por el afiliado una vez vencidas las 48 horas.', 'Circ. 017/2026 MSPS Num. 3.1.2 vi) (p. 11)', 'v2', 'Si pasadas las 48 horas reglamentarias el gestor no entrega el pendiente, el afiliado queda habilitado para reclamarlo y recibirlo en la red alterna de gestores o ante las IPS, en los términos del parágrafo del art. 2.5.3.10.5 del Dec. 780/2016.', 'No definida en la norma', 'Aplica solo a establecimientos de la red alterna de gestores farmacéuticos o IPS designados por la EPS', NULL, NULL, NULL::jsonb, NULL::jsonb, 10),
    ('P10-11', 'Datos de contacto del afiliado confidenciales, veraces y actualizados', 'Cumple si · los datos de domicilio y contacto de los pendientes con entrega domiciliaria están completos, actualizados y protegidos.', 'Res. 1604/2013 Art. 7 num. 1 (p. 4)', 'v2', 'Debe garantizarse la confidencialidad, veracidad y actualización de la información de los afiliados, para evitar inconsistencias e imposibilidad en la entrega de los medicamentos en el lugar de residencia o trabajo cuando estos la autoricen.', 'No definida en la norma', 'Aplica solo si el establecimiento realiza entrega domiciliaria de pendientes', NULL, NULL, NULL::jsonb, NULL::jsonb, 11),
    ('P10-12', 'Programación con el afiliado de la entrega en residencia o trabajo', 'Cumple si · los pendientes con entrega domiciliaria revisados tienen la programación acordada con el afiliado.', 'Res. 1604/2013 Art. 7 num. 2 (p. 4)', 'v2', 'La entrega de medicamentos en el lugar de residencia o trabajo debe programarse con el afiliado cuando este la autorice.', 'No definida en la norma', 'Aplica solo a pendientes con autorización de entrega domiciliaria', NULL, NULL, NULL::jsonb, NULL::jsonb, 12),
    ('P10-13', 'Constancia de no autorización y entrega del pendiente en el establecimiento dispuesto', 'Cumple si · cada pendiente sin entrega domiciliaria tiene la constancia de no autorización y fue entregado en el establecimiento dispuesto.', 'Res. 1604/2013 Art. 7 num. 2 inc. 2 (p. 4)', 'v2', 'Cuando el afiliado no autorice la entrega en su residencia o trabajo, debe dejarse constancia de ello y la entrega se realiza en los establecimientos dispuestos para tal fin.', 'Constancia de no autorización (art. 7 num. 2); registro de usuarios que no autorizan (art. 8 num. 11)', 'Aplica solo a pendientes en los que el afiliado no autoriza la entrega domiciliaria', NULL, NULL, NULL::jsonb, NULL::jsonb, 13),
    ('P10-14', 'Entrega por el mecanismo excepcional realizada por Químico Farmacéutico o TRF', 'Cumple si · los registros de entrega de pendientes identifican a un Químico Farmacéutico o Tecnólogo en Regencia de Farmacia como responsable de la entrega.', 'Res. 1604/2013 Art. 7 num. 3 (p. 4)', 'v2', 'La entrega completa e inmediata de los medicamentos mediante el mecanismo excepcional debe ser realizada por un profesional Químico Farmacéutico o un Tecnólogo en Regencia de Farmacia con competencias para informar al usuario sobre el uso adecuado del medicamento y la importancia de la farmacoterapia.', 'No definida en la norma', 'Aplica solo a entregas de pendientes por el mecanismo excepcional (entrega incompleta al reclamar)', NULL, NULL, NULL::jsonb, NULL::jsonb, 14),
    ('P10-15', 'Información verbal y escrita sobre uso adecuado en la entrega de pendientes', 'Cumple si · en las entregas de pendientes se entrega información escrita sobre uso adecuado y se brinda información verbal.', 'Res. 1604/2013 Art. 7 num. 3 (p. 4)', 'v2', 'En la entrega por el mecanismo excepcional debe brindarse al usuario información sobre el uso adecuado del medicamento y la importancia de la farmacoterapia, entre otros, de forma verbal y escrita.', 'Información escrita entregada al usuario (formato y contenido no definidos en la norma)', 'Aplica solo a entregas de pendientes por el mecanismo excepcional (entrega incompleta al reclamar)', NULL, NULL, NULL::jsonb, NULL::jsonb, 15),
    ('P10-16', 'Entrenamiento y formación del personal que transporta los pendientes', 'Cumple si · el personal de transporte cuenta con soportes de entrenamiento y formación en la actividad.', 'Res. 1604/2013 Art. 7 num. 4 – Personal (p. 4)', 'v2', 'El personal propio o contratado que realice el transporte de medicamentos en el mecanismo excepcional debe contar con entrenamiento y formación al respecto.', 'No definida en la norma', 'Aplica solo si el establecimiento realiza transporte de medicamentos para la entrega domiciliaria de pendientes', NULL, NULL, NULL::jsonb, NULL::jsonb, 16),
    ('P10-17', 'Procedimientos escritos del transporte para la entrega de pendientes', 'Cumple si · existen procedimientos escritos que incluyen todos los contenidos mínimos listados.', 'Res. 1604/2013 Art. 7 num. 4 – Documentación (p. 4)', 'v2', 'Deben existir procedimientos escritos que describan, como mínimo, las principales operaciones que puedan afectar la calidad de los medicamentos, el mantenimiento y limpieza de vehículos e instalaciones, las condiciones de manipulación, la seguridad y la trazabilidad, entre otros.', 'Procedimientos escritos', 'Aplica solo si el establecimiento realiza transporte de medicamentos para la entrega domiciliaria de pendientes', NULL, NULL, NULL::jsonb, NULL::jsonb, 17),
    ('P10-18', 'Trazabilidad de los medicamentos en todas las actividades de la entrega', 'Cumple si · es posible reconstruir el recorrido de los medicamentos desde la dispensación hasta la entrega al afiliado.', 'Res. 1604/2013 Art. 7 num. 4 – Trazabilidad (p. 4)', 'v2', 'La trazabilidad de los medicamentos debe estar siempre garantizada durante todas las actividades realizadas para la entrega por el mecanismo excepcional.', 'No definida en la norma', 'Aplica solo a entregas de pendientes por el mecanismo excepcional (entrega incompleta al reclamar)', NULL, NULL, NULL::jsonb, NULL::jsonb, 18),
    ('P10-19', 'Autoinspecciones periódicas a los medios de transporte de la entrega', 'Cumple si · hay evidencia de autoinspecciones periódicas de todos los medios de transporte utilizados.', 'Res. 1604/2013 Art. 7 num. 4 – Autoinspecciones (p. 5)', 'v2', 'Deben realizarse autoinspecciones periódicas a todos los medios de transporte utilizados para la entrega de medicamentos, especialmente en los aspectos de riesgo del proceso, cumpliendo la normatividad vigente sobre esos medios de transporte.', 'No definida en la norma', 'Aplica solo si el establecimiento realiza transporte de medicamentos para la entrega domiciliaria de pendientes', NULL, NULL, NULL::jsonb, NULL::jsonb, 19),
    ('P10-20', 'Custodia y seguridad de medicamentos, personal y afiliado en la entrega domiciliaria', 'Cumple si · existen medidas de custodia y seguridad aplicadas a la entrega domiciliaria.', 'Res. 1604/2013 Art. 7 num. 5 (p. 5)', 'v2', 'Debe garantizarse la custodia y seguridad de los medicamentos, del personal encargado de realizar la entrega y del afiliado en el lugar de residencia o trabajo, cuando este la autorice.', 'No definida en la norma', 'Aplica solo si el establecimiento realiza entrega domiciliaria de pendientes', 'Solo si el punto entrega medicamentos a domicilio', NULL, NULL::jsonb, NULL::jsonb, 20),
    ('P10-21', 'Registro numerado de entrega a satisfacción, firmado por el afiliado y archivado', 'Cumple si · todos los registros revisados tienen número y firma de recibido del afiliado y están archivados y disponibles.', 'Res. 1604/2013 Art. 8 num. 10 e inc. final (p. 5)', 'v2', 'Cada entrega por el mecanismo excepcional debe tener un número de registro de entrega a satisfacción (propio de la EAPB, que permita la trazabilidad de la entrega), con la firma de recibido del afiliado; estos registros deben conservarse en archivo.', 'Registro de entrega a satisfacción numerado y firmado por el afiliado; archivo de los registros', 'Aplica solo a entregas de pendientes por el mecanismo excepcional (entrega incompleta al reclamar)', NULL, NULL, NULL::jsonb, NULL::jsonb, 21),
    ('P10-22', 'Información actualizada para el seguimiento y monitoreo de la entrega', 'Cumple si · la información de entregas y pendientes está al día en el sistema del gestor al momento de la visita.', 'Circ. 017/2026 MSPS Num. 3.2.5 (p. 13)', 'v2', 'El gestor farmacéutico debe mantener actualizada la información que permita el seguimiento y monitoreo de la entrega de medicamentos.', 'No definida en la norma', 'Aplica solo a gestores farmacéuticos (verificable en el punto de dispensación o en la sede del gestor)', NULL, NULL, NULL::jsonb, NULL::jsonb, 22),
    ('P10-23', 'Acciones de seguimiento a los indicadores de entrega (Res. 1809/2025)', 'Cumple si · el gestor tiene definidas acciones de seguimiento a los indicadores de entrega, incluido el tiempo de entrega de pendientes.', 'Circ. 017/2026 MSPS (num. 3.2.7; transcribe Res. 1809/2025 num. 10.3) Num. 3.2.7 (p. 13); num. 2, indicador 10.3 transcrito (p. 8)', 'v2', 'El gestor farmacéutico debe definir las acciones para el seguimiento de los indicadores de entrega de medicamentos de la Res. 1809/2025, entre ellos el tiempo de entrega (sumatoria de días desde la generación del registro del pendiente hasta la entrega efectiva, sobre el total de pendientes generados y registrados en el período).', 'No definida en la norma', 'Aplica solo a gestores farmacéuticos (verificable en el punto de dispensación o en la sede del gestor)', NULL, NULL, NULL::jsonb, NULL::jsonb, 23),
    ('P10-24', 'Pago oportuno del gestor a sus proveedores', 'Cumple si · no se evidencian interrupciones o incumplimientos de pedidos atribuibles a falta de pago a proveedores.', 'Circ. 017/2026 MSPS Num. 3.2.1 (p. 13)', 'v2', 'El gestor farmacéutico debe garantizar el pago oportuno a sus proveedores para evitar interrupciones o incumplimientos en la entrega de pedidos de medicamentos.', 'No definida en la norma', 'Aplica solo a gestores farmacéuticos (verificable en el punto de dispensación o en la sede del gestor)', NULL, NULL, NULL::jsonb, NULL::jsonb, 24),
    ('P10-25', 'Más de un oferente para los medicamentos a cargo del gestor', 'Cumple si · el gestor tiene identificado más de un oferente por medicamento, salvo los de oferente único (ver ítem siguiente).', 'Circ. 017/2026 MSPS Num. 3.2.2 (p. 13)', 'v2', 'El gestor farmacéutico debe garantizar tener más de un oferente para los medicamentos a su cargo.', 'No definida en la norma', 'Aplica solo a gestores farmacéuticos (verificable en el punto de dispensación o en la sede del gestor)', NULL, NULL, NULL::jsonb, NULL::jsonb, 25),
    ('P10-26', 'Plan de mitigación para medicamentos de oferente único', 'Cumple si · existe plan de mitigación para cada medicamento de oferente único que maneja el gestor.', 'Circ. 017/2026 MSPS Num. 3.2.3 (p. 13)', 'v2', 'Para medicamentos con un solo oferente en el mercado, el gestor farmacéutico debe contar con un plan de mitigación ante una eventual interrupción o salida del mercado, mediante el mecanismo de importación de medicamentos vitales no disponibles (Circular Externa 027 de 2025 y Auto 525 de 2025).', 'Plan de mitigación (se desprende del texto)', 'Aplica solo a gestores farmacéuticos que manejan medicamentos de oferente único', NULL, NULL, NULL::jsonb, NULL::jsonb, 26),
    ('P10-27', 'Seguimiento al abastecimiento y respuesta a solicitudes de información', 'Cumple si · hay evidencia de seguimiento al abastecimiento y las solicitudes de información recibidas tienen respuesta.', 'Circ. 017/2026 MSPS Num. 3.2.8 (a) y (b) (p. 13)', 'v2', 'El gestor farmacéutico debe realizar seguimiento al abastecimiento de medicamentos y dispositivos médicos y dar respuesta oportuna a las solicitudes de información relacionadas con dicho abastecimiento.', 'No definida en la norma', 'Aplica solo a gestores farmacéuticos (verificable en el punto de dispensación o en la sede del gestor)', NULL, NULL, NULL::jsonb, NULL::jsonb, 27),
    ('P10-28', 'Notificación de escasez o desabastecimiento por el canal del MSPS', 'Cumple si · cada caso de escasez o desabastecimiento del período tiene reporte enviado por el canal indicado.', 'Circ. 017/2026 MSPS Num. 3.2.8 (c) e inciso siguiente (pp. 13-14)', 'v2', 'El gestor farmacéutico debe notificar los casos de escasez o desabastecimiento a través de la herramienta de alertas del Sistema de Monitoreo del Abastecimiento del MSPS (Res. 1411/2022) o, mientras no funcione, al correo desabastecimiento@minsalud.gov.co con los formatos del micrositio del MSPS y copia a desabastecimientomedicamentos@invima.gov.co (medicamentos) o desabastecimientodm@invima.gov.co (dispositivos).', 'Reportes en la herramienta o correos con los formatos del micrositio y copia al INVIMA', 'Aplica solo a gestores farmacéuticos con casos de escasez o desabastecimiento', NULL, NULL, NULL::jsonb, NULL::jsonb, 28),
    ('P10-29', 'Urgencias: no se exige autorización administrativa prestador-asegurador', 'Cumple si · los medicamentos y tecnologías de urgencias se entregan sin exigir autorización administrativa del asegurador.', 'Ley 1751/2015 Art. 14 (p. 3)', 'v2', 'En la atención de urgencia no se exige ningún tipo de autorización administrativa entre el prestador y la entidad que cumple la función de gestión de servicios de salud para acceder a servicios y tecnologías.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de IPS con servicio de urgencias', NULL, NULL, NULL::jsonb, NULL::jsonb, 29)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C11', 'Servicio farmacéutico contratado y legalidad', 'Vacío 5: la Res. 3100 no exige verificar el servicio farmacéutico contratado (interdependencia: No aplica). Es el modelo del OPL en el ESM.', 'Cruce Res. 3100 vs Res. 1403 y 2955', NULL, NULL, NULL, ARRAY['ESM', 'FA']::text[], 'Res. 1403/2007 Art. 22-23; Manual T.I Cap.II-III y V · cruce 3100 vs 1403', 12) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P01-24', 'Procesos del SF contratados: contratista con documentación legal y cumplimiento', 'Cumple si · el contrato y los documentos legales del contratista están vigentes y el contratista cumple las condiciones obligatorias de los procesos contratados.', 'Res. 1403/2007 Art. 22 num. 2 lit. a (p.12)', 'v2', 'Cuando las actividades o procesos del servicio farmacéutico relacionados con medicamentos y dispositivos médicos son contratados, la documentación del contratista es legal y este cumple permanentemente las condiciones, requisitos y procedimientos obligatorios.', 'Contrato y documentación legal del contratista', 'Aplica solo a IPS que contratan actividades o procesos del servicio farmacéutico', 'Solo servicio farmacéutico de IPS (ESM)', '5 · Servicio farmacéutico contratado', NULL::jsonb, NULL::jsonb, 1),
    ('P01-25', 'SF hospitalario contratado: declarado y prestado desde el interior de la IPS', 'Cumple si · la contratación está declarada y el contratista opera desde el interior de la IPS.', 'Res. 1403/2007 Manual T.I Cap.II inc. 2 (p.22)', 'v2', 'La IPS que contrata actividades o procesos relacionados con medicamentos y dispositivos médicos para sus pacientes hospitalizados lo declara, y el contratista presta los servicios desde el interior de la IPS contratante.', 'Declaración de la contratación; constatación de que el contratista opera dentro de la IPS', 'Aplica solo a IPS que contratan actividades o procesos del servicio farmacéutico para pacientes hospitalizados', 'Solo servicio farmacéutico de IPS (ESM)', '5 · Servicio farmacéutico contratado', NULL::jsonb, NULL::jsonb, 2),
    ('P01-26', 'EF que presta procesos del SF por cuenta de terceros o contratado cumple íntegramente', 'Cumple si · los procesos que presta por cuenta de terceros o bajo contrato cumplen todas las condiciones del Capítulo, del modelo de gestión, de la normatividad aplicable a cada proceso y las condiciones esenciales del SF de la entidad contratante.', 'Dec. 780/2016 Art. 2.5.3.10.11 par. 2 (p. 288); Dec. 780/2016 Art. 2.5.3.10.11 par. 4 (p. 289); Res. 1403/2007 Manual T.I Cap.V num. 1.4 inc. 1 (p.36); num. 2.3 inc. 1 (p.40)', 'v2', 'El establecimiento farmacéutico que realiza actividades o procesos propios del servicio farmacéutico por cuenta de otra persona cumple las condiciones y requisitos del Capítulo de servicio farmacéutico del Dec. 780, del modelo de gestión y demás normas (responde solidariamente con el contratante); las farmacias-droguerías, droguerías o personas autorizadas contratadas en el SGSSS cumplen íntegramente el Capítulo y el modelo de gestión; cuando presta procesos a una IPS se somete a la normatividad aplicable a cada proceso y cumple las condiciones esenciales del servicio farmacéutico de la entidad contratante.', 'Contrato; verificación de las condiciones de los procesos contratados', 'Aplica solo a establecimientos farmacéuticos que prestan procesos del servicio farmacéutico por cuenta de terceros o contratados (en el SGSSS o por una IPS)', 'Solo farmacia alterna', '5 · Servicio farmacéutico contratado', NULL::jsonb, NULL::jsonb, 3),
    ('P01-02', 'Realiza únicamente los procesos expresamente autorizados o habilitados', 'Cumple si · ninguno de los procesos observados excede los expresamente autorizados o habilitados.', 'Res. 1403/2007 Art. 23 num. 2 (p.13); Dec. 780/2016 Art. 2.5.3.10.2 (p. 281)', 'v2', 'El establecimiento o servicio farmacéutico realiza únicamente los procesos (almacenamiento, comercialización, distribución, dispensación u otros) expresamente señalados en su autorización; el Capítulo de servicio farmacéutico del Dec. 780 se aplica en relación con el o los procesos para los que esté autorizado.', 'Autorización de funcionamiento o habilitación vs. procesos observados en la visita', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P01-03', 'SF de baja complejidad que hace procesos de mediana/alta cumple sus condiciones', 'Cumple si · para cada proceso de mediana o alta complejidad que realiza el SF de baja complejidad, se verifican las condiciones y requisitos específicos de ese proceso.', 'Res. 1403/2007 Art. 7 parágrafo (p.5)', 'v2', 'Cuando en el servicio farmacéutico de baja complejidad se realiza un proceso del servicio farmacéutico de mediana y alta complejidad, se cumplen las condiciones y requisitos exigidos para ese proceso de mayor complejidad.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de baja complejidad que realicen procesos de mediana o alta complejidad (Res. 1403/2007 art. 7 num. 2)', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P01-27', 'SF ambulatorio en local interno de la institución no vende al público en general', 'Cumple si · no hay venta de medicamentos o dispositivos médicos al público en general en el local interno.', 'Res. 1403/2007 Manual T.I Cap.III num. 1 inc. 4 (p.28)', 'v2', 'Cuando el servicio farmacéutico ambulatorio (propio o contratado) se presta en local ubicado en el interior de la institución de salud, no se venden medicamentos ni dispositivos médicos al público en general.', 'No definida en la norma (observación de ventas y facturación)', 'Aplica solo a servicios farmacéuticos ambulatorios (propios o contratados) que funcionan en local ubicado en el interior de la institución de salud', 'Solo servicio farmacéutico de IPS (ESM)', NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P01-32', 'IPS con atención domiciliaria contratada: declarada a la ETS que la habilitó', 'Cumple si · existe la declaración ante la ETS de la atención domiciliaria contratada.', 'Res. 1403/2007 Manual T.I Cap.III num. 1.1 inc. 4 (p.29)', 'v2', 'Si la atención domiciliaria se presta por contrato a pacientes de una IPS, la institución declara esta circunstancia a la entidad territorial de salud que la habilitó.', 'Declaración ante la entidad territorial de salud', 'Aplica solo a IPS con atención domiciliaria prestada por contrato', 'Solo si el punto entrega medicamentos a domicilio', NULL, NULL::jsonb, NULL::jsonb, 7),
    ('P01-31', 'Cambios de propietario, nombre o dirección informados a la ETS en 15 días hábiles', 'Cumple si · todo cambio de propietario, nombre o dirección fue informado a la ETS dentro de los 15 días hábiles siguientes.', 'Res. 1403/2007 Manual T.I Cap.III num. 2.2 (p.31)', 'v2', 'La adquisición, venta y cambio de nombre o dirección del establecimiento farmacéutico se informan a la entidad territorial de salud otorgante de la autorización dentro de los quince (15) días hábiles siguientes.', 'Comunicación a la entidad territorial de salud con fecha de radicación (se desprende)', 'Aplica solo a establecimientos farmacéuticos que han tenido adquisición, venta o cambio de nombre o dirección', 'Solo farmacia alterna', NULL, NULL::jsonb, NULL::jsonb, 8),
    ('P01-35', 'Farmacia-droguería: solo vende al detal los productos permitidos', 'Cumple si · todos los productos ofrecidos al detal pertenecen a las categorías listadas.', 'Res. 1403/2007 Manual T.I Cap.V num. 1 lit. a (p.34)', 'v2', 'La farmacia-droguería solo vende al detal los productos permitidos: medicamentos alopáticos, homeopáticos y fitoterapéuticos y sus preparaciones magistrales; dispositivos médicos; suplementos dietarios; cosméticos, productos de tocador e higiénicos; y productos que no sean contaminantes ni riesgosos.', 'No definida en la norma (observación del portafolio)', 'Aplica solo a farmacias-droguerías', 'Solo si la farmacia alterna es farmacia-droguería', NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P01-40', 'Droguería contratada en el SGSSS: solo procesos generales, inyectología y glicemia', 'Cumple si · el contrato y la operación con el SGSSS se limitan a los procesos listados.', 'Res. 1403/2007 Manual T.I Cap.V num. 2.3 lit. b (p.41)', 'v2', 'La droguería solo presta al SGSSS los procesos generales de selección, adquisición, recepción técnica y almacenamiento, distribución y/o dispensación de medicamentos y DM, además de inyectología y monitoreo de glicemia.', 'No definida en la norma (se desprende: contrato)', 'Aplica solo a droguerías que prestan servicios al SGSSS por contrato', 'Solo si la farmacia alterna es droguería', NULL, NULL::jsonb, NULL::jsonb, 10)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C12', 'Talento humano y dirección técnica', 'Incluye títulos y ReTHUS (Res. 3100) y lo que agrega la Res. 1403: dirección según complejidad, red ambulatoria, quién dispensa, servicio nocturno y capacitación.', 'Cruce Res. 3100 vs Res. 1403 y 2955', NULL, NULL, NULL, ARRAY['ESM', 'FA']::text[], 'Res. 3100/2019 11.1.1 y 11.3.2; Res. 1403/2007 Manual T.I Cap.I-III y V · cruce', 13) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P02-01', 'Director del SF de la IPS con el perfil exigido según la complejidad', 'Cumple si · el director del SF es QF (SF de mediana o alta complejidad), o QF o TRF (SF de baja complejidad). La dirección por auxiliar se califica en el ítem de dirección excepcional.', 'Dec. 780/2016 Art. 2.5.3.10.9 num. 1 (p. 287); concordante 2.7.2.3.2.2.1 lit. a (p. 435); Dec. 780/2016 Art. 2.5.3.10.9 num. 2 (p. 287); Res. 1403/2007 Manual T.I Cap.II num. 3.2 lit. a (p.26); Res. 1403/2007 Manual T.I Cap.II num. 3.2 lit. b (p.26); Res. 3100/2019 Manual 11.3.2, TH num. 1 (p.98); Res. 3100/2019 Manual 11.3.2, TH num. 2 (p.98)', 'v2', 'El servicio farmacéutico de la IPS está dirigido por un Químico Farmacéutico (QF) si es de mediana o alta complejidad, y por un QF o un Tecnólogo en Regencia de Farmacia (TRF) si es de baja complejidad. En prestadores inscritos en REPS, el estándar de talento humano del SF (también en la modalidad de telemedicina) exige cumplir el art. 2.5.3.10.9 del Dec. 780/2016 y la Res. 1403/2007 (Manual T. I Cap. II num. 3.2, 3.2.1, 3.2.2 y Cap. III num. 1.2).', 'No definida en la norma (se desprende: soporte del título del director; en prestadores REPS, soportes de talento humano)', 'Aplica solo a servicios farmacéuticos de IPS (prestadores de servicios de salud)', 'Solo servicio farmacéutico de IPS (ESM)', NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P02-02', 'Dirección del SF de baja complejidad por auxiliar solo en área especial sin QF/TRF', 'Cumple si · el SF de baja complejidad dirigido por un auxiliar está en un área especial donde no hay QF ni TRF disponibles para dirigirlo. No cumple si se designó al auxiliar existiendo TRF o QF disponible en el área.', 'Res. 1403/2007 Manual T.I Cap.II num. 3.2.1 (p.26); Res. 1403/2007 Manual T.I Cap.II num. 3.2.2 (p.26)', 'v2', 'La dirección del SF hospitalario de baja complejidad solo puede ejercerla un auxiliar en servicios farmacéuticos en áreas especiales carentes de facilidades de acceso a los recursos ordinarios de la salud (art. 446 Ley 09/1979): lugares geográficamente distantes o con dificultades de comunicación y todo sitio donde no haya disponible un QF o TRF para dirigir el SF. La IPS no puede designar como director a un auxiliar cuando exista disponible en el área un TRF o un QF.', 'No definida en la norma', 'Aplica solo a SF hospitalario de IPS de baja complejidad dirigido por un auxiliar en servicios farmacéuticos', 'Solo servicio farmacéutico de IPS (ESM)', NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P02-03', 'Dirección del SF ambulatorio en instalaciones separadas a cargo de personal autorizado', 'Cumple si · el SF ambulatorio separado está dirigido por el director del SF hospitalario o por personal con el perfil autorizado para la complejidad de los procesos que realiza.', 'Res. 1403/2007 Manual T.I Cap.III num. 1 inc. 2 (p.28)', 'v2', 'Cuando la IPS presta el SF ambulatorio en instalaciones separadas, la dirección está a cargo del director del SF hospitalario o del recurso humano autorizado por la normatividad, según el grado de complejidad de las actividades y procesos que se realicen.', 'No definida en la norma (se desprende: designación del director)', 'Aplica solo a SF ambulatorio de IPS ubicado en instalaciones separadas', 'Solo servicio farmacéutico de IPS (ESM)', NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P02-04', 'Un QF tiene a cargo máximo 5 SF ambulatorios con dispensación, en zona que pueda cubrir', 'Cumple si · el QF tiene a su cargo cinco (5) o menos SF ambulatorios con dispensación y todos están en una zona geográfica que puede cubrir efectivamente.', 'Dec. 780/2016 Art. 2.5.3.10.9 par. 2 (p. 287); Res. 1403/2007 Manual T.I Cap.III num. 1.2 (p.29)', 'v2', 'Dentro de la red de la IPS, un Químico Farmacéutico puede dirigir (Dec. 780) o coordinar (Res. 1403) un máximo de cinco (5) servicios farmacéuticos ambulatorios donde haya dispensación de medicamentos, ubicados en una zona geográfica de una ciudad, municipio, distrito o provincia que pueda ser efectivamente cubierta por dicho profesional.', 'No definida en la norma (se desprende: asignación del QF a los servicios de la red)', 'Aplica solo a IPS con red de servicios farmacéuticos ambulatorios con dispensación', 'Solo servicio farmacéutico de IPS (ESM)', NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P02-05', 'Cada SF ambulatorio de la red dirigido por TRF (auxiliar solo si no hay TRF)', 'Cumple si · cada SF ambulatorio de la red está dirigido por un TRF, o por un auxiliar únicamente cuando no hay TRF disponible.', 'Res. 1403/2007 Manual T.I Cap.III num. 1.2 (p.29)', 'v2', 'Cada uno de los (hasta cinco) SF ambulatorios de la red coordinados por un QF está dirigido por un Tecnólogo en Regencia de Farmacia; solo cuando este recurso no esté disponible puede dirigirlo un auxiliar en servicios farmacéuticos.', 'No definida en la norma (se desprende: título del responsable de cada punto)', 'Aplica solo a IPS con red de SF ambulatorios coordinados por un QF', 'Solo servicio farmacéutico de IPS (ESM)', NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P02-06', 'Establecimiento autorizado para atención domiciliaria dirigido por QF o TRF', 'Cumple si · el director del establecimiento autorizado para atención domiciliaria es QF o TRF.', 'Res. 1403/2007 Manual T.I Cap.III num. 1.1 inc. 4 (p.29)', 'v2', 'Cuando la atención domiciliaria está a cargo de un establecimiento farmacéutico autorizado específicamente para ese fin por la entidad territorial de salud, su dirección está a cargo de un Químico Farmacéutico o de un Tecnólogo en Regencia de Farmacia.', 'No definida en la norma (se desprende: autorización de la entidad territorial y título del director)', 'Aplica solo a establecimientos farmacéuticos autorizados por la entidad territorial específicamente para atención domiciliaria', 'Solo si el punto entrega medicamentos a domicilio', NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P02-07', 'Dirección técnica de la farmacia-droguería a cargo de QF (TRF en los casos permitidos)', 'Cumple si · el DT es QF; o si es TRF, las preparaciones magistrales que elabora la F-D son solo no estériles de uso tópico y, si la F-D está contratada con una IPS, esta es de primer nivel de atención.', 'Dec. 780/2016 Art. 2.5.3.10.11 num. 1 (p. 287); Res. 1403/2007 Manual T.I Cap.V num. 1.4 lit. a (p.36)', 'v2', 'La dirección técnica de la farmacia-droguería está a cargo de un Químico Farmacéutico. Puede estar a cargo de un Tecnólogo en Regencia de Farmacia cuando las preparaciones magistrales que se elaboren sean no estériles y de uso tópico (polvos, ungüentos, pomadas, cremas, geles, lociones). Si la F-D está contratada para prestar servicios a una IPS (situación del par. 2 del art. 2.5.3.10.11), la Res. 1403 exige QF y admite TRF cuando la IPS contratante es del primer nivel de atención.', 'No definida en la norma (se desprende: título del director técnico)', 'Aplica solo a farmacias-droguerías', 'Solo si la farmacia alterna es farmacia-droguería', NULL, NULL::jsonb, NULL::jsonb, 7),
    ('P02-08', 'Dirección técnica de la droguería a cargo de un perfil autorizado', 'Cumple si · el DT tiene uno de los perfiles del art. 2.5.3.10.11 num. 2, o es médico propietario con la autorización especial; y, si la droguería está contratada con una IPS, el perfil corresponde a la complejidad de la IPS contratante (QF en alta/mediana; QF o TRF en baja; auxiliar solo sin disponibilidad de QF/TRF).', 'Dec. 780/2016 Art. 2.5.3.10.11 num. 2 (p. 288); Dec. 780/2016 Art. 2.7.2.3.5.7 (p. 446); Res. 1403/2007 Manual T.I Cap.V num. 2.3 lit. a (p.41)', 'v2', 'La dirección de la droguería está a cargo de un Químico Farmacéutico, Tecnólogo en Regencia de Farmacia, Director de Droguería, Farmacéutico Licenciado o Expendedor de Drogas (Dec. 780 art. 2.5.3.10.11 num. 2). El médico en ejercicio domiciliado en lugares sin QF, farmacéutico licenciado o expendedor de drogas en número suficiente puede dirigir la droguería de su propiedad con autorización del MSPS o de su autoridad sanitaria delegada (art. 2.7.2.3.5.7). Si la droguería está contratada con una IPS (Res. 1403): QF si la IPS contratante es de alta o mediana complejidad; QF o TRF si es de baja complejidad; auxiliar en servicios farmacéuticos cuando no exista disponibilidad de estos.', 'No definida en el art. 2.5.3.10.11; autorización especial del MSPS o autoridad delegada si el DT es médico propietario (art. 2.7.2.3.5.7); para Expendedor de Drogas, ver ítem de credencial', 'Aplica solo a droguerías', 'Solo si la farmacia alterna es droguería', NULL, NULL::jsonb, NULL::jsonb, 8),
    ('P02-13', 'La dispensación la realiza personal autorizado y, si no es QF ni TRF, con información limitada', 'Cumple si · quien entrega los medicamentos e informa sobre su uso es Químico Farmacéutico, Tecnólogo en Regencia de Farmacia, Director de Droguería, Farmacéutico Licenciado, Expendedor de Drogas o Auxiliar en Servicios Farmacéuticos; y, cuando no es QF ni TRF, la información al paciente se limita a condiciones de almacenamiento, reconstitución de medicamentos de vía oral, medición de la dosis, cuidados en la administración e importancia de la adherencia.', 'Res. 1403/2007 Manual T.II Cap.II num. 5 (p.54); num. 5.1.3 inc. 4 (p.56); Dec. 780/2016 Art. 2.5.3.10.3, def. "Dispensación" (p. 282)', 'v2', 'La dispensación es la entrega de uno o más medicamentos a un paciente y la información sobre su uso adecuado, realizada por un Químico Farmacéutico, Tecnólogo en Regencia de Farmacia, Director de Droguería, Farmacéutico Licenciado, Expendedor de Drogas y Auxiliar en Servicios Farmacéuticos. Cuando el dispensador no tiene la condición de QF o TRF, suministra información solo sobre los cinco aspectos señalados.', 'Soportes de formación del personal que dispensa (se desprende); observación del acto de dispensación.', 'Aplica solo a servicios y establecimientos que dispensan (SF de IPS, farmacias-droguerías y droguerías)', NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P02-14', 'Personal idóneo, con las calidades exigidas y en número suficiente para los procesos', 'Cumple si · cada cargo está ocupado por personal con el perfil exigido por la norma y el número de personas permite cumplir los procesos que se realizan. La norma no fija razón de personal.', 'Dec. 780/2016 Art. 2.5.3.10.8 num. 3 (p. 286); Dec. 780/2016 Art. 2.5.3.10.9 par. 1 (p. 287); Res. 1403/2007 Manual T.I Cap.I num. 3 lit. c (p.22); T.I Cap.III num. 2 inc. 2 (p.30), sustituido por Res. 2955/2007 Art. 1 (p.1-2); Res. 1403/2007 Manual T.I Cap.II num. 3.1 (p.25); Res. 3100/2019 Manual 11.1.1 num. 3 (p.59-60)', 'v2', 'El SF o establecimiento dispone de recurso humano idóneo y suficiente para las actividades y procesos que realiza; en el SF de la IPS, el personal tiene las calidades señaladas en la normatividad vigente para cada cargo y está en número que garantice el cumplimiento de los procesos.', 'No definida en la norma (se desprende: hojas de vida y soportes de formación del personal)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 10),
    ('P02-15', 'Soportes de formación del personal según el cargo (títulos, certificados, convalidación)', 'Cumple si · todo el personal verificado presenta el soporte de formación exigido para su cargo, incluida la convalidación de los títulos extranjeros.', 'Dec. 780/2016 Art. 2.7.2.3.2.2.8 (p. 438); Dec. 780/2016 Art. 2.7.2.3.4.1 lit. e y 2.7.2.3.4.3 (p. 444); Res. 3100/2019 Manual 11.1.1 num. 1 (p.59)', 'v2', 'Cada persona cuenta con el soporte de formación de su cargo: el QF, título de Químico Farmacéutico obtenido o validado según el art. 2.7.2.3.2.2.8 e inscripción en el registro del Colegio Nacional de Químicos Farmacéuticos; el auxiliar en servicios farmacéuticos, Certificado de Aptitud Ocupacional por Competencias (''Técnico Laboral en…''), cuyo titular debe solicitar la inscripción en el Registro Único Nacional; en prestadores inscritos en REPS, el talento humano en salud y otros profesionales relacionados con la atención tienen títulos de educación superior o certificados de aptitud ocupacional y, si se obtuvieron en el extranjero, la resolución de convalidación del Ministerio de Educación Nacional.', 'Título de QF (o validación) e inscripción en el registro del Colegio Nacional de QF; Certificado de Aptitud Ocupacional por Competencias del auxiliar; títulos o certificados de aptitud ocupacional; copia de la resolución de convalidación (títulos extranjeros)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 11),
    ('P02-16', 'Talento humano en salud inscrito en RETHUS o con autorización del ejercicio', 'Cumple si · todo el talento humano en salud verificado acredita inscripción en RETHUS o resolución de autorización del ejercicio.', 'Dec. 780/2016 Art. 2.7.2.1.2.1 y 2.7.2.1.2.2 (p. 408); 2.7.2.1.2.6 (p. 411); Res. 3100/2019 Manual 11.1.1 num. 2 (p.59); Ley 1751/2015 Art. 10 lit. h) (p. 2)', 'v2', 'Los profesionales, tecnólogos, técnicos y auxiliares del área de la salud que laboran en el SF o establecimiento (QF, TRF, auxiliares) están inscritos en el Registro Único Nacional del Talento Humano en Salud (RETHUS) o cuentan con la resolución de autorización del ejercicio expedida por la autoridad competente. El usuario tiene derecho a ser atendido por trabajadores de la salud debidamente capacitados y autorizados para ejercer.', 'Inscripción en RETHUS / Tarjeta de Identificación Única; copia de la resolución de autorización del ejercicio', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 12),
    ('P02-17', 'Capacitación y actualización continua del personal del SF y del dispensador', 'Cumple si · existe un mecanismo o programa de capacitación y actualización del personal del SF con evidencia de ejecución, que incluya al personal que dispensa.', 'Res. 1403/2007 Manual T.I Cap.I num. 3 inc. final (p.22); Dec. 780/2016 Art. 2.5.3.10.18 num. 8 (p. 293)', 'v2', 'Las políticas y programas de mejoramiento continuo del SF incluyen mecanismos que promueven y fomentan la actualización, capacitación, adiestramiento, motivación y comunicación efectiva del recurso humano; el dispensador recibe la capacitación ofrecida por entidades oficiales u otros actores del sector salud y/o se capacita continuamente en los conocimientos teóricos y destrezas necesarias para su cargo u oficio.', 'No definida en la norma (se desprende: programa y registros de capacitación)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 13),
    ('P14-10', 'Servicio nocturno con presencia del director o de personal entrenado designado por él', 'Cumple si · durante el servicio nocturno está presente el director o una persona entrenada designada por él.', 'Res. 1403/2007 Manual T.I Cap.II num. 5 (p.28); Res. 1403/2007 Manual T.I Cap.V num. 1.7 (p.39); num. 2.2 lit. d (p.40)', 'v2', 'Cuando se presta servicio nocturno (en el SF hospitalario, cuando las necesidades lo exijan), está presente de forma permanente el director o una persona o trabajador debidamente capacitado y entrenado, encargado por el director y bajo su responsabilidad.', 'No definida en la norma (se desprende: turnos y designación del encargado)', 'Aplica solo si el SF hospitalario, la farmacia-droguería o la droguería presta servicio nocturno', 'Solo si hay servicio nocturno', NULL, NULL::jsonb, NULL::jsonb, 14),
    ('P02-25', 'Hospital universitario propicia formación y rotación de estudiantes en el SF', 'Cumple si · el hospital universitario ofrece formación y rotación en el SF a estudiantes de esos programas.', 'Res. 1403/2007 Manual T.I Cap.I num. 3 inc. final (p.22)', 'v2', 'Los hospitales universitarios propician la formación y la disponibilidad de rotación de los estudiantes de los programas que forman el recurso humano del servicio farmacéutico.', 'No definida en la norma', 'Aplica solo a hospitales universitarios', 'Solo hospital universitario', NULL, NULL::jsonb, NULL::jsonb, 15),
    ('P02-29', 'Áreas especiales sin personal del SF: suministro por médico o auxiliar en salud', 'Cumple si · en esas áreas, el suministro lo realiza el médico del equipo de salud o un auxiliar en salud.', 'Res. 1403/2007 Manual T.I Cap.III num. 1.1 inc. 5 (p.29)', 'v2', 'En atención domiciliaria o sitios predeterminados en áreas especiales donde no es posible contar con personal del servicio farmacéutico, el suministro de medicamentos está a cargo del médico encargado del equipo de salud o de uno de los auxiliares en salud.', 'No definida en la norma', 'Aplica solo a atención domiciliaria o sitios predeterminados en áreas especiales sin personal del servicio farmacéutico', 'Solo si el punto entrega medicamentos a domicilio', NULL, NULL::jsonb, NULL::jsonb, 16)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C13', 'Dispensación', 'La Res. 3100 solo exige que la dispensación esté documentada (11.1.4 num. 4.10). La Res. 1403 fija el procedimiento, la información al paciente, el registro y las prohibiciones.', 'Cruce Res. 3100 vs Res. 1403 y 2955', NULL, NULL, NULL, ARRAY['ESM', 'FA']::text[], 'Res. 1403/2007 Manual T.II Cap.II num. 5 (p.54-57) · cruce', 14) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P08-01', 'Características de la prescripción médica que se dispensa', 'Cumple si · las prescripciones revisadas reúnen todas las características listadas.', 'Dec. 780/2016 Art. 2.5.3.10.15 inc. 1 y nums. 1-7 (pp. 290-291); Res. 1403/2007 Manual T.II Cap.II num. 5.1.1 lits. a-e (p. 55)', 'v2', 'Toda prescripción que se dispensa debe: hacerse por escrito, en idioma español (copia mecanográfica, medio electromagnético y/o computarizado) y con la Denominación Común Internacional (nombre genérico); provenir de personal de salud debidamente autorizado según su competencia; estar en letra clara y legible, con las indicaciones necesarias para su administración; no contener enmendaduras, tachaduras, siglas, claves, signos secretos, abreviaturas o símbolos químicos (salvo abreviaturas aprobadas por el Comité de Farmacia y Terapéutica de la institución); permitir la confrontación entre lo prescrito y lo dispensado (ambulatorio) o administrado (hospitalario) y la correlación de los medicamentos con el diagnóstico; y expresar la dosis en el sistema métrico decimal (en casos especiales, en unidades internacionales).', 'Prescripciones (fórmulas médicas) recibidas y dispensadas; listado de abreviaturas aprobadas por el Comité de Farmacia y Terapéutica, cuando aplique', 'Aplica solo a servicios y establecimientos farmacéuticos que dispensan medicamentos con prescripción', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P09-02', 'Verificación de la prescripción por el dispensador antes de entregar', 'Cumple si · las fórmulas dispensadas revisadas provienen de prescriptor autorizado y cumplen las características y el contenido verificados en los ítems de P08.', 'Dec. 780/2016 Art. 2.5.3.10.18 num. 1 (p. 292); Res. 1403/2007 Manual T.II Cap.II num. 5.1.1 inc. 1 (p. 54); Res. 1604/2013 Art. 7 num. 3 inc. 2 (p. 4)', 'v2', 'El dispensador debe verificar que la prescripción esté elaborada por personal de salud competente y autorizado y que cumpla la plenitud de las características y del contenido de la prescripción (Dec. 780/2016 arts. 2.5.3.10.15 y 2.5.3.10.16). En la entrega de pendientes por el mecanismo excepcional debe garantizarse igualmente que la fórmula médica cumple las exigencias legales vigentes.', 'No definida en la norma (se desprende: fórmulas dispensadas)', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P09-03', 'No dispensar ante errores o dudas en la fórmula sin aclarar con el prescriptor', 'Cumple si · no se dispensan fórmulas con posibles errores, dudas, correcciones o adiciones sin aclaración previa con el prescriptor.', 'Dec. 780/2016 Art. 2.5.3.10.18 num. 4 (p. 292); Res. 1403/2007 Manual T.II Cap.II num. 5.1.1 inc. 2 (p. 54); Res. 1604/2013 Art. 7 num. 3 inc. 2 (p. 4)', 'v2', 'Cuando la fórmula no cumpla las exigencias legales o presente posibles errores, dudas, correcciones o adiciones, el dispensador debe solicitar al prescriptor la aclaración, corrección o adición y no debe dispensar ni entregar hasta aclarar la duda con el prescriptor.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P09-04', 'Exigencia de fórmula para medicamentos con leyenda ''Venta Bajo Fórmula Médica''', 'Cumple si · no se dispensan medicamentos con esa leyenda sin prescripción.', 'Dec. 780/2016 Art. 2.5.3.10.18 num. 3 (p. 292); Res. 1403/2007 Manual T.II Cap.II num. 5.1.1 lit. g (p. 55)', 'v2', 'Debe exigirse la prescripción para todo medicamento en cuya etiqueta aparezca la leyenda ''Venta Bajo Fórmula Médica''.', 'Prescripción médica que soporta la dispensación', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P09-05', 'Lo dispensado corresponde a lo prescrito, sin cambios ni adulteración de la fórmula', 'Cumple si · en las dispensaciones revisadas lo entregado coincide con lo prescrito en todos los elementos listados y las fórmulas no presentan adulteraciones ni modificaciones.', 'Dec. 780/2016 Art. 2.5.3.10.18 num. 5 (p. 293); Dec. 780/2016 Art. 2.5.3.10.19 nums. 1-2 (p. 293); Res. 1403/2007 Manual T.II Cap.II num. 5.3 lits. a-b (p. 56); Res. 1885/2018 Art. 7 par. (p. 8)', 'v2', 'El dispensador debe verificar y controlar que los medicamentos dispensados correspondan a los prescritos; no puede adulterar o modificar en cualquier forma la prescripción ni cambiar el principio activo, la concentración, la forma farmacéutica, la vía de administración, la frecuencia, la cantidad o la dosis prescrita. En tecnologías no financiadas con UPC, la IPS no puede modificar la decisión ni los datos consignados por el profesional en la prescripción.', 'No definida en la norma (se desprende: cotejo de las fórmulas con lo dispensado)', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P09-06', 'No se dispensan medicamentos alterados o fraudulentos', 'Cumple si · no se encuentran medicamentos alterados o fraudulentos dispensados o disponibles para dispensación.', 'Dec. 780/2016 Art. 2.5.3.10.19 num. 3 (p. 293); Res. 1403/2007 Manual T.II Cap.II num. 5.3 lit. c (p. 56)', 'v2', 'El dispensador no puede dispensar medicamentos alterados o fraudulentos.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P09-07', 'El dispensador guarda la reserva propia de su función', 'Cumple si · no se evidencia violación de la reserva a que está obligado el dispensador.', 'Dec. 780/2016 Art. 2.5.3.10.19 num. 4 (p. 293); Res. 1403/2007 Manual T.II Cap.II num. 5.3 lit. d (p. 56)', 'v2', 'El dispensador no puede violar la reserva a que está obligado por razón de la función que desempeña.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 7),
    ('P09-08', 'El dispensador no recomienda a los usuarios el uso de medicamentos', 'Cumple si · no se observa al dispensador recomendando a los usuarios la utilización de medicamentos.', 'Dec. 780/2016 Art. 2.5.3.10.19 num. 5 (p. 293); Res. 1403/2007 Manual T.II Cap.II num. 5.3 lit. e (p. 56)', 'v2', 'El dispensador no puede recomendar a los usuarios la utilización de medicamentos.', 'No definida en la norma (observación)', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 8),
    ('P09-11', 'Envío por correo de medicamentos bajo fórmula solo con prescripción previa', 'Cumple si · cada envío por correo de medicamentos de venta bajo prescripción tiene la prescripción presentada previamente y condiciones de transporte garantizadas.', 'Res. 1403/2007 Manual T.II Cap.II num. 5.3 lit. g (pp. 56-57)', 'v2', 'El dispensador no puede enviar por correo medicamentos de venta bajo prescripción médica, a menos que antes del envío se presente la prescripción médica y se garanticen las condiciones y requisitos para su transporte.', 'No definida en la norma (se desprende: prescripción presentada antes del envío)', 'Aplica solo si el establecimiento envía por correo medicamentos de venta bajo prescripción médica', NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P09-12', 'Empaque adecuado de lo dispensado para su transporte por el paciente', 'Cumple si · lo dispensado se entrega en bolsa resistente, caja u otro medio que permita su transporte y la conservación de su calidad.', 'Res. 1403/2007 Art. 12 inc. 2 (p. 8); Manual T.II Cap.II num. 5.1.2 (p. 55)', 'v2', 'En la dispensación deben empacarse adecuadamente los medicamentos y dispositivos médicos que van a ser transportados por los pacientes, en bolsas resistentes, cajas o cualquier otro medio que permita transportarlos adecuadamente y asegurar la conservación de su calidad.', 'No definida en la norma (observación directa)', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 10),
    ('P09-13', 'Información al paciente sobre uso adecuado en el acto de dispensación', 'Cumple si · en las dispensaciones observadas el dispensador brinda la información correspondiente a su perfil.', 'Dec. 780/2016 Art. 2.5.3.10.18 num. 6 (p. 293); Res. 1403/2007 Manual T.II Cap.II num. 5.1.3 incs. 1-2 y 4 (pp. 55-56); Dec. 780/2016 Art. 2.5.3.10.18 num. 7 (p. 293)', 'v2', 'En el acto de entrega física, el dispensador debe informar al usuario sobre los aspectos indispensables para el efecto terapéutico y el uso adecuado: condiciones de almacenamiento, cómo reconstituir, cómo medir la dosis, cuidados en la administración, interacciones con alimentos y otros medicamentos, advertencias sobre efectos o eventos adversos, contraindicaciones, PRM y PRUM, e importancia de la adherencia a la terapia. Si el dispensador no es Químico Farmacéutico ni Tecnólogo en Regencia de Farmacia, debe informar al menos: condiciones de almacenamiento, reconstitución de medicamentos de vía oral, medición de la dosis, cuidados en la administración e importancia de la adherencia (en droguerías con dirección técnica no QF/TRF, lo señalado en el art. 2.5.3.10.3 del Dec. 780/2016).', 'No definida en la norma (observación de la dispensación)', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 11),
    ('P09-14', 'Entrega de pictogramas y ayudas exigidos por la normatividad', 'Cumple si · se entregan los pictogramas y ayudas que la normatividad exige para los medicamentos dispensados, con la información para su comprensión.', 'Res. 1403/2007 Manual T.II Cap.II num. 5.1.3 inc. 3 (p. 56)', 'v2', 'En el acto de entrega, el dispensador debe entregar los pictogramas y demás ayudas que la normatividad haya señalado para los medicamentos que se dispensan, con la información para su uso y la comprensión de su significado.', 'Pictogramas y ayudas entregados al usuario', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 12),
    ('P09-15', 'Registro de salida de lo dispensado (cantidad y fecha)', 'Cumple si · existe registro de las dispensaciones con, al menos, la cantidad y la fecha de lo dispensado.', 'Res. 1403/2007 Manual T.II Cap.II num. 5.1.4 (p. 56)', 'v2', 'El servicio o establecimiento farmacéutico debe registrar, en los medios existentes para tal fin (preferiblemente computarizados), la cantidad, fecha, etc., de los medicamentos y dispositivos médicos dispensados.', 'Registro de salida de lo dispensado', 'Aplica solo a servicios farmacéuticos y establecimientos que dispensan (farmacia-droguería, droguería); no a agencias de especialidades farmacéuticas ni depósitos de drogas', NULL, NULL, NULL::jsonb, NULL::jsonb, 13)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C14', 'Distribución intrahospitalaria y dosis unitaria', 'Vacío 3: la dosis unitaria es obligatoria en IPS de mediana y alta complejidad (Res. 1403 art. 13) y la Res. 3100 no la exige.', 'Cruce Res. 3100 vs Res. 1403 y 2955', NULL, NULL, NULL, ARRAY['ESM']::text[], 'Res. 1403/2007 Art. 13-16; Manual T.II Cap.II num. 4-4.3 (p.51-54) · cruce', 15) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P07-04', 'Sistema(s) de distribución intrahospitalaria determinado(s) por el SF', 'Cumple si · el SF tiene definido(s) y en operación el/los sistema(s) de distribución intrahospitalaria y estos cuentan con envases unitarios, cantidad disponible y perfil farmacoterapéutico.', 'Dec. 780/2016 Art. 2.5.3.10.17 inc. 2 (p. 292); Res. 1403/2007 Manual T.II Cap.II num. 4.1 (p.51)', 'v2', 'El SF determina el sistema o sistemas de distribución intrahospitalaria a implementar en la IPS (reserva por piso/stock, prescripción individual para 24 horas, dosis unitaria o mixto) para garantizar oportunidad, seguridad, eficiencia y calidad; son elementos esenciales del sistema los envases unitarios, la cantidad disponible y el perfil farmacoterapéutico.', 'No definida en la norma (se desprende: documento de definición del sistema)', 'Aplica solo a servicios farmacéuticos de IPS con distribución intrahospitalaria', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P07-05', 'Registro de medicamentos administrados y devolución sustentada de no administrados', 'Cumple si · para los medicamentos distribuidos a los servicios, existe registro de administración y, para los no administrados, devolución sustentada.', 'Res. 1403/2007 Manual T.II Cap.II num. 4.1 (p.51)', 'v2', 'En la distribución intrahospitalaria se registran los medicamentos administrados y se sustenta debidamente la devolución de los no administrados.', 'No definida en la norma (se desprende: registro de administración y soportes de devolución)', 'Aplica solo a IPS con distribución intrahospitalaria', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P07-17', 'SDMDU implementado en IPS de mediana/alta complejidad, con alcance definido por SF y CFT', 'Cumple si · el SDMDU opera en los servicios definidos y existe la definición documentada de servicios, medicamentos y pacientes y de los medicamentos a reempacar/reenvasar.', 'Res. 1403/2007 Art. 13 inc. 1 (p. 8); Art. 27 (p. 15); Manual T. II Cap. II num. 4.3 (p. 51); Res. 1403/2007 Art. 13 inc. 2 (p. 8); Art. 16 (p. 9); Res. 1403/2007 Art. 16 (p. 9); Manual T. II Cap. II num. 4.3.6 (p. 54); Dec. 780/2016 Art. 2.5.3.10.17 inc. 3 (p. 292); Res. 444/2008 Anexo num. 16.1.1 (p. 18)', 'v2', 'Las IPS de mediana y alta complejidad (segundo y tercer nivel) tienen implementado el Sistema de Distribución de Medicamentos en Dosis Unitaria; el SF y el CFT determinaron los servicios, medicamentos y pacientes a los que se aplica y está establecido a qué medicamentos se practica reempaque y reenvase; la IPS de baja complejidad que adopte el SDMDU cumple plenamente sus disposiciones.', 'Acta o decisión del CFT con servicios, medicamentos y pacientes (se desprende); listado de medicamentos a reempacar/reenvasar (se desprende).', 'Aplica solo a SF de IPS de mediana y alta complejidad (obligatorio) y a IPS de baja complejidad que hayan adoptado el SDMDU.', 'Solo IPS de mediana o alta complejidad, o de baja que adoptó la dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 3),
    ('P16-04', 'Dirección técnica del Sistema de Distribución de Medicamentos en Dosis Unitaria a cargo de QF', 'Cumple si · el director técnico de los procesos del SDMDU (reempaque, reenvase y distribución en dosis unitaria) es un Químico Farmacéutico con título y registro profesional, y el personal tiene las competencias para esos procesos.', 'Res. 1403/2007 Manual T.II Cap.II num. 4.3.1 lit. e (p.52); Res. 444/2008 Anexo num. 4.2.2 (p. 7)', 'v2', 'El servicio farmacéutico dispone del recurso humano con los conocimientos, destrezas y competencias necesarios para las actividades del SDMDU. El director técnico del o los procesos es un Químico Farmacéutico.', 'Título y registro profesional del director técnico del SDMDU.', 'Aplica solo a IPS que operan el Sistema de Distribución de Medicamentos en Dosis Unitaria.', 'Solo IPS de mediana o alta complejidad, o de baja que adoptó la dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 4),
    ('P16-23', 'Protocolo y procedimientos del SDMDU: orden médica, perfil, PRM, dispensación y devolución', 'Cumple si · el protocolo contiene los seis aspectos, existen los procedimientos listados y las dispensaciones revisadas tienen prescripción médica y perfil farmacoterapéutico por paciente.', 'Res. 1403/2007 Art. 14 (p. 8); Res. 1403/2007 Manual T. II Cap. II num. 4.3.1 lit. d (p. 52); Res. 444/2008 Anexo num. 16.2.1–16.2.7 y 16.2.9–16.2.11 (p. 19)', 'v2', 'Existe protocolo del SDMDU que contiene: recepción de la orden médica, elaboración del perfil farmacoterapéutico, detección/identificación/resolución de PRM, preparación, transporte de la medicación y devoluciones; se cuenta con los protocolos de los arts. 10 y 11 en lo pertinente; están determinados los servicios y pacientes del SDMDU y hay procedimientos de dispensación y distribución en dosis unitaria que mantienen las especificaciones de calidad y almacenamiento; se dispensa contra prescripción médica, con procedimiento para verificar que la orden cumpla el contenido normativo; hay procedimientos para hacer cumplir las obligaciones del dispensador y para que conozca las prohibiciones; se elabora perfil farmacoterapéutico por paciente; hay responsable de la supervisión y control de los procedimientos y procedimientos de devolución de medicamentos por la IPS y por los servicios de enfermería/SF.', 'Protocolo del SDMDU; procedimientos escritos; prescripciones; perfiles farmacoterapéuticos.', 'Aplica solo a servicios/establecimientos farmacéuticos que realizan reempaque o reenvase y dispensación/distribución en el Sistema de Distribución de Medicamentos en Dosis Unitaria (SDMDU).', 'Solo IPS de mediana o alta complejidad, o de baja que adoptó la dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 5),
    ('P16-24', 'Protocolo de reempaque/reenvase con actividades previas, propias y posteriores', 'Cumple si · el protocolo incluye las tres fases con los aspectos listados y los registros de control documentan el seguimiento y las desviaciones.', 'Res. 1403/2007 Art. 15 (p. 8–9); Res. 444/2008 Anexo num. 16.1.3, 16.1.3.1 y 16.1.3.2 (p. 18)', 'v2', 'El protocolo de reempaque y reenvase de medicamentos (pacientes hospitalizados y/o ambulatorios en casos especiales) contiene actividades previas (comprensión del procedimiento, medicamentos a reempacar, especificaciones y condiciones de almacenamiento, condiciones del área y del material), actividades propias (pasos sucesivos con controles y resolución de problemas) y actividades posteriores (retiro de materiales, limpieza, revisión de equipos y almacenamiento); existen procedimientos escritos que aseguran el cumplimiento de las normas técnicas y científicas, se registran los controles y el seguimiento y se anotan y explican las desviaciones en el registro de control.', 'Protocolo y procedimientos escritos de reempaque/reenvase; registros de control con desviaciones.', 'Aplica solo a servicios/establecimientos farmacéuticos que realizan reempaque o reenvase y dispensación/distribución en el Sistema de Distribución de Medicamentos en Dosis Unitaria (SDMDU).', 'Solo IPS de mediana o alta complejidad, o de baja que adoptó la dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 6),
    ('P16-25', 'Personal del SDMDU competente y capacitado en reempaque/reenvase, con registros', 'Cumple si · el personal del SDMDU tiene soportes de competencia y registros de capacitación en los procedimientos de reempaque/reenvase.', 'Res. 1403/2007 Manual T. II Cap. II num. 4.3.1 lit. e (p. 52); Res. 444/2008 Anexo num. 16.1.3.3 y 16.1.3.4 (p. 19)', 'v2', 'El SF dispone de recurso humano con los conocimientos, destrezas y competencias necesarios para las actividades del SDMDU; el personal se capacita en el conocimiento y uso de los procedimientos de reempaque/reenvase y la capacitación se registra.', 'Registros de capacitación; soportes de formación/competencia (se desprenden).', 'Aplica solo a servicios/establecimientos farmacéuticos que realizan reempaque o reenvase y dispensación/distribución en el Sistema de Distribución de Medicamentos en Dosis Unitaria (SDMDU).', 'Solo IPS de mediana o alta complejidad, o de baja que adoptó la dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 7),
    ('P16-26', 'Control del reempaque: inspección previa, supervisión del QF, verificación y trazabilidad', 'Cumple si · los registros evidencian inspección previa, supervisión del QF y verificación frente a la prescripción, y las unidades observadas permiten trazar identificación, dosis, concentración, lote y vencimiento, con empaque que protege el contenido.', 'Res. 444/2008 Anexo num. 16.1.4–16.1.7 (p. 19); Res. 1403/2007 Manual T. II Cap. II num. 4.3.7 lit. a–b (p. 54)', 'v2', 'Se inspecciona la calidad del medicamento a reempacar/reenvasar; los procedimientos son controlados y supervisados por un Químico Farmacéutico y se registra el resultado; el SF revisa que el medicamento reempacado/reenvasado cumpla la prescripción (identidad, calidad de los materiales, corrección de la etiqueta, nombre, potencia, dosificación, lote, vencimiento y fecha de reempaque); el manejo de las dosis unitarias permite la trazabilidad (identificación, dosis, concentración, número de lote y fecha de vencimiento); se implementan mecanismos que protegen el contenido del deterioro ambiental y de la manipulación y permiten su uso rápido, fácil y seguro.', 'Registros de inspección, supervisión, control y verificación (se desprenden).', 'Aplica solo a servicios/establecimientos farmacéuticos que realizan reempaque o reenvase y dispensación/distribución en el Sistema de Distribución de Medicamentos en Dosis Unitaria (SDMDU).', 'Solo IPS de mediana o alta complejidad, o de baja que adoptó la dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 8),
    ('P16-27', 'Etiquetado de medicamentos reempacados/reenvasados con contenido mínimo y revisión final', 'Cumple si · las unidades observadas tienen etiqueta legible y durable con todos los datos listados (o separata en envases pequeños) y hay evidencia de revisión final.', 'Res. 1403/2007 Manual T. II Cap. II num. 4.3.2, lit. a–f e inc. final (p. 52–53); Res. 444/2008 Anexo num. 16.1.8 y 16.1.9 (p. 19)', 'v2', 'Las etiquetas de los medicamentos reempacados/reenvasados aseguran la máxima legibilidad, contraste y durabilidad y contienen: nombre en DCI, forma farmacéutica y vía de administración, concentración final, indicaciones especiales (si es posible), fecha de vencimiento y número de lote; en envases o empaques pequeños la información se incluye en una separata; las etiquetas cumplen además el lit. f del num. 5.1.1 del Manual y se realiza revisión final de etiquetas y rótulos.', 'Etiquetas y separatas; registro de revisión final.', 'Aplica solo a servicios/establecimientos farmacéuticos que realizan reempaque o reenvase y dispensación/distribución en el Sistema de Distribución de Medicamentos en Dosis Unitaria (SDMDU).', 'Solo IPS de mediana o alta complejidad, o de baja que adoptó la dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 9),
    ('P16-28', 'Traslado de dosis unitarias a enfermería y revisión de DU reempacada externamente', 'Cumple si · el traslado observado o documentado cumple todos los elementos y, cuando el reempaque es externo, existe el procedimiento escrito y evidencia de la revisión del SF.', 'Res. 1403/2007 Manual T. II Cap. II num. 4.3.4 y 4.3.5 lit. a–d (p. 53); Res. 444/2008 Anexo num. 16.2.8 (p. 19)', 'v2', 'Los medicamentos en dosis unitaria se guardan en bolsas resistentes, cajas u otro medio que asegure su conservación, se trasladan directamente del SF al servicio de enfermería sin abrir los contenedores y se entregan al jefe de enfermería de turno o su delegado; los medicamentos reempacados/reenvasados en DU por establecimientos externos se entregan al SF institucional para su revisión antes de enviarlos a enfermería, con procedimiento escrito de traslado conforme a los num. 4.3.4 y 4.3.5 del Manual.', 'Procedimiento escrito de traslado; constancia de entrega a enfermería y de revisión del SF (se desprenden).', 'Aplica solo a servicios/establecimientos farmacéuticos que realizan reempaque o reenvase y dispensación/distribución en el Sistema de Distribución de Medicamentos en Dosis Unitaria (SDMDU). Los num. 4.3.4 y 16.2.8 solo si el reempaque/reenvase lo hace un establecimiento externo.', 'Solo IPS de mediana o alta complejidad, o de baja que adoptó la dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 10),
    ('I07-11', 'Áreas de reempaque/reenvase y de dosis unitaria, con dotación y bibliografía', 'Cumple si · existen ambas áreas con las condiciones listadas y la dotación y la bibliografía definidas por el CFT.', 'Res. 1403/2007 Manual T. I Cap. II num. 1.2.2 lit. b–c (p. 25); T. II Cap. II num. 4.3.1 lit. a–c (p. 52); Res. 444/2008 Anexo num. 16.1.2 y 16.1.2.1 (p. 18)', 'v2', 'Existe un área especial, independiente y específica, claramente diferenciada, para el reempaque/reenvase y la preparación de cajetillas, que evita riesgos de contaminación cruzada y confusión y garantiza las buenas prácticas; un área para la segregación, disposición en cajetines y distribución de medicamentos en dosis unitaria; la dotación, equipos, instrumentos y materiales necesarios para el SDMDU; y la bibliografía técnica, científica y de seguridad industrial necesaria, determinada por el CFT.', 'No definida en la norma (constatación física); bibliografía disponible (se desprende).', 'Aplica solo a servicios/establecimientos farmacéuticos que realizan reempaque o reenvase y dispensación/distribución en el Sistema de Distribución de Medicamentos en Dosis Unitaria (SDMDU). (Res. 1403 T. I 1.2.2: SF hospitalario de mediana/alta complejidad).', 'Solo IPS de mediana o alta complejidad, o de baja que adoptó la dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 11),
    ('I07-12', 'Dosis unitarias en enfermería identificadas por paciente y cama; voluminosos segregados', 'Cumple si · los cajetines o sitios están identificados por paciente y cama y los medicamentos voluminosos están en sitio alterno adecuado, segregados e identificados.', 'Res. 1403/2007 Manual T. II Cap. II num. 4.3.5 lit. e–f (p. 53)', 'v2', 'En el servicio de enfermería los medicamentos en dosis unitaria están adecuadamente almacenados e identificados con el paciente y su cama; los que no caben en el sitio del paciente se ubican en otro sitio con condiciones ambientales que garanticen su almacenamiento, segregados y plenamente identificados.', 'No definida en la norma (constatación física)', 'Aplica solo a servicios/establecimientos farmacéuticos que realizan reempaque o reenvase y dispensación/distribución en el Sistema de Distribución de Medicamentos en Dosis Unitaria (SDMDU).', 'Solo IPS de mediana o alta complejidad, o de baja que adoptó la dosis unitaria', '3 · Dosis unitaria', NULL::jsonb, NULL::jsonb, 12),
    ('P07-18', 'IPS: medicamentos y DM de la consulta médica suministrados por el servicio farmacéutico', 'Cumple si · los medicamentos y DM usados en los consultorios provienen del servicio farmacéutico.', 'Res. 1403/2007 Manual T.II Cap.II num. 4 inc. 2 (p.51)', 'v2', 'En la consulta médica donde se requieran medicamentos y dispositivos médicos, estos son suministrados por el servicio farmacéutico; las muestras médicas que se encuentren en consultorio deben haber sido debidamente recibidas y almacenadas.', 'No definida en la norma', 'Aplica solo a IPS con consultorios donde se usan medicamentos o dispositivos médicos', NULL, NULL, NULL::jsonb, NULL::jsonb, 13),
    ('P07-19', 'IPS: medicamentos aportados por terceros para hospitalizados entregados al SF', 'Cumple si · los medicamentos aportados por terceros para pacientes hospitalizados son recibidos y verificados por el SF antes de su distribución (salvo urgencias, a cargo de enfermería).', 'Res. 1403/2007 Manual T.II Cap.II num. 4.3.3 (p.53)', 'v2', 'Los medicamentos suministrados por personas ajenas a la IPS para un paciente hospitalizado se entregan al servicio farmacéutico para su verificación, almacenamiento y distribución, excepto en casos de urgencia, cuya responsabilidad corre a cargo del servicio de enfermería.', 'No definida en la norma (se desprende: registro de recepción en el servicio farmacéutico)', 'Aplica solo a IPS con hospitalización', NULL, NULL, NULL::jsonb, NULL::jsonb, 14)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C15', 'Transporte y distribución física', 'La Res. 3100 solo exige que el transporte esté documentado (11.1.4 num. 4.3).', 'Cruce Res. 3100 vs Res. 1403 y 2955', NULL, NULL, NULL, ARRAY['ESM', 'FA', 'NC']::text[], 'Res. 1403/2007 Manual T.II Cap.II num. 4; Cap.III num. 7 (p.51, 71-74) · cruce', 16) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P07-02', 'Solo se distribuyen medicamentos y DM que cumplen condiciones legales y técnicas', 'Cumple si · los medicamentos y DM distribuidos cumplen las condiciones legales y técnicas de producción y comercialización (p. ej., registro sanitario vigente) y no presentan alteración.', 'Res. 1403/2007 Manual T.II Cap.II num. 4 inc. 1 (p.51)', 'v2', 'Los establecimientos farmacéuticos, SF de IPS y demás autorizados solo distribuyen medicamentos y DM que cumplan las condiciones legales y técnicas para su producción y comercialización.', 'No definida en la norma (se desprende: registro sanitario vigente de los productos)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P07-03', 'Distribución y entrega solo a establecimientos o personas autorizadas', 'Cumple si · los destinatarios de las entregas son establecimientos o personas autorizadas y legalmente constituidos, con verificación de su autorización.', 'Res. 1403/2007 Manual T.II Cap.II num. 4 inc. 1 (p.51); T.II Cap.III num. 7.5 lit. a–b (p.73)', 'v2', 'La distribución y entrega se hace solo a establecimientos o personas autorizadas para distribuir y/o dispensar medicamentos al público, con seguridad de que se trata de un establecimiento legalmente constituido.', 'No definida en la norma (se desprende: soporte de verificación de la autorización del destinatario)', 'Aplica solo a quienes distribuyan o entreguen medicamentos a terceros (DD, AEF, SF o establecimientos que distribuyan)', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P07-07', 'Transporte que preserva integridad, condiciones de almacenaje e identificación', 'Cumple si · los medios y prácticas de transporte (propio o contratado) mantienen la integridad, las condiciones de almacenaje especificadas y la identificación de los productos y los protegen contra hurto, contaminación y confusión.', 'Res. 1403/2007 Manual T.II Cap.III num. 7.4 inc. 1 (p.73); Dec. 780/2016 Art. 2.5.3.10.11 (p. 288)', 'v2', 'Los establecimientos y personas autorizadas cumplen los requisitos y técnicas de embalaje, transporte y entrega física del modelo de gestión: los medicamentos se transportan de modo que su integridad no se deteriore, se mantengan las condiciones de almacenaje, se protejan contra hurto, se conserve su identificación y se evite la contaminación o confusión con otros productos, sin exposición a condiciones ambientales distintas de las especificadas en la etiqueta ni a microorganismos o plagas.', 'No definida en la norma (observación de vehículos o contenedores de transporte)', 'Aplica solo a quienes embalen, transporten o entreguen medicamentos (transporte propio o contratado)', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P07-10', 'Registros de condiciones especiales durante el transporte, entregados al destinatario', 'Cumple si · por cada envío o recibo de productos con condiciones especiales, existe registro que demuestra el cumplimiento durante el transporte y fue entregado al destinatario.', 'Res. 1403/2007 Manual T.II Cap.III num. 7.4 lit. c (p.73); Res. 1403/2007 Manual T.II Cap.III num. 7.5 lit. d (p.73)', 'v2', 'Para medicamentos que requieren condiciones especiales de almacenamiento existen registros y controles que demuestran el cumplimiento de esas exigencias durante el transporte, y ese registro se entrega al destinatario.', 'Registros de condiciones de transporte', 'Aplica solo a quienes transporten, entreguen o reciban productos con condiciones especiales de almacenamiento', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P07-11', 'Envío solo tras orden de pedido, con recibo de la orden y envío documentados', 'Cumple si · cada envío está precedido por una orden de pedido y están documentados el recibo de la orden y el envío.', 'Res. 1403/2007 Manual T.II Cap.III num. 7.4 lit. d (p.73)', 'v2', 'El envío y transporte de materiales y medicamentos se realiza solo después del recibo de una orden de pedido; se documenta y registra el recibo de la orden y el envío de las mercancías.', 'Orden de pedido y registro de envío', 'Aplica solo a quienes despachen medicamentos a terceros', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P07-12', 'Documento acompañante de la entrega con datos de producto, proveedor y destinatario', 'Cumple si · cada entrega va acompañada de documento con todos los datos listados.', 'Res. 1403/2007 Manual T.II Cap.III num. 7.5 lit. c (p.73)', 'v2', 'La entrega se acompaña de documento con fecha, nombre, número de lote, forma farmacéutica y cantidad del producto, y el nombre y dirección del proveedor y del destinatario.', 'Documento de entrega', 'Aplica solo a quienes entreguen medicamentos a terceros (verificable también por el destinatario en la recepción)', NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P07-13', 'Registros de envío accesibles y completos hasta la entrega', 'Cumple si · los registros de envío son de fácil acceso, se conservan hasta la entrega y contienen todos los datos listados.', 'Res. 1403/2007 Manual T.II Cap.III num. 7.3 inc. 3 (p.73)', 'v2', 'Los registros de envío son de fácil acceso, se conservan hasta el momento de la entrega e indican por lo menos: fecha de envío; nombre y dirección del remitente; nombre y dirección del cliente; descripción del producto (nombre, forma de dosificación y concentración si es apropiado), cantidad y número de lote(s).', 'Registros de envío', 'Aplica solo a quienes despachen o transporten medicamentos', NULL, NULL, NULL::jsonb, NULL::jsonb, 7),
    ('P07-14', 'Embalaje protector, de materiales apropiados y con rotulado indeleble y claro', 'Cumple si · los medicamentos despachados van en balas o cubiertas protectoras, los embalajes de varias unidades son de materiales apropiados y el rotulado es indeleble y claro.', 'Res. 1403/2007 Manual T.II Cap.III num. 7.3 inc. 1 (p.72); Res. 1403/2007 Manual T.II Cap.III num. 7.3 inc. 2 (p.72)', 'v2', 'Los medicamentos a transportar se colocan en balas o cubiertas que garanticen protección adecuada contra los aspectos externos; los embalajes de varias unidades son de materiales apropiados para su conservación y su rotulado es indeleble y claro.', 'No definida en la norma (observación)', 'Aplica solo a quienes despachen o transporten medicamentos', NULL, NULL, NULL::jsonb, NULL::jsonb, 8),
    ('P07-15', 'Información y documentos del remitente al transportador', 'Cumple si · existen soportes de la información entregada al transportador (características, condiciones especiales y carácter restringido, cuando aplique) y de los documentos de transporte suministrados antes del despacho.', 'Res. 1403/2007 Manual T.II Cap.III num. 7.1 inc. 2 (p.72); Res. 1403/2007 Manual T.II Cap.III num. 7.2 inc. 1 (p.72); Res. 1403/2007 Manual T.II Cap.III num. 7.1 inc. 1 (p.72)', 'v2', 'El remitente indica al transportador, a más tardar al momento de la entrega, las características de los medicamentos y las condiciones especiales de almacenamiento, embalaje, cargue, ubicación y entrega técnica; le informa el carácter restringido de medicamentos o materias primas con sus condiciones especiales de manejo y precauciones; y le suministra antes del despacho los documentos necesarios para el transporte y las formalidades de policía, aduana y sanidad.', 'Documentos de transporte (explícito); para la información al transportador no definida en la norma (se desprende: instrucciones escritas)', 'Aplica solo a quienes despachen medicamentos mediante transportador', NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P07-16', 'Transporte propio: no transportar productos en mal estado y permitir verificación', 'Cumple si · no se transportan medicamentos en mal estado o con embalaje/acondicionamiento que constituya peligro evidente y se permite al destinatario verificar los medios de almacenamiento cuando se requiere.', 'Res. 1403/2007 Manual T.II Cap.III num. 7.2 inc. 2 (p.72); Res. 1403/2007 Manual T.II Cap.III num. 7.5 lit. e (p.73)', 'v2', 'Quien transporta no lleva medicamentos que, por su mal estado, embalaje, acondicionamiento u otras circunstancias graves, puedan constituir peligro evidente, y permite al destinatario verificar la existencia de medios adecuados de almacenamiento durante el transporte cuando la naturaleza de los productos lo exige.', 'No definida en la norma', 'Aplica solo a establecimientos que transporten medicamentos por cuenta propia (si el transporte es contratado, la obligación recae en el transportador)', NULL, NULL, NULL::jsonb, NULL::jsonb, 10)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C16', 'Devoluciones, retiro del mercado y destrucción', 'La Res. 3100 solo exige área y procedimiento documentado. La Res. 1403 fija las condiciones de reubicación y el procedimiento de retiro del mercado.', 'Cruce Res. 3100 vs Res. 1403 y 2955', NULL, NULL, NULL, ARRAY['ESM', 'FA', 'NC']::text[], 'Res. 1403/2007 Art. 25-26; Manual T.II Cap.II num. 3.5 (p.48-49) · cruce', 17) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P11-04', 'Medicamentos devueltos por pacientes: no reingresan al inventario y se destruyen', 'Cumple si · los medicamentos devueltos por pacientes no se reintegran al inventario y se destinan a destrucción o desnaturalización.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.5.3 (p.49)', 'v2', 'Los medicamentos devueltos por los pacientes no se devuelven al inventario, sino que se destruyen o desnaturalizan.', 'No definida en la norma (se desprende: registros de destrucción o desnaturalización)', 'Aplica solo a servicios y establecimientos que dispensan (SF de IPS, F-D, DRG)', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P11-05', 'Productos devueltos separados de los disponibles hasta decidir su destino', 'Cumple si · los productos devueltos están separados del área de disponibles y no se redistribuyen hasta que se decide su disponibilidad.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.5.1 (p.48)', 'v2', 'Los productos devueltos se guardan aparte del área de productos disponibles para la venta y/o dispensación y se previene su redistribución hasta que se decida que están disponibles.', 'No definida en la norma (observación)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P11-06', 'Reubicación de devueltos solo si cumplen las condiciones a) a d)', 'Cumple si · cada producto devuelto reubicado cumple a), b), c) y d), con soporte de la evaluación del director.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.5.2 lit. a–c (p.48–49); Res. 1403/2007 Manual T.II Cap.II num. 3.5.2 lit. d (p.49)', 'v2', 'Los productos devueltos solo se reubican en el área de disponibles si: a) están en sus recipientes originales sin abrir y en buenas condiciones; b) se demuestra que se almacenaron y manejaron según las condiciones del fabricante; c) su vida útil restante es superior al mínimo establecido; d) fueron examinados y evaluados por el director del establecimiento o SF (naturaleza del producto, condiciones especiales de almacenamiento, tiempo desde el despacho; concepto del titular del registro o del fabricante si es necesario) para autorizar su devolución.', 'No definida en la norma (se desprende: soporte de la evaluación y autorización del director)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P11-07', 'Comunicación a la autoridad sanitaria de devueltos que no cumplen especificaciones', 'Cumple si · para cada devuelto con incumplimiento comprobado de especificaciones, existe comunicación a la autoridad sanitaria competente.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.5.2 lit. d (p.49)', 'v2', 'Si se comprueba que un producto devuelto no cumple las especificaciones técnicas de calidad, el SF o establecimiento lo comunica en primera instancia a las autoridades sanitarias competentes.', 'No definida en la norma (se desprende: comunicación radicada)', 'Aplica solo si se comprobó incumplimiento de especificaciones de calidad en productos devueltos', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P11-08', 'Identificación y registro de productos reingresados al inventario disponible', 'Cumple si · cada producto reingresado al inventario disponible está identificado y consignado en los registros.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.5.3 (p.49)', 'v2', 'Cualquier producto que se vuelva a ingresar al inventario disponible se identifica y se consigna en los registros correspondientes.', 'Registros de reingreso', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P11-10', 'Solicitud oportuna al proveedor de cambio o devolución de productos próximos a vencer', 'Cumple si · existen solicitudes al proveedor de cambio o devolución de los productos próximos a vencer, realizadas con antelación según las condiciones de negociación.', 'Res. 1403/2007 Manual T.II Cap.II num. 3.6.5 (p.50); num. 5.4.1 (p.57); num. 5.4.2 lit. b (p.57)', 'v2', 'Se solicita al proveedor, con la debida antelación y conforme a las condiciones de la negociación, el cambio o la devolución de medicamentos con fechas próximas de vencimiento.', 'No definida en la norma (se desprende: solicitudes al proveedor)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P11-11', 'Retiro del mercado: procedimiento escrito y responsables designados', 'Cumple si · existe procedimiento escrito vigente de retiro del mercado y responsables designados.', 'Res. 1403/2007 Art. 26 inc. 1 (p.14)', 'v2', 'Los fabricantes, titulares de registro sanitario y distribuidores cuentan con responsables y procedimientos escritos para retirar de manera inmediata del mercado los medicamentos y DM que no cumplan especificaciones técnicas de calidad o cuando lo solicite el INVIMA.', 'Procedimiento escrito y designación de responsables', 'Aplica solo a distribuidores (DD, AEF), fabricantes y titulares de registro sanitario; la norma no define ''distribuidor''', NULL, NULL, NULL::jsonb, NULL::jsonb, 7),
    ('P11-12', 'Retiro: registro de entregas que identifica de inmediato el destino de los productos', 'Cumple si · para un lote seleccionado, el sistema de registro de entregas identifica de inmediato su destino.', 'Res. 1403/2007 Art. 26 inc. 1 (p.14)', 'v2', 'El sistema de registro de entregas del distribuidor permite la identificación inmediata del destino de todos los productos comercializados.', 'Sistema de registro de entregas', 'Aplica solo a distribuidores (DD, AEF), fabricantes y titulares de registro sanitario; la norma no define ''distribuidor''', NULL, NULL, NULL::jsonb, NULL::jsonb, 8),
    ('P11-13', 'Retiro: separación inmediata de los productos y ubicación en área segura', 'Cumple si · los productos objeto de retiro están fuera del inventario disponible y en un área segura.', 'Res. 1403/2007 Art. 26 num. 3 (p.15)', 'v2', 'El distribuidor o quien tenga los productos objeto de retiro los separa inmediatamente del inventario y/o del sitio de almacenamiento y los coloca en un área segura hasta que se decida su destino final.', 'No definida en la norma (observación del área y del inventario)', 'Aplica solo cuando el establecimiento tenga productos objeto de retiro del mercado', NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P11-14', 'Retiro: registro con cantidades entregadas, retiradas y diferencia, disponible', 'Cumple si · existe registro e informe de cada retiro con las tres cantidades (entregada, retirada y diferencia), elaborado en el momento del retiro y disponible en la visita.', 'Res. 1403/2007 Art. 26 num. 4 (p.15)', 'v2', 'El proceso de retiro se registra en el momento en que se realiza; el informe incluye la cantidad de productos entregados por el distribuidor a quien los tenga, la cantidad retirada del mercado y la diferencia; la documentación queda inmediatamente a disposición de la autoridad competente.', 'Registro e informe de retiro', 'Aplica solo a distribuidores y a quien tenga productos objeto de retiro', NULL, NULL, NULL::jsonb, NULL::jsonb, 10),
    ('P11-15', 'Retiro: revisión y evaluación periódica del sistema de retiro', 'Cumple si · existen registros de revisión y evaluación del sistema de retiro con la periodicidad definida.', 'Res. 1403/2007 Art. 26 num. 5 (p.15)', 'v2', 'Periódicamente se efectúa una revisión y evaluación del sistema de retiro de medicamentos y DM que no cumplan especificaciones técnicas de calidad.', 'No definida en la norma (se desprende: registro de la revisión)', 'Aplica solo a distribuidores (DD, AEF), fabricantes y titulares de registro sanitario; la norma no define ''distribuidor''', NULL, NULL, NULL::jsonb, NULL::jsonb, 11),
    ('P11-16', 'Retiro: información al INVIMA dentro de las 24 horas siguientes', 'Cumple si · existe constancia de comunicación al INVIMA con fecha y hora dentro de las 24 horas siguientes a cada retiro.', 'Res. 1403/2007 Art. 26 parágrafo (p.15)', 'v2', 'Los fabricantes, titulares de registro sanitario y distribuidores informan al INVIMA, dentro de las 24 horas siguientes, el retiro de medicamentos que no cumplan especificaciones técnicas de calidad.', 'No definida en la norma (se desprende: constancia de comunicación al INVIMA)', 'Aplica solo a distribuidores (DD, AEF), fabricantes y titulares de registro sanitario; la norma no define ''distribuidor''', NULL, NULL, NULL::jsonb, NULL::jsonb, 12),
    ('P11-02', 'Destrucción/desnaturalización conforme al manual técnico aplicable (vacío normativo)', 'Cumple si · la destrucción o desnaturalización se realiza conforme a las reglas técnicas del manual aplicable; no existe en la documentación cargada un manual vigente con reglas específicas para medicamentos.', 'Res. 1403/2007 Art. 25 parágrafo (p.13)', 'v2', 'La destrucción y desnaturalización de medicamentos se rige por el manual adoptado mediante la Res. 1164/2002 o las normas que la modifiquen, adicionen o sustituyan.', 'No definida en la norma (los requisitos técnicos remiten a una norma derogada sin reemplazo específico en la documentación)', 'Aplica solo a quienes destruyan o desnaturalicen medicamentos', NULL, NULL, NULL::jsonb, NULL::jsonb, 13)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C17', 'Comité de Farmacia y Terapéutica', 'Vacío 4: la Res. 3100 no exige el Comité de Farmacia y Terapéutica; solo un comité de seguridad del paciente, infecciones y antibióticos.', 'Cruce Res. 3100 vs Res. 1403 y 2955', NULL, NULL, NULL, ARRAY['ESM']::text[], 'Res. 1403/2007 Manual T.I Cap.II num. 4 (p.26-27) · cruce', 18) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P13-01', 'Comité de Farmacia y Terapéutica conformado y en funcionamiento permanente', 'Cumple si · el CFT está conformado y sesionando.', 'Res. 1403/2007 Manual T.I Cap.II num. 4 (p.26); Dec. 780/2016 Art. 2.5.3.10.24 (p. 296)', 'v2', 'La IPS tiene en funcionamiento el Comité de Farmacia y Terapéutica, de carácter permanente.', 'No definida en la norma (se desprende: acto de conformación y actas)', 'Aplica solo a IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 1),
    ('P13-02', 'Integración del CFT conforme a la norma', 'Cumple si · los integrantes (a) a (d) están designados y participan, y (e) y (f) participan cuando el tema lo requiere.', 'Res. 1403/2007 Manual T.I Cap.II num. 4.1 (p.26); Dec. 780/2016 Art. 2.5.3.10.24 num. 1-6 (p. 296)', 'v2', 'El CFT está integrado por: (a) el director o gerente de la institución o su delegado; (b) el subdirector científico o quien haga sus veces; (c) el director del servicio farmacéutico; (d) el director de enfermería o quien haga sus veces; y, cuando el tema a desarrollar o discutir lo requiera, (e) un representante de la especialidad médica respectiva y (f) un representante del área administrativa y financiera.', 'No definida en la norma (se desprende: acto de conformación y actas)', 'Aplica solo a IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 2),
    ('P13-03', 'CFT invita a representante de los usuarios cuando el tema afecta sus intereses', 'Cumple si · en las sesiones con temas de relación directa con los intereses de los usuarios consta la invitación a un representante de los usuarios que es profesional titulado del área de la salud.', 'Res. 1403/2007 Manual T.I Cap.II num. 4.2 (p.27); Dec. 780/2016 Art. 2.5.3.10.24 par. (p. 296)', 'v2', 'El CFT invita a un representante de los usuarios del servicio farmacéutico de la institución, con la condición de profesional titulado del área de la salud, cuando el tema a tratar tenga relación directa con los intereses de los usuarios.', 'No definida en la norma (se desprende: actas con constancia de la invitación)', 'Aplica solo a IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 3),
    ('P13-04', 'CFT sesiona al menos una vez al mes y archiva el acta de cada reunión', 'Cumple si · hay al menos un acta por cada mes del periodo revisado y las actas están archivadas.', 'Res. 1403/2007 Manual T.I Cap.II num. 4.3 (p.27)', 'v2', 'El CFT se reúne por lo menos una vez al mes; de cada reunión se elaboran y mantienen debidamente archivadas las actas.', 'Actas de reunión archivadas', 'Aplica solo a IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 4),
    ('P13-05', 'CFT formuló políticas de medicamentos y DM con mecanismos de implementación y vigilancia', 'Cumple si · existen políticas documentadas sobre cada uno de los aspectos listados y mecanismos de implementación y vigilancia establecidos.', 'Res. 1403/2007 Manual T.I Cap.II num. 4.4 lit. a (p.27); Dec. 780/2016 Art. 2.5.3.10.25 num. 1 (p. 296)', 'v2', 'El CFT formula las políticas sobre medicamentos y dispositivos médicos en la IPS en relación con la prescripción, dispensación, administración, sistemas de distribución, uso y control, y establece los mecanismos de implementación y vigilancia de las mismas.', 'No definida en la norma (se desprende: políticas documentadas y actas)', 'Aplica solo a IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 5),
    ('P13-06', 'CFT recomienda, cuando corresponda, solicitudes de inclusión o exclusión de medicamentos', 'Cumple si · cuando se han presentado necesidades de inclusión o exclusión de medicamentos, las actas registran la recomendación del CFT.', 'Res. 1403/2007 Manual T.I Cap.II num. 4.4 lit. b (p.27); Dec. 780/2016 Art. 2.5.3.10.25 num. 2 (p. 296-297)', 'v2', 'El CFT recomienda la solicitud de inclusión y/o exclusión de medicamentos del plan de beneficios ante la instancia competente, de acuerdo con el procedimiento definido para el efecto.', 'No definida en la norma (se desprende: actas con las recomendaciones)', 'Aplica solo a IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 6),
    ('P13-07', 'CFT conceptúa sobre las guías de manejo de las patologías más frecuentes', 'Cumple si · las actas registran conceptos del CFT sobre las guías de manejo de las patologías más frecuentes de la institución.', 'Res. 1403/2007 Manual T.I Cap.II num. 4.4 lit. c (p.27); Dec. 780/2016 Art. 2.5.3.10.25 num. 3 (p. 297)', 'v2', 'El CFT conceptúa sobre las guías de manejo para el tratamiento de las patologías más frecuentes en la institución.', 'No definida en la norma (se desprende: actas)', 'Aplica solo a IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 7),
    ('P13-08', 'CFT coordina con el Comité de Infecciones perfiles epidemiológicos y eficacia terapéutica', 'Cumple si · hay evidencia (actas) de la coordinación del CFT con el Comité de Infecciones sobre perfiles epidemiológicos y eficacia de la terapia, incluido el uso de antibióticos.', 'Res. 1403/2007 Manual T.I Cap.II num. 4.4 lit. d (p.27); Dec. 780/2016 Art. 2.5.3.10.25 num. 4 (p. 297)', 'v2', 'El CFT coordina con el Comité de Infecciones de la IPS el impacto, seguimiento y evaluación de los perfiles epidemiológicos institucionales y la eficacia de la terapia farmacológica instaurada en los casos especiales, principalmente la relacionada con el uso de antibióticos.', 'No definida en la norma (se desprende: actas)', 'Aplica solo a IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 8),
    ('P13-09', 'SF reporta al CFT sospechas de EA/PRM; el CFT las analiza e informa resultados', 'Cumple si · hay evidencia del envío de datos del SF al CFT, de su análisis en el CFT y de la comunicación de resultados a los destinatarios listados.', 'Res. 1403/2007 Manual T.I Cap.II num. 4.4 lit. e (p.27); Dec. 780/2016 Art. 2.5.3.10.25 num. 5 (p. 297); Dec. 780/2016 Art. 2.5.3.10.25 num. 5 (p. 297); Res. 1403/2007 Manual T.II Cap.III num. 5.2.4 (p.69)', 'v2', 'El servicio farmacéutico envía al CFT los datos sobre sospecha de eventos adversos o cualquier otro problema relacionado con los medicamentos; el CFT los recolecta y analiza e informa los resultados al médico tratante, al paciente, al personal de salud, a las administradoras (EAPB) y a las autoridades correspondientes.', 'No definida en la norma (se desprende: reportes del SF al CFT, actas y comunicaciones de resultados)', 'Aplica solo a IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 9),
    ('P13-10', 'Decisiones del CFT aprobadas por el director, gerente o quien haga sus veces', 'Cumple si · las decisiones del CFT tienen constancia de aprobación del director, gerente o quien haga sus veces.', 'Res. 1403/2007 Manual T.I Cap.II num. 4.5 (p.27)', 'v2', 'Para que tengan validez, las decisiones del CFT son aprobadas por el director, gerente o quien haga sus veces en la institución.', 'No definida en la norma (se desprende: firma o constancia de aprobación en actas)', 'Aplica solo a IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 10),
    ('P13-11', 'El SF participa en los Comités de Farmacia y Terapéutica, Infecciones y Bioética', 'Cumple si · el SF figura como integrante y participa en los tres comités.', 'Res. 1403/2007 Art. 5 num. 11 (p.4); Dec. 780/2016 Art. 2.5.3.10.7 num. 10 (p. 286)', 'v2', 'El servicio farmacéutico forma parte y participa en los Comités de Farmacia y Terapéutica, de Infecciones y de Bioética de la institución, entre otros.', 'No definida en la norma (se desprende: actas de los comités con participación del SF)', 'Aplica solo a servicios farmacéuticos de IPS', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 11),
    ('P16-42', 'IPS: protocolos del art. 10 elaborados/sugeridos por el CFT y aprobados por el director', 'Cumple si · los protocolos del art. 10 vigentes fueron elaborados o sugeridos por el CFT (con el Comité de Infecciones cuando aplique) y cuentan con aprobación del director, gerente o quien haga sus veces.', 'Res. 1403/2007 Art. 11 inc. 2 (p.7–8)', 'v2', 'En las IPS, el Comité de Farmacia y Terapéutica, en colaboración con el Comité de Infecciones cuando sea del caso, elabora o sugiere la adopción de los protocolos del art. 10 de la Res. 1403/2007 y los presenta para la aprobación del director, gerente o quien haga sus veces.', 'No definida en la norma (se desprende: acta del CFT y constancia de aprobación del director/gerente)', 'Aplica solo a IPS que realizan procesos que requieren los protocolos del art. 10 de la Res. 1403/2007', NULL, '4 · Comité de Farmacia y Terapéutica', NULL::jsonb, NULL::jsonb, 12)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C18', 'Atención farmacéutica y farmacovigilancia', 'La Res. 3100 exige el programa de farmacovigilancia documentado (11.1.4 num. 6); la Res. 1403 fija su contenido y los plazos de reporte.', 'Cruce Res. 3100 vs Res. 1403 y 2955', NULL, NULL, NULL, ARRAY['ESM', 'FA']::text[], 'Res. 1403/2007 Manual T.II Cap.III num. 1 y 5 (p.57-59, 68-70) · cruce', 19) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P12-01', 'Procedimiento escrito para la prestación de la atención farmacéutica', 'Cumple si · existe el procedimiento escrito de atención farmacéutica con los elementos del Manual (T.II Cap.III num. 1).', 'Res. 1403/2007 Art. 10 parágrafo (p.7); Res. 1403/2007 Manual T.II Cap.III num. 1.2 inc. 3 (p.58)', 'v2', 'Los SF de las IPS y los establecimientos farmacéuticos autorizados elaboran por escrito el procedimiento para la prestación de la atención farmacéutica, con las disposiciones del Manual de la Res. 1403/2007 y las técnicas y criterios aceptados en la comunidad farmacéutica nacional e internacional.', 'Procedimiento escrito', 'Aplica a SF de IPS y establecimientos farmacéuticos autorizados (ver nota: el texto no lo condiciona expresamente a que presten atención farmacéutica)', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P12-02', 'Atención farmacéutica prestada por QF y bajo dirección técnica de QF', 'Cumple si · la atención farmacéutica la presta un QF y el servicio o establecimiento que la ofrece está dirigido por un QF.', 'Res. 1403/2007 Manual T.II Cap.III num. 1.1 inc. 1 (p.57); Res. 1403/2007 Manual T.II Cap.III num. 1.1 inc. 3 (p.57); Dec. 780/2016 Art. 2.7.2.3.2.2.1 lit. e (p. 435)', 'v2', 'La atención farmacéutica es la asistencia del Químico Farmacéutico al paciente o grupos de pacientes que lo requieran. Los servicios de atención farmacéutica hospitalarios y ambulatorios están bajo dirección técnica de QF (competencia exclusiva). La farmacia-droguería y la droguería solo pueden ofrecer atención farmacéutica al público si están dirigidas por un QF.', 'No definida en la norma (se desprende: registros de atención farmacéutica firmados por QF; título del director)', 'Aplica solo a SF o establecimientos que prestan atención farmacéutica (proceso de los SF de IPS de mediana y alta complejidad; en FD/D solo si están dirigidas por QF)', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('CR-01', 'Asistencia básica del TRF y del auxiliar en IPS de baja complejidad, según sus competencias', 'Cumple si · en el servicio farmacéutico de baja complejidad o primer nivel, el Tecnólogo en Regencia de Farmacia y el auxiliar en servicios farmacéuticos solo dan asistencia básica (dispensación, promoción y uso adecuado, recolección de información de medicamentos y del programa de farmacovigilancia) según sus competencias, y la atención farmacéutica la presta un Químico Farmacéutico.', 'Res. 1403/2007 Manual T.II Cap.III num. 1.1 inc. 1 (p.57); inc. 4 (p.58)', 'cruce', 'En los servicios farmacéuticos de IPS de baja complejidad o primer nivel, el TRF y el auxiliar pueden dar asistencia básica farmacéutica en la dispensación, promoción y uso adecuado de medicamentos, y recolección de información relacionada con los medicamentos y con la farmacovigilancia, cada uno según sus competencias.', 'Funciones asignadas al personal; observación.', '', 'Solo SF de IPS de baja complejidad', NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P12-03', 'AF con entrevista, perfil farmacoterapéutico, gestión de PRM/PRUM y seguimiento', 'Cumple si · para los pacientes en atención farmacéutica, hay evidencia de entrevista directa por el QF, perfil farmacoterapéutico elaborado, gestión de PRM/PRUM con intervenciones y seguimiento permanente.', 'Dec. 780/2016 Art. 2.5.3.10.6 par. (p. 285); Res. 1403/2007 Manual T.II Cap.III num. 1.2 inc. 1–2 (p.58)', 'v2', 'Quien presta atención farmacéutica establece contacto directo con el paciente mediante la entrevista; elabora el perfil farmacoterapéutico; previene, detecta y resuelve los Problemas Relacionados con Medicamentos (PRM) y con el Uso de Medicamentos (PRUM); realiza las intervenciones necesarias, y hace el seguimiento permanente en unión con otros profesionales de la salud, con estrategias para las necesidades particulares del paciente.', 'Perfil farmacoterapéutico; para los demás elementos, no definida en la norma (se desprende: registros de entrevista e intervenciones)', 'Aplica solo a SF o establecimientos que prestan atención farmacéutica (proceso de los SF de IPS de mediana y alta complejidad; en FD/D solo si están dirigidas por QF)', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P12-04', 'Políticas de selección de pacientes o grupos para atención farmacéutica', 'Cumple si · existen políticas definidas de selección de pacientes o grupos para la atención farmacéutica.', 'Res. 1403/2007 Manual T.II Cap.III num. 1.3 (p.58)', 'v2', 'La IPS o el establecimiento farmacéutico minorista que presta atención farmacéutica determina las políticas para la selección de los pacientes o grupos de pacientes a los que se les presta (la norma enuncia como principales grupos los de los literales a) a i) del num. 1.3).', 'No definida en la norma (se desprende: política documentada)', 'Aplica solo a IPS y establecimientos minoristas que presten atención farmacéutica', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P12-05', 'Sistema de vigilancia de interacciones en los pacientes de atención farmacéutica', 'Cumple si · existe y opera un sistema de vigilancia de interacciones medicamento–alimento y medicamento–automedicación para los pacientes en atención farmacéutica.', 'Res. 1403/2007 Manual T.II Cap.III num. 1.4 lit. a (p.59)', 'v2', 'El prestador de la atención farmacéutica desarrolla un sistema de vigilancia de interacciones de medicamentos con alimentos o de medicamentos prescritos con otros que el paciente se esté autoadministrando, especialmente en pacientes de edad avanzada con múltiples patologías y polimedicados.', 'No definida en la norma', 'Aplica solo a SF o establecimientos que prestan atención farmacéutica (proceso de los SF de IPS de mediana y alta complejidad; en FD/D solo si están dirigidas por QF)', NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P12-06', 'Detección de posibles eventos adversos en los pacientes de atención farmacéutica', 'Cumple si · hay evidencia de actividades de búsqueda o detección de eventos adversos en los pacientes en atención farmacéutica.', 'Res. 1403/2007 Manual T.II Cap.III num. 1.4 lit. b (p.59)', 'v2', 'El prestador de la atención farmacéutica se esfuerza en detectar los posibles eventos adversos de los medicamentos que toman sus pacientes.', 'No definida en la norma', 'Aplica solo a SF o establecimientos que prestan atención farmacéutica (proceso de los SF de IPS de mediana y alta complejidad; en FD/D solo si están dirigidas por QF)', NULL, NULL, NULL::jsonb, NULL::jsonb, 7),
    ('P12-07', 'Registro claro y fidedigno de las actuaciones de atención farmacéutica', 'Cumple si · existe registro de las actuaciones de atención farmacéutica, que incluye los consejos al paciente y las intervenciones en la farmacoterapia.', 'Res. 1403/2007 Manual T.II Cap.III num. 1.4 lit. c (p.59)', 'v2', 'El prestador de la atención farmacéutica lleva un registro claro y fidedigno de todas las actuaciones realizadas en el proceso, especialmente los consejos al paciente y las intervenciones en la farmacoterapia.', 'Registro de atención farmacéutica', 'Aplica solo a SF o establecimientos que prestan atención farmacéutica (proceso de los SF de IPS de mediana y alta complejidad; en FD/D solo si están dirigidas por QF)', NULL, NULL, NULL::jsonb, NULL::jsonb, 8),
    ('P12-09', 'Mecanismos y recursos para detectar, identificar y resolver PRM, PRUM y eventos adversos', 'Cumple si · el SF demuestra mecanismos y recursos en operación para detectar, identificar y resolver PRM, PRUM y eventos adversos.', 'Res. 1403/2007 Manual T.II Cap.I num. 1.2 lit. f (p.42)', 'v2', 'El SF cuenta con mecanismos y recursos que permiten la detección, identificación y resolución de los PRM, los PRUM y los eventos adversos en general (actividad de promoción y prevención del SF).', 'No definida en la norma', 'Aplica a SF de IPS y a farmacias-droguerías o droguerías contratadas en el SGSSS (Dec. 780 art. 2.5.3.10.11 par. 2)', NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P12-10', 'Participación en programas de farmacovigilancia, tecnovigilancia y uso adecuado', 'Cumple si · hay evidencia de participación en los programas de farmacovigilancia, tecnovigilancia, uso de antibióticos y uso adecuado de medicamentos que le competen.', 'Dec. 780/2016 Art. 2.5.3.10.7 num. 6 (p. 286); Res. 1403/2007 Manual T.II Cap.I num. 1.2 lit. g (p.42); Res. 1403/2007 Manual T.I Cap.V num. 1.4 lit. d (p.36–37); num. 2.3 lit. d (p.41)', 'v2', 'El SF participa en la creación y desarrollo de programas relacionados con los medicamentos y DM, especialmente de farmacovigilancia, uso de antibióticos y uso adecuado de medicamentos, y cumple las actividades que le competen en los programas nacionales de Farmacovigilancia, Tecnovigilancia y Uso Adecuado de Medicamentos. La FD o droguería contratada asume, solidariamente con la IPS contratante y la EAPB, la obligación de participar en los programas y campañas nacionales o locales relacionados con el uso de medicamentos.', 'No definida en la norma (se desprende: soportes de participación)', 'Aplica a SF de IPS y a farmacias-droguerías o droguerías contratadas en el SGSSS (Dec. 780 art. 2.5.3.10.11 par. 2)', NULL, NULL, NULL::jsonb, NULL::jsonb, 10),
    ('P12-11', 'Programa institucional de farmacovigilancia documentado y en ejecución', 'Cumple si · existe el programa institucional de farmacovigilancia documentado (planeación) con evidencia de ejecución.', 'Res. 1403/2007 Manual T.II Cap.III num. 5.2 (p.68); Res. 3100/2019 Manual 11.1.4 num. 6 (p.72)', 'v2', 'La IPS cuenta con un programa institucional de farmacovigilancia con perspectiva especialmente clínica/individual, que permita establecer y prevenir problemas relacionados con la indicación, efectividad y seguridad de los medicamentos; el prestador inscrito en REPS cuenta con información documentada de la planeación y ejecución del programa de farmacovigilancia.', 'Información documentada de la planeación y ejecución del programa', 'Aplica solo a servicios farmacéuticos de IPS (prestadores de servicios de salud)', NULL, NULL, NULL::jsonb, NULL::jsonb, 11),
    ('P12-12', 'Procedimiento estandarizado de notificación, registro, análisis y envío de reportes de FV', 'Cumple si · existe el procedimiento con notificación, registro, procesamiento, análisis clínico y envío de reportes, y se aplica.', 'Res. 1403/2007 Manual T.II Cap.III num. 5.2.1 (p.68)', 'v2', 'El programa institucional de farmacovigilancia contiene un procedimiento estandarizado para la notificación, registro y procesamiento de eventos, el análisis clínico de la información y el envío de reportes a la entidad reguladora correspondiente.', 'Procedimiento', 'Aplica solo a servicios farmacéuticos de IPS (prestadores de servicios de salud)', NULL, NULL, NULL::jsonb, NULL::jsonb, 12),
    ('P12-13', 'Formato de reporte de eventos adversos (INVIMA o institucional con datos mínimos)', 'Cumple si · se usa el formato del INVIMA o un formulario institucional que contiene todos los datos a) a e).', 'Res. 1403/2007 Manual T.II Cap.III num. 5.2.2 (p.69)', 'v2', 'Se usa el formato de reporte nacional del INVIMA o, en su defecto, un formulario institucional de notificación de eventos adversos con: a) identificación del paciente (género y edad); b) medicamento sospechoso y medicación concomitante (indicación, fecha de inicio, dosis, vía, frecuencia y momento de suspensión); c) información del evento (inicio, evolución y desenlace); d) diagnóstico y enfermedades concomitantes, con paraclínicos pertinentes; e) identificación del notificador (profesión y contacto).', 'Formato de reporte nacional del INVIMA o formulario institucional', 'Aplica solo a servicios farmacéuticos de IPS (prestadores de servicios de salud)', NULL, NULL, NULL::jsonb, NULL::jsonb, 13),
    ('P12-14', 'Programa continuo de capacitación sobre el perfil de seguridad de los medicamentos', 'Cumple si · existe el programa continuo de capacitación con contenidos sobre el perfil de seguridad de los medicamentos de la institución y evidencia de ejecución.', 'Res. 1403/2007 Manual T.II Cap.III num. 5.2.3 (p.69)', 'v2', 'El programa de farmacovigilancia incluye un programa continuo de divulgación y capacitación a profesionales y trabajadores de la salud que incluya, entre otros aspectos, el perfil de seguridad de los medicamentos utilizados en la institución.', 'No definida en la norma (se desprende: programa y registros de capacitación)', 'Aplica solo a servicios farmacéuticos de IPS (prestadores de servicios de salud)', NULL, NULL, NULL::jsonb, NULL::jsonb, 14),
    ('P12-15', 'Participación del programa institucional en la red nacional de farmacovigilancia', 'Cumple si · hay evidencia de participación del programa institucional en la red nacional de farmacovigilancia (envío periódico de reportes, intercambio de resultados, aportes o vigilancia activa).', 'Res. 1403/2007 Manual T.II Cap.III num. 5.3 lit. a–d (p.69)', 'v2', 'El programa institucional participa en la estrategia de red del Programa Nacional de Farmacovigilancia (a cargo del INVIMA): envío periódico de reportes, intercambio de resultados de intervenciones, solicitud de asistencia técnica y participación en eventos nacionales; soporte a otros programas institucionales; aportes al boletín nacional; iniciativas de vigilancia activa de eventos adversos.', 'No definida en la norma', 'Aplica solo a servicios farmacéuticos de IPS (prestadores de servicios de salud)', NULL, NULL, NULL::jsonb, NULL::jsonb, 15),
    ('P12-16', 'Toda sospecha de evento adverso se reporta a la autoridad correspondiente', 'Cumple si · las sospechas de eventos adversos detectadas en el SF o establecimiento fueron reportadas a la autoridad.', 'Res. 1403/2007 Manual T.II Cap.III num. 5.1 (p.68)', 'v2', 'Se reporta a la autoridad correspondiente toda sospecha de eventos adversos relacionados con medicamentos, medios de contraste, vacunas, pruebas diagnósticas o productos fitoterapéuticos.', 'No definida en la norma (se desprende: reportes enviados)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 16),
    ('P12-17', 'Reporte mensual de sospechas de EA al INVIMA y a la ETS dentro de los 5 días', 'Cumple si · los reportes de cada mes se enviaron al INVIMA y a la ETS dentro de los 5 días siguientes al cierre del mes (en minoristas, con el formulario del INVIMA).', 'Res. 1403/2007 Manual T.II Cap.III num. 5.4 inc. 1 (p.70); Res. 1403/2007 Manual T.II Cap.III num. 5.5 (p.70)', 'v2', 'Los reportes institucionales de sospechas de eventos adversos se remiten al INVIMA y a la entidad territorial de salud dentro de los cinco (5) días siguientes al vencimiento del mes que se informa. En el establecimiento farmacéutico distribuidor minorista, el director que sospeche un evento adverso lo reporta al INVIMA y a la entidad territorial de salud dentro de los primeros cinco (5) días de cada mes, usando el formulario de notificación del INVIMA.', 'Constancias de envío; en minoristas, formulario de notificación del INVIMA', 'Aplica a SF de IPS y a establecimientos minoristas (farmacias-droguerías y droguerías)', NULL, NULL, NULL::jsonb, NULL::jsonb, 17),
    ('P12-18', 'Eventos adversos serios reportados dentro de las 72 horas siguientes a su aparición', 'Cumple si · cada evento adverso serio se reportó en un plazo de 72 horas o menos desde su aparición.', 'Res. 1403/2007 Manual T.II Cap.III num. 5.4 inc. 1 (p.70); num. 5.5 (p.70)', 'v2', 'Los eventos adversos serios se reportan dentro de las setenta y dos (72) horas siguientes a su aparición.', 'No definida en la norma (se desprende: constancia de reporte con fecha y hora)', 'Aplica a SF de IPS y a establecimientos minoristas (farmacias-droguerías y droguerías)', NULL, NULL, NULL::jsonb, NULL::jsonb, 18),
    ('P12-19', 'EA por problemas de acceso o disponibilidad remitidos a Supersalud con copia a la ETS', 'Cumple si · todos los eventos adversos asociados a problemas de acceso o disponibilidad fueron remitidos a la Supersalud con copia a la ETS.', 'Res. 1403/2007 Manual T.II Cap.III num. 5.4 inc. 3 (p.70)', 'v2', 'En todos los casos, los eventos adversos asociados a problemas de acceso o disponibilidad de medicamentos se remiten a la Superintendencia Nacional de Salud con copia a la entidad territorial de salud correspondiente.', 'No definida en la norma (se desprende: constancia de remisión)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 19)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C19', 'Gestión de calidad, información y horarios', 'Sistema de gestión de calidad, indicadores, sistema de información y horario: exigencias de la Res. 1403 que la Res. 3100 no cubre.', 'Cruce Res. 3100 vs Res. 1403 y 2955', NULL, NULL, NULL, ARRAY['ESM', 'FA', 'NC']::text[], 'Res. 1403/2007 Arts. 17-21 y 24; Manual T.I Cap.II num. 5 · cruce', 20) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('P03-01', 'Sistema de Gestión de la Calidad desarrollado, implementado, revisado y mejorado', 'Cumple si · existe un SGC documentado, implementado y con evidencia de revisión y mejora.', 'Res. 1403/2007 Art. 17 inc. 2 (p.9); Dec. 780/2016 Art. 2.5.3.10.12 (p. 289)', 'v2', 'Todo servicio farmacéutico, establecimiento farmacéutico o persona autorizada desarrolla, implementa, mantiene, revisa y perfecciona un Sistema de Gestión de la Calidad.', 'Documentación del SGC y evidencia de su revisión', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P03-02', 'SGC documenta estructura, procesos críticos, criterios, riesgos y acciones de mejora', 'Cumple si · la documentación del SGC contiene todos los elementos listados y está en uso.', 'Res. 1403/2007 Art. 17 num. 1, 5 y 6 (p.9); num. 7, 8 e inc. 3 (p.10); Res. 1403/2007 Art. 17 num. 3 (p.9)', 'v2', 'El SGC identifica y documenta en forma clara, completa y operativa, incluyendo todos los puntos de control: (1) estructura interna y principales funciones; (5) procesos estratégicos y críticos determinantes de la calidad, su secuencia e interacción, con base en criterios técnicos previamente definidos; (6) criterios y métodos para asegurar la eficacia de los procesos en su operación y control; (7) puntos de control sobre los riesgos de mayor probabilidad de ocurrencia o de impacto considerable en la satisfacción de los usuarios, con participación de los responsables de cada actividad o proceso; (8) acciones para alcanzar los resultados planificados y la mejora continua.', 'Documentación del SGC (estructura interna y funciones, procesos críticos e interacción, criterios y métodos, riesgos y puntos de control, acciones de mejora)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P03-03', 'Procesos del SF documentados y ejecutados según procedimientos, con seguimiento', 'Cumple si · existe documentación vigente para cada proceso que se realiza, la práctica observada corresponde a los procedimientos, hay evidencia de seguimiento y medición y, en prestadores, la documentación de los procesos generales fue elaborada por el responsable del servicio.', 'Res. 1403/2007 Art. 9 (p.7); Res. 1403/2007 Art. 17 num. 4 (p.9); Res. 3100/2019 Manual 11.3.2, PP num. 15.1 (p.100); Res. 3100/2019 Manual 11.1.5 num. 6 (p.73)', 'v2', 'Para cada actividad o proceso que realiza, el servicio o establecimiento cuenta con un conjunto de normas, procesos, procedimientos, recursos, mecanismos de control y documentación técnica o administrativa; los procesos propios del servicio farmacéutico se efectúan de acuerdo con los procedimientos documentados, con seguimiento, análisis y medición. En prestadores, la información documentada de los procesos generales que realiza el servicio farmacéutico es elaborada por el responsable del servicio.', 'Procedimientos documentados por proceso; registros de seguimiento y medición; información documentada elaborada por el responsable del SF (prestadores)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P03-05', 'Usuarios identificados y medición sistemática de su satisfacción', 'Cumple si · los usuarios están identificados y existen mediciones de su satisfacción realizadas en forma sistemática.', 'Res. 1403/2007 Art. 17 num. 2 (p.9); Dec. 780/2016 Art. 2.5.1.4.6 num. 2 (p. 161)', 'v2', 'El SGC identifica a los usuarios, destinatarios o beneficiarios de los servicios y el nivel de satisfacción acerca de las funciones a cargo del servicio y su calidad; en las IPS, el programa de auditoría evalúa sistemáticamente la satisfacción de los usuarios respecto al ejercicio de sus derechos y a la calidad de los servicios recibidos.', 'No definida en la norma (se desprende: mediciones de satisfacción de usuarios)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P03-06', 'Indicadores de gestión y evaluación de eficiencia, eficacia y efectividad del SF', 'Cumple si · existen indicadores de los cinco tipos con mediciones y evaluaciones de eficiencia, eficacia y efectividad.', 'Res. 1403/2007 Art. 18 inc. 1, 2 y 4 (p.10)', 'v2', 'El servicio farmacéutico determina los indicadores de gestión necesarios, básicamente de calidad técnica, de costo, de servicio, del recurso humano y de seguridad, y evalúa como mínimo la eficiencia, la eficacia y la efectividad.', 'No definida en la norma (se desprende: fichas y mediciones de indicadores; evaluaciones)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P03-07', 'Se aplican acciones para corregir los problemas que afectan los procesos', 'Cumple si · hay evidencia de acciones correctivas aplicadas frente a los problemas identificados en los procesos.', 'Res. 1403/2007 Art. 19 (p.10)', 'v2', 'El servicio farmacéutico aplica en forma efectiva los criterios, procedimientos y recursos necesarios para corregir los problemas que afecten cualquiera de los procesos.', 'No definida en la norma', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P03-08', 'Actividades del SF planificadas con participación de los responsables de cada proceso', 'Cumple si · existe planificación de las actividades del SF con evidencia de participación de los responsables de los procesos.', 'Res. 1403/2007 Art. 24 (p.13)', 'v2', 'Las IPS y los establecimientos farmacéuticos planifican las actividades de sus servicios farmacéuticos, con participación activa de las personas o responsables de cada proceso.', 'No definida en la norma (se desprende: plan de actividades)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 7),
    ('P14-01', 'Información y educación al paciente y la comunidad sobre uso adecuado de medicamentos', 'Cumple si · el proceso de información y educación sobre uso adecuado de medicamentos y DM está definido y hay evidencia de actividades dirigidas a pacientes y comunidad.', 'Dec. 780/2016 Art. 2.5.3.10.14 num. 1 (p. 290); Res. 3100/2019 Manual 11.3.2, Estructura – baja (p.97); Res. 1403/2007 Manual T.II Cap.I num. 1.2 lit. h (p.42–43); Res. Art. 7 num. 1 lit. g (p.5); Res. 1403/2007 Manual T.I Cap.V num. 1.4 lit. c (p.36); num. 2.3 lit. c (p.41); Res. 1403/2007 Manual T.I Cap.V num. 1.3 (p.36); num. 2.2 lit. b (p.40); Dec. 780/2016 Art. 2.5.3.10.26 (p. 297)', 'v2', 'El SF realiza el proceso de información y educación al paciente y a la comunidad sobre el uso adecuado de medicamentos y dispositivos médicos, incluidas actividades o programas de información, capacitación o educación a la comunidad. La FD o droguería contratada asume, solidariamente con la IPS contratante, la obligación de ofrecer información sobre los medicamentos y DM a usuarios, beneficiarios, destinatarios, autoridades y comunidad en general.', 'Información documentada del proceso (Res. 3100, Manual 11.3.2 num. 15.1); soportes de las actividades realizadas (se desprende)', 'Aplica a SF de IPS y a farmacias-droguerías o droguerías contratadas en el SGSSS (Dec. 780 art. 2.5.3.10.11 par. 2)', NULL, NULL, NULL::jsonb, NULL::jsonb, 8),
    ('P14-02', 'Información sobre uso adecuado ofrecida a quien la solicite, a cargo del Director', 'Cumple si · el establecimiento ofrece información sobre uso adecuado y, ante la solicitud de una persona, la brinda el Director del SF o del establecimiento minorista.', 'Dec. 780/2016 Art. 2.5.3.10.26 (p. 297); Res. 1403/2007 Art. 12 inc. 2 (p.8); Res. 1403/2007 Manual T.II Cap.III num. 1.1 inc. 5 (p.58)', 'v2', 'El SF de la IPS y el establecimiento minorista ofrecen la información para el uso adecuado de medicamentos y DM y mantienen vínculos con el usuario y los establecimientos mayoristas; la información que solicite una persona sobre el uso adecuado de los medicamentos la ofrece el Director del SF o del establecimiento farmacéutico minorista.', 'No definida en la norma', 'Aplica a SF de IPS, farmacias-droguerías y droguerías', NULL, NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P14-05', 'Sistema institucional de información sobre medicamentos y DM implementado', 'Cumple si · el sistema existe, está en uso, está integrado a los sistemas institucionales y su responsable es el director del SF.', 'Res. 1403/2007 Art. 20 inc. 1 (p.11); Res. 1403/2007 Art. 20 inc. 2 (p.11); Res. 1403/2007 Art. 20 inc. 3 (p.11)', 'v2', 'La IPS construye e implementa el Sistema Institucional de Información sobre medicamentos y dispositivos médicos, en lo posible computarizado, integrado al Sistema Institucional de Salud, al Sistema Integral de Información en Salud y al Sistema General de Información Administrativa; el sistema del SF está bajo la responsabilidad del director del SF.', 'No definida en la norma (se desprende: sistema en operación y responsabilidad asignada al director del SF)', 'Aplica solo a servicios farmacéuticos de IPS (prestadores de servicios de salud)', NULL, NULL, NULL::jsonb, NULL::jsonb, 10),
    ('P14-06', 'El sistema de información contiene los datos mínimos del art. 21 de la Res. 1403', 'Cumple si · el sistema contiene todos los elementos listados (1 a 14).', 'Res. 1403/2007 Art. 21 num. 1, 2 y 4 a 14 (p.11–12); Res. 1403/2007 Art. 21 num. 3 (p.11)', 'v2', 'El Sistema Institucional de Información sobre medicamentos y DM contiene datos sobre: 1) misión, visión, objetivos y funciones del SF; 2) organización del SF (estructura, dirección y ubicación en la institución); 3) comités en que resulte dable participar; 4) representación del Ministerio y divisiones administrativas relacionadas con medicamentos y DM; 5) desempeño del SF y criterios de su evaluación; 6) prestaciones del SF y manera de acceder a ellas; 7) organismos de control interno y externos del SF; 8) existencia del Programa y de la Red de Farmacovigilancia; 9) mecanismos de verificación de órdenes médicas prescritas, dispensadas y no dispensadas; 10) precios, proveedores, sanciones a proveedores y demás datos de adquisición; 11) estadísticas de eventos adversos detectados en la institución y reportados al Sistema Nacional de Farmacovigilancia; 12) Manual de Medicamentos y Terapéutica del SGSSS; 13) mecanismos para formular quejas, reclamos y sugerencias; 14) normatividad vigente sobre medicamentos y DM.', 'Contenido del sistema de información (constatación)', 'Aplica solo a servicios farmacéuticos de IPS (prestadores de servicios de salud)', NULL, NULL, NULL::jsonb, NULL::jsonb, 11),
    ('P14-07', 'Información del SF entregada por escrito y con firma del responsable', 'Cumple si · las respuestas de información emitidas por el SF constan por escrito con firma del responsable (la norma dice ''generalmente'').', 'Res. 1403/2007 Art. 20 inc. 4 (p.11)', 'v2', 'La información puede solicitarse por escrito, telefónicamente, por Internet y demás medios técnica y legalmente viables; el SF la ofrece generalmente por escrito y con la firma del responsable de la misma.', 'Respuestas escritas firmadas por el responsable', 'Aplica solo a servicios farmacéuticos de IPS (prestadores de servicios de salud)', NULL, NULL, NULL::jsonb, NULL::jsonb, 12),
    ('P14-08', 'Resultados de la evaluación del SF publicados y a disposición de los usuarios', 'Cumple si · los resultados de las mediciones están publicados de forma permanente y accesibles a los usuarios.', 'Res. 1403/2007 Art. 18 inc. 3 (p.10)', 'v2', 'Los resultados de las mediciones de la evaluación del SF están a disposición de los usuarios, beneficiarios o destinatarios y se publican de manera permanente, preferentemente en las páginas electrónicas cuando se cuente con dicho medio.', 'Publicación de los resultados (se desprende)', '', NULL, NULL, NULL::jsonb, NULL::jsonb, 13),
    ('P14-09', 'Funcionamiento diario con jornada no inferior a 8 horas', 'Cumple si · el servicio o establecimiento funciona todos los días con una jornada de al menos 8 horas.', 'Res. 1403/2007 Manual T.I Cap.II num. 5 (p.27–28); Res. 1403/2007 Manual T.I Cap.V num. 1.7 (p.39); num. 2.2 lit. d (p.40)', 'v2', 'El SF hospitalario funciona diariamente en un horario adecuado para satisfacer la demanda, con jornada no inferior a ocho horas diarias; la farmacia-droguería y la droguería funcionan diariamente en horario adecuado, con jornada no inferior a 8 horas.', 'No definida en la norma (se desprende: horario de atención)', 'Aplica a SF hospitalario de IPS, farmacias-droguerías y droguerías', NULL, NULL, NULL::jsonb, NULL::jsonb, 14),
    ('P14-35', 'Horario de atención al público visible en la parte externa', 'Cumple si · el horario de atención está publicado en la parte externa y es claramente visible.', 'Res. 1403/2007 Manual T.I Cap.II num. 5 (p.28); Res. 1403/2007 Manual T.I Cap.V num. 1.7 (p.39); num. 2.2 lit. d (p.40)', 'v2', 'El horario de atención al público está colocado en la parte externa del servicio o establecimiento y es claramente visible.', 'Aviso de horario (observación)', 'Aplica solo a servicios farmacéuticos hospitalarios, farmacias-droguerías y droguerías', NULL, NULL, NULL::jsonb, NULL::jsonb, 15),
    ('P03-11', 'Medios (preferiblemente computarizados) para registrar la comercialización', 'Cumple si · dispone de un medio de registro de la comercialización de medicamentos y dispositivos médicos con registros disponibles.', 'Res. 1403/2007 Manual T.I Cap.V num. 1.2 (p.35); num. 2.2 lit. a (p.40)', 'v2', 'La farmacia-droguería y la droguería cuentan con medios, preferiblemente computarizados, que permitan registrar la comercialización de medicamentos y dispositivos médicos.', 'Registro de comercialización (ventas) de medicamentos y dispositivos médicos', 'Aplica solo a farmacias-droguerías y droguerías', 'Solo farmacia alterna', NULL, NULL::jsonb, NULL::jsonb, 16)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

WITH c AS (INSERT INTO chk_componentes (version, codigo, nombre, descripcion, grupo, especial, escala, guia, unidades, fuente, orden) VALUES ('v6', 'C20', 'Farmacia alterna: establecimiento, inyectología y glicemia', 'Condiciones propias del establecimiento farmacéutico, que la Res. 3100 no cubre porque se autoriza y no se habilita.', 'Cruce Res. 3100 vs Res. 1403 y 2955', NULL, NULL, NULL, ARRAY['FA']::text[], 'Res. 1403/2007 Manual T.I Cap.V; Res. 2955/2007 Art. 3 · cruce', 21) RETURNING id)
INSERT INTO chk_items (componente_id, codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden)
SELECT c.id, v.* FROM c CROSS JOIN (VALUES
    ('CR-02', 'Droguería: áreas de la farmacia-droguería, sin magistrales ni materias primas', 'Cumple si · la droguería cuenta con las áreas del num. 1.1.2 del Cap. V (administrativa; recepción y almacenamiento provisional de medicamentos, dispositivos y productos autorizados; almacenamiento de medicamentos y dispositivos; productos autorizados separados; control especial; vencidos o deteriorados; fitoterapéuticos, si los vende; dispensación; cuarentena; residuos). No se le exigen el área de magistrales, el área de materias primas ni la recepción de materia prima.', 'Res. 2955/2007 Art. 3 (p.3), que modifica Res. 1403/2007 Manual T.I Cap.V num. 2.1; Res. 1403/2007 Manual T.I Cap.V num. 1.1.2 (p.35)', 'cruce', 'La droguería contará básicamente con la infraestructura del num. 1.1 del Cap. II y con las áreas del num. 1.1.2 del Cap. V, con excepción de las de los literales b) y d) y sin la sección de recepción y almacenamiento provisional de materia prima del literal c).', 'Constatación física.', '', 'Solo si la farmacia alterna es droguería', NULL, NULL::jsonb, NULL::jsonb, 1),
    ('P17-01', 'La FD/droguería solo ofrece los procedimientos permitidos (inyectología y glicemia)', 'Cumple si · el establecimiento no ofrece al público procedimientos distintos de inyectología y monitoreo de glicemia con equipo por punción.', 'Res. 1403/2007 Manual T.I Cap.V num. 1 lit. b (p.34); num. 2 lit. b (p.40)', 'v2', 'La farmacia-droguería o droguería solo presta los servicios inherentes a los procesos del servicio farmacéutico que según la normatividad vigente puede realizar; como procedimientos al público solo puede ofrecer inyectología y monitoreo de glicemia con equipo por punción.', 'No definida en la norma', 'Aplica solo a farmacias-droguerías y droguerías', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 2),
    ('P17-03', 'Formación y entrenamiento de quien administra medicamentos inyectables', 'Cumple si · quien administra inyectables tiene soportes de formación académica y entrenamiento que lo autoricen para ello.', 'Dec. 780/2016 Art. 2.5.3.10.21 num. 2 (p. 294); Res. 1403/2007 Manual T.I Cap.V num. 1.5.2 (p.37)', 'v2', 'El encargado de administrar el medicamento inyectable cuenta con formación académica y entrenamiento que lo autorice para ello, de conformidad con las normas vigentes sobre la materia.', 'No definida en la norma (se desprende: soportes de formación académica y entrenamiento)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen inyectología', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 3),
    ('P17-04', 'Normas de limpieza, bioseguridad, residuos y manual técnico (inyectología/glicemia)', 'Cumple si · existen las normas de limpieza y desinfección de áreas, de bioseguridad y de manejo de residuos y el manual de procedimientos técnicos, y se evidencia su cumplimiento.', 'Dec. 780/2016 Art. 2.5.3.10.21 num. 3 y 2.5.3.10.22 num. 3 (p. 294-295); Res. 1403/2007 Manual T.I Cap.V num. 1.5.3 (p.37); num. 1.6.3 (p.38)', 'v2', 'Para los procedimientos de inyectología y de monitoreo de glicemia, el establecimiento cuenta y cumple con normas sobre limpieza y desinfección de áreas, bioseguridad y manejo de residuos, y con manual de procedimientos técnicos.', 'Normas documentadas de limpieza y desinfección de áreas, bioseguridad y manejo de residuos; manual de procedimientos técnicos (explícito); evidencia de su aplicación', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen inyectología y/o monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 4),
    ('P17-05', 'No se administran medicamentos por vía intravenosa ni se hacen pruebas de sensibilidad', 'Cumple si · no se evidencia administración de medicamentos por vía intravenosa ni práctica de pruebas de sensibilidad.', 'Dec. 780/2016 Art. 2.5.3.10.21 num. 4 (p. 294); Res. 1403/2007 Manual T.I Cap.V num. 1.5.4 (p.37)', 'v2', 'En el procedimiento de inyectología no se administran medicamentos por vía intravenosa ni se practican pruebas de sensibilidad.', 'No definida en la norma', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen inyectología', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 5),
    ('P17-06', 'Prescripción médica exigida para toda aplicación intramuscular', 'Cumple si · toda administración intramuscular se realiza previa presentación de la prescripción médica.', 'Dec. 780/2016 Art. 2.5.3.10.21 num. 5 (p. 294); Res. 1403/2007 Manual T.I Cap.V num. 1.5.5 (p.37)', 'v2', 'Se solicita la prescripción médica, requisito indispensable para la administración de cualquier medicamento por vía intramuscular.', 'Prescripción médica presentada para cada aplicación (la norma no exige conservar copia ni registrar la aplicación)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen inyectología', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 6),
    ('P17-07', 'Glicemia solo si se ofrece inyectología y el director técnico es QF o TRF', 'Cumple si · el establecimiento ofrece inyectología y su director técnico es químico farmacéutico o tecnólogo en regencia de farmacia.', 'Dec. 780/2016 Art. 2.5.3.10.22 inc. 1 (p. 294); Res. 1403/2007 Manual T.I Cap.V num. 1.6 (p.37)', 'v2', 'La farmacia-droguería o droguería solo ofrece el monitoreo de glicemia con equipo por punción si también ofrece el procedimiento de inyectología y su director técnico es químico farmacéutico o tecnólogo en regencia de farmacia.', 'No definida en la norma (se desprende: título del director técnico)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 7),
    ('P17-08', 'Entrenamiento del director técnico y del ejecutor del monitoreo de glicemia', 'Cumple si · existen soportes de entrenamiento y de instrucciones del fabricante o distribuidor para el director técnico y para quien realiza el monitoreo.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 2 (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.2 (p.38)', 'v2', 'Tanto el director técnico como la persona encargada de realizar el monitoreo de glicemia están suficientemente entrenados y han recibido claras instrucciones por parte del fabricante o distribuidor.', 'No definida en la norma (se desprende: soportes de entrenamiento e instrucciones del fabricante o distribuidor)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 8),
    ('P17-09', 'Personal de glicemia cumple bioseguridad, aseo personal, asepsia y manejo de residuos', 'Cumple si · en la observación del procedimiento las prácticas del personal son conformes con las normas de bioseguridad, aseo personal, asepsia del sitio y manejo de residuos.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 2 (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.2 (p.38)', 'v2', 'El director técnico y la persona encargada del monitoreo de glicemia cumplen las normas establecidas sobre bioseguridad, aseo personal, asepsia del sitio y manejo de residuos.', 'No definida en la norma (observación de prácticas)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 9),
    ('P17-10', 'Tiras reactivas vigentes y almacenadas en las condiciones del fabricante', 'Cumple si · no hay tiras reactivas vencidas y se almacenan en las condiciones indicadas por el fabricante.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. d (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.1 lit. d (p.38)', 'v2', 'Se conserva la fecha de vencimiento vigente de las tiras reactivas y las condiciones de almacenamiento previstas por el fabricante.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 10),
    ('P17-11', 'Libro de registro diario de pacientes, resultados y calibración del glucómetro', 'Cumple si · el libro registra diariamente los pacientes atendidos y sus resultados y contiene el registro de la calibración del equipo.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. h (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.1 lit. h (p.38)', 'v2', 'Cuenta con un libro de registro diario de pacientes y de resultados del monitoreo de glicemia, en el que además se encuentra registrada la calibración del equipo.', 'Libro de registro diario (explícito)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 11),
    ('P17-12', 'Resultados entregados por escrito con nombre del ejecutor y sin interpretación', 'Cumple si · los resultados se entregan por escrito, con el nombre de quien realizó el procedimiento y sin interpretación alguna.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. i (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.1 lit. i (p.38)', 'v2', 'Los resultados se entregan al paciente en forma escrita con el nombre de la persona que realizó el procedimiento, sin hacer ningún tipo de interpretación.', 'Resultado escrito entregado al paciente (explícito)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 12),
    ('P17-13', 'Archivo de los registros de glicemia por el tiempo de la normatividad vigente', 'Cumple si · los registros del monitoreo están archivados y disponibles; el tiempo mínimo de conservación no está definido en la norma.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. j (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.1 lit. j (p.38)', 'v2', 'Los registros del monitoreo de glicemia se mantienen en archivo durante el tiempo contemplado en la normatividad vigente.', 'Archivo de registros (explícito)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 13),
    ('P17-14', 'La prueba de glicemia no se usa como diagnóstico, tratamiento ni para cambiar terapia', 'Cumple si · no se evidencia que el establecimiento presente o use la prueba como diagnóstico, tratamiento o seguimiento, como sustituto del laboratorio clínico, ni para recomendar cambios de tratamiento sin autorización del médico tratante.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 4 (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.4 (p.39)', 'v2', 'Las pruebas de glicemia no se constituyen en actividades de apoyo diagnóstico, de tratamiento ni de seguimiento de la patología, no reemplazan las pruebas del laboratorio clínico y no sirven para cambio de tratamiento sin previa autorización del médico tratante.', 'No definida en la norma', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 14),
    ('I08-01', 'Sección de inyectología especial e independiente, con privacidad y comodidad', 'Cumple si · existe sección independiente destinada a inyectología que ofrece privacidad y comodidad.', 'Dec. 780/2016 Art. 2.5.3.10.21 num. 1 lit. a (p. 294); Res. 1403/2007 Manual T.I Cap.V num. 1.5.1 lit. a (p.37)', 'v2', 'Cuenta con una sección especial e independiente que ofrece privacidad y comodidad para el administrador y el paciente.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen inyectología', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 15),
    ('I08-02', 'Lavamanos en el mismo sitio o cercano a las áreas de inyectología y glicemia', 'Cumple si · hay lavamanos funcional en el mismo sitio o en un sitio cercano al área donde se realizan los procedimientos.', 'Dec. 780/2016 Art. 2.5.3.10.21 num. 1 lit. a (p. 294); Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. e (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.5.1 lit. a (p.37); num. 1.6.1 lit. e (p.38)', 'v2', 'Las secciones o áreas de inyectología y de monitoreo de glicemia cuentan con un lavamanos en el mismo sitio o en sitio cercano.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen inyectología y/o monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 16),
    ('I08-03', 'Dotación mínima de inyectología', 'Cumple si · dispone de camilla, escalerilla, mesa auxiliar, jeringas desechables, recipiente algodonero, cubetas y toallas desechables, y de los demás materiales necesarios para el procedimiento.', 'Dec. 780/2016 Art. 2.5.3.10.21 num. 1 lit. b (p. 294); Dec. 780/2016 Art. 2.5.3.10.21 num. 1 lit. c (p. 294); Dec. 780/2016 Art. 2.5.3.10.21 num. 1 lit. d (p. 294); Dec. 780/2016 Art. 2.5.3.10.21 num. 1 lit. e (p. 294); Res. 1403/2007 Manual T.I Cap.V num. 1.5.1 lit. b (p.37); Res. 1403/2007 Manual T.I Cap.V num. 1.5.1 lit. c (p.37); Res. 1403/2007 Manual T.I Cap.V num. 1.5.1 lit. d (p.37); num. 1.6.1 lit. f (p.38); Res. 1403/2007 Manual T.I Cap.V num. 1.5.1 lit. e (p.37); num. 1.6.1 lit. g (p.38)', 'v2', 'Tiene camilla, escalerilla y mesa auxiliar; jeringas desechables, recipiente algodonero y cubetas; toallas desechables; y los demás materiales y dotación necesaria para el procedimiento de inyectología.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen inyectología', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 17),
    ('I08-04', 'Área de glicemia especial, independiente, dotada, con privacidad y comodidad', 'Cumple si · existe área independiente (propia o la de inyectología), dotada y con privacidad y comodidad para el procedimiento de glicemia.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. a (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.1 lit. a (p.38)', 'v2', 'Cuenta con área especial e independiente, debidamente dotada, que ofrece privacidad y comodidad para el paciente y para quien aplica la prueba; puede ser la misma utilizada para inyectología.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 18),
    ('I08-05', 'Iluminación y ventilación adecuadas en el área de glicemia', 'Cumple si · el área cuenta con iluminación y ventilación (natural y/o artificial) adecuadas para el procedimiento.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. a (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.1 lit. a (p.38)', 'v2', 'El área de monitoreo de glicemia tiene adecuada iluminación y ventilación natural y/o artificial.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 19),
    ('I08-06', 'Temperatura del área de glicemia entre 15 y 25 °C', 'Cumple si · la temperatura medida en el área durante la visita está entre 15 °C y 25 °C.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. a (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.1 lit. a (p.38)', 'v2', 'La temperatura del área de monitoreo de glicemia está entre 15 y 25 °C.', 'No definida en la norma (constatación física: medición de la temperatura del área durante la visita)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 20),
    ('I08-07', 'Glucómetro con registro sanitario INVIMA y debidamente calibrado', 'Cumple si · el equipo tiene registro sanitario del INVIMA y existe evidencia de su calibración.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. b (p. 295); Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. b y h (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.1 lit. b (p.38)', 'v2', 'El equipo de monitoreo de glicemia cuenta con registro sanitario del INVIMA y está debidamente calibrado.', 'Registro sanitario INVIMA del equipo; registro de la calibración en el libro de registro diario (ver P18)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 21),
    ('I08-08', 'Microlancetas registradas conforme al Decreto 4725 de 2005', 'Cumple si · las microlancetas en uso cuentan con el registro exigido por el Decreto 4725 de 2005.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. b (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.1 lit. b (p.38)', 'v2', 'Las microlancetas utilizadas están registradas de acuerdo con lo establecido en el Decreto 4725 de 2005 y las normas que lo modifiquen, adicionen o sustituyan.', 'Registro de las microlancetas (se desprende del requisito)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 22),
    ('I08-09', 'Tiras reactivas con registro sanitario INVIMA, de uso individual por paciente', 'Cumple si · las tiras reactivas tienen registro sanitario del INVIMA y se usa una tira por paciente.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. c (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.6.1 lit. c (p.38)', 'v2', 'Cuenta con tiras reactivas con registro sanitario del INVIMA, para cada paciente individual.', 'Registro sanitario INVIMA de las tiras reactivas (se desprende del requisito)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 23),
    ('I08-10', 'Dotación mínima para glicemia, incluido lo requerido para manejo de desechos', 'Cumple si · dispone de toallas desechables, recipiente algodonero y de los materiales necesarios para el procedimiento y para el manejo de desechos.', 'Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. f (p. 295); Dec. 780/2016 Art. 2.5.3.10.22 num. 1 lit. g (p. 295); Res. 1403/2007 Manual T.I Cap.V num. 1.5.1 lit. d (p.37); num. 1.6.1 lit. f (p.38); Res. 1403/2007 Manual T.I Cap.V num. 1.5.1 lit. e (p.37); num. 1.6.1 lit. g (p.38)', 'v2', 'Tiene toallas desechables y recipiente algodonero, y cuenta con los materiales y demás dotación necesaria para el procedimiento, incluyendo lo requerido para el manejo de desechos.', 'No definida en la norma (constatación física)', 'Aplica solo a farmacias-droguerías y droguerías que ofrecen monitoreo de glicemia con equipo por punción', 'Solo si la farmacia alterna ofrece inyectología o glicemia', NULL, NULL::jsonb, NULL::jsonb, 24)
) AS v(codigo, punto, criterio, fuente, origen, requisito, evidencia, aplica, condicion, prioridad, medicion, subvalidacion, orden);

